-- ----------------------------
-- Table structure for qrtz_job_details
-- ----------------------------
DROP TABLE IF EXISTS `qrtz_job_details`;
CREATE TABLE `qrtz_job_details` (
  `SCHED_NAME` varchar(120) NOT NULL,
  `JOB_NAME` varchar(190) NOT NULL,
  `JOB_GROUP` varchar(190) NOT NULL,
  `DESCRIPTION` varchar(250) DEFAULT NULL,
  `JOB_CLASS_NAME` varchar(250) NOT NULL,
  `IS_DURABLE` varchar(1) NOT NULL,
  `IS_NONCONCURRENT` varchar(1) NOT NULL,
  `IS_UPDATE_DATA` varchar(1) NOT NULL,
  `REQUESTS_RECOVERY` varchar(1) NOT NULL,
  `JOB_DATA` blob,
  PRIMARY KEY (`SCHED_NAME`,`JOB_NAME`,`JOB_GROUP`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of qrtz_job_details
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for qrtz_triggers
-- ----------------------------
DROP TABLE IF EXISTS `qrtz_triggers`;
CREATE TABLE `qrtz_triggers` (
  `SCHED_NAME` varchar(120) NOT NULL,
  `TRIGGER_NAME` varchar(190) NOT NULL,
  `TRIGGER_GROUP` varchar(190) NOT NULL,
  `JOB_NAME` varchar(190) NOT NULL,
  `JOB_GROUP` varchar(190) NOT NULL,
  `DESCRIPTION` varchar(250) DEFAULT NULL,
  `NEXT_FIRE_TIME` bigint DEFAULT NULL,
  `PREV_FIRE_TIME` bigint DEFAULT NULL,
  `PRIORITY` int DEFAULT NULL,
  `TRIGGER_STATE` varchar(16) NOT NULL,
  `TRIGGER_TYPE` varchar(8) NOT NULL,
  `START_TIME` bigint NOT NULL,
  `END_TIME` bigint DEFAULT NULL,
  `CALENDAR_NAME` varchar(190) DEFAULT NULL,
  `MISFIRE_INSTR` smallint DEFAULT NULL,
  `JOB_DATA` blob,
  PRIMARY KEY (`SCHED_NAME`,`TRIGGER_NAME`,`TRIGGER_GROUP`) USING BTREE,
  KEY `SCHED_NAME` (`SCHED_NAME`,`JOB_NAME`,`JOB_GROUP`) USING BTREE,
  CONSTRAINT `qrtz_triggers_ibfk_1` FOREIGN KEY (`SCHED_NAME`, `JOB_NAME`, `JOB_GROUP`) REFERENCES `qrtz_job_details` (`SCHED_NAME`, `JOB_NAME`, `JOB_GROUP`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of qrtz_triggers
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_album
-- ----------------------------
DROP TABLE IF EXISTS `sys_album`;
CREATE TABLE `sys_album` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) DEFAULT NULL COMMENT '相册名',
  `description` varchar(64) DEFAULT NULL COMMENT '相册描述',
  `cover` varchar(255) DEFAULT NULL COMMENT '封面URL',
  `is_lock` int DEFAULT '0' COMMENT '是否加密 0：否 1：是',
  `password` varchar(255) DEFAULT NULL COMMENT '密码',
  `sort` int DEFAULT NULL COMMENT '排序',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='相册';

-- ----------------------------
-- Records of sys_album
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_article
-- ----------------------------
DROP TABLE IF EXISTS `sys_article`;
CREATE TABLE `sys_article` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int NOT NULL COMMENT '用户id',
  `title` varchar(150) NOT NULL DEFAULT '' COMMENT '文章标题',
  `cover` varchar(200) DEFAULT NULL COMMENT '文章封面地址',
  `summary` varchar(255) NOT NULL DEFAULT '' COMMENT '文章简介',
  `content` mediumtext COMMENT '文章内容',
  `content_md` mediumtext COMMENT '文章内容md格式',
  `read_type` int DEFAULT '1' COMMENT '阅读方式 0无需验证 1：评论阅读 2：点赞阅读 3：扫码阅读',
  `is_stick` int DEFAULT '0' COMMENT '是否置顶 0否 1是',
  `status` int DEFAULT '0' COMMENT '状态 0：下架 1：发布',
  `is_original` int DEFAULT '1' COMMENT '是否原创  0：转载 1:原创',
  `is_carousel` int DEFAULT '0' COMMENT '是否首页轮播',
  `is_recommend` int DEFAULT '0' COMMENT '是否推荐',
  `original_url` varchar(3000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '转载地址',
  `quantity` bigint DEFAULT '0' COMMENT '文章阅读量',
  `keywords` varchar(200) DEFAULT NULL COMMENT '关键词',
  `ai_describe` mediumtext COMMENT 'Ai生成的简短描述',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  FULLTEXT KEY `title` (`title`) /*!50100 WITH PARSER `ngram` */ 
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='博客文章表';

-- ----------------------------
-- Records of sys_article
-- ----------------------------
BEGIN;
INSERT INTO `sys_article` (`id`, `user_id`, `title`, `cover`, `summary`, `content`, `content_md`, `read_type`, `is_stick`, `status`, `is_original`, `is_carousel`, `is_recommend`, `original_url`, `quantity`, `keywords`, `ai_describe`, `create_time`, `update_time`) VALUES (329, 1, 'MySQL复杂查询优化实战：从多表关联到子查询的性能突破', 'http://sycexovyo.hn-bkt.clouddn.com//blog20250626/article-cover/18_d72a6be0479f4c42a171034afba11188.jpeg', 'MySQL复杂查询优化实战：从多表关联到子查询的性能突破', '<h3><a id=\"_0\"></a>一、复杂查询性能瓶颈分析与优化框架</h3>\n<p>在实际业务场景中，MySQL查询性能问题往往源于多表关联（JOIN）和子查询的不当使用。以电商订单系统为例，当需要查询&quot;近30天内购买过电子产品的用户及其订单详情&quot;时，若直接使用嵌套子查询或无序JOIN，可能导致查询耗时从毫秒级飙升至秒级。这类问题的核心矛盾在于：<strong>数据库引擎对复杂查询的执行计划生成存在天然局限性，需要通过人为干预优化执行路径</strong>。</p>\n<p>优化的核心框架可拆解为三步：</p>\n<ol>\n<li><strong>定位性能痛点</strong> ：通过<code>EXPLAIN</code>分析执行计划，识别<code>Using filesort</code>、<code>Using temporary</code>等低效操作</li>\n<li><strong>重构查询结构</strong>：将子查询转换为JOIN、调整表关联顺序、拆分复杂查询</li>\n<li><strong>索引与统计信息优化</strong>：建立复合索引、更新表统计信息</li>\n</ol>\n<h3><a id=\"_10\"></a>二、多表关联查询的优化策略与实战</h3>\n<h4><a id=\"1_JOIN_12\"></a>1. JOIN顺序优化：基于成本估算的表关联策略</h4>\n<p>MySQL的JOIN执行遵循&quot;嵌套循环连接&quot;（Nested Loop Join）机制，驱动表的选择直接影响IO次数。以订单表、用户表、商品表的三表关联为例：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始查询：错误的JOIN顺序导致全表扫描</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> o.order_id, u.username, p.product_name\n<span class=\"hljs-keyword\">FROM</span> orders o\n<span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> o.user_id <span class=\"hljs-operator\">=</span> u.user_id\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> o.product_id <span class=\"hljs-operator\">=</span> p.product_id\n<span class=\"hljs-keyword\">WHERE</span> o.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span> <span class=\"hljs-keyword\">AND</span> p.category <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;电子产品&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 优化后：先过滤再关联，以orders表为驱动表</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> o.order_id, u.username, p.product_name\n<span class=\"hljs-keyword\">FROM</span> orders o\n<span class=\"hljs-comment\">-- 先对orders表建立时间索引</span>\n<span class=\"hljs-keyword\">WHERE</span> o.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n<span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> o.user_id <span class=\"hljs-operator\">=</span> u.user_id\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> o.product_id <span class=\"hljs-operator\">=</span> p.product_id <span class=\"hljs-keyword\">AND</span> p.category <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;电子产品&#x27;</span>;\n</code></div></pre>\n<p><strong>执行计划对比</strong> ：<br />\n优化前：orders表扫描10万行，users和products表均全表扫描，总IO约20万次<br />\n优化后：orders表通过索引过滤至1万行，users和products表通过主键关联，总IO降至1.2万次</p>\n<h4><a id=\"2_JOIN_37\"></a>2. 复合索引与JOIN条件优化</h4>\n<p>当JOIN条件涉及多个字段时，复合索引的顺序至关重要。以订单明细表与商品表的关联为例：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 表结构</span>\n<span class=\"hljs-keyword\">CREATE</span> <span class=\"hljs-keyword\">TABLE</span> order_items (\n  order_id <span class=\"hljs-type\">INT</span>,\n  product_id <span class=\"hljs-type\">INT</span>,\n  quantity <span class=\"hljs-type\">INT</span>,\n  <span class=\"hljs-comment\">-- 错误的索引顺序：未按JOIN条件顺序创建</span>\n  KEY idx_order_product (order_id, product_id)\n);\n\n<span class=\"hljs-keyword\">CREATE</span> <span class=\"hljs-keyword\">TABLE</span> products (\n  product_id <span class=\"hljs-type\">INT</span> <span class=\"hljs-keyword\">PRIMARY</span> KEY,\n  category <span class=\"hljs-type\">VARCHAR</span>(<span class=\"hljs-number\">50</span>),\n  price <span class=\"hljs-type\">DECIMAL</span>(<span class=\"hljs-number\">10</span>,<span class=\"hljs-number\">2</span>)\n);\n\n<span class=\"hljs-comment\">-- 低效查询：JOIN条件与索引顺序不一致</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> oi.order_id, p.category\n<span class=\"hljs-keyword\">FROM</span> order_items oi\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> oi.product_id <span class=\"hljs-operator\">=</span> p.product_id <span class=\"hljs-keyword\">AND</span> oi.order_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">12345</span>;\n\n<span class=\"hljs-comment\">-- 优化方案：重建复合索引并调整JOIN条件顺序</span>\n<span class=\"hljs-keyword\">ALTER</span> <span class=\"hljs-keyword\">TABLE</span> order_items <span class=\"hljs-keyword\">DROP</span> KEY idx_order_product;\n<span class=\"hljs-keyword\">ALTER</span> <span class=\"hljs-keyword\">TABLE</span> order_items <span class=\"hljs-keyword\">ADD</span> KEY idx_product_order (product_id, order_id);\n\n<span class=\"hljs-comment\">-- 优化后查询：条件顺序与索引一致</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> oi.order_id, p.category\n<span class=\"hljs-keyword\">FROM</span> order_items oi\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> oi.product_id <span class=\"hljs-operator\">=</span> p.product_id <span class=\"hljs-keyword\">AND</span> oi.order_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">12345</span>;\n</code></div></pre>\n<p><strong>索引原理解析</strong> ：<br />\n复合索引<code>idx_product_order</code>按<code>product_id</code>和<code>order_id</code>排序，当查询条件为<code>product_id = ? AND order_id = ?</code>时，可直接通过B+树定位，避免回表查询。而原索引<code>idx_order_product</code>在查询时只能利用<code>order_id</code>过滤，<code>product_id</code>条件需二次扫描。</p>\n<h4><a id=\"3_JOIN_75\"></a>3. 大表JOIN的分片处理</h4>\n<p>当关联表数据量超过千万级时，直接JOIN可能导致内存溢出。可采用&quot;分批次JOIN&quot;策略，以日志表与用户表的关联为例：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始查询：千万级日志表与百万级用户表直接JOIN</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> l.user_id, u.username, <span class=\"hljs-built_in\">COUNT</span>(l.id) <span class=\"hljs-keyword\">as</span> log_count\n<span class=\"hljs-keyword\">FROM</span> user_logs l\n<span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> l.user_id <span class=\"hljs-operator\">=</span> u.user_id\n<span class=\"hljs-keyword\">WHERE</span> l.log_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-01-01&#x27;</span>\n<span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> l.user_id;\n\n<span class=\"hljs-comment\">-- 优化方案：分批次查询用户ID再关联</span>\n<span class=\"hljs-comment\">-- 1. 先查询符合条件的用户ID范围</span>\n<span class=\"hljs-keyword\">SELECT</span> user_id <span class=\"hljs-keyword\">INTO</span> <span class=\"hljs-variable\">@min</span>_id <span class=\"hljs-keyword\">FROM</span> users <span class=\"hljs-keyword\">ORDER</span> <span class=\"hljs-keyword\">BY</span> user_id LIMIT <span class=\"hljs-number\">1</span>;\n<span class=\"hljs-keyword\">SELECT</span> user_id <span class=\"hljs-keyword\">INTO</span> <span class=\"hljs-variable\">@max</span>_id <span class=\"hljs-keyword\">FROM</span> users <span class=\"hljs-keyword\">ORDER</span> <span class=\"hljs-keyword\">BY</span> user_id <span class=\"hljs-keyword\">DESC</span> LIMIT <span class=\"hljs-number\">1</span>;\n\n<span class=\"hljs-comment\">-- 2. 定义批次大小</span>\n<span class=\"hljs-keyword\">SET</span> <span class=\"hljs-variable\">@batch</span>_size <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">10000</span>;\n<span class=\"hljs-keyword\">SET</span> <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-variable\">@min</span>_id;\n\n<span class=\"hljs-comment\">-- 3. 循环分批次查询</span>\n<span class=\"hljs-keyword\">CREATE</span> TEMPORARY <span class=\"hljs-keyword\">TABLE</span> temp_results (\n  user_id <span class=\"hljs-type\">INT</span>,\n  username <span class=\"hljs-type\">VARCHAR</span>(<span class=\"hljs-number\">50</span>),\n  log_count <span class=\"hljs-type\">INT</span>\n);\n\nWHILE <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-operator\">&lt;</span> <span class=\"hljs-variable\">@max</span>_id DO\n  <span class=\"hljs-keyword\">INSERT</span> <span class=\"hljs-keyword\">INTO</span> temp_results\n  <span class=\"hljs-keyword\">SELECT</span> l.user_id, u.username, <span class=\"hljs-built_in\">COUNT</span>(l.id)\n  <span class=\"hljs-keyword\">FROM</span> user_logs l\n  <span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> l.user_id <span class=\"hljs-operator\">=</span> u.user_id\n  <span class=\"hljs-keyword\">WHERE</span> l.log_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-01-01&#x27;</span>\n  <span class=\"hljs-keyword\">AND</span> u.user_id <span class=\"hljs-keyword\">BETWEEN</span> <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-keyword\">AND</span> <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-operator\">+</span> <span class=\"hljs-variable\">@batch</span>_size <span class=\"hljs-operator\">-</span> <span class=\"hljs-number\">1</span>\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> l.user_id;\n  \n  <span class=\"hljs-keyword\">SET</span> <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-variable\">@current</span>_id <span class=\"hljs-operator\">+</span> <span class=\"hljs-variable\">@batch</span>_size;\n<span class=\"hljs-keyword\">END</span> WHILE;\n\n<span class=\"hljs-comment\">-- 4. 输出最终结果</span>\n<span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-operator\">*</span> <span class=\"hljs-keyword\">FROM</span> temp_results;\n</code></div></pre>\n<p><strong>性能对比</strong> ：<br />\n直接JOIN：耗时120秒，内存占用峰值2.8GB<br />\n分批次JOIN：总耗时28秒，单次批次内存占用&lt;500MB</p>\n<h3><a id=\"JOIN_123\"></a>三、子查询优化：从嵌套到JOIN的转换艺术</h3>\n<h4><a id=\"1_JOIN_125\"></a>1. 标量子查询转换为JOIN</h4>\n<p>标量子查询（返回单个值）常见于&quot;查询订单中金额最高的商品&quot;场景，但其嵌套查询结构会导致多次执行：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始标量子查询：每次查询都触发子查询</span>\n<span class=\"hljs-keyword\">SELECT</span> order_id, product_id, price,\n  (<span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-built_in\">MAX</span>(price) <span class=\"hljs-keyword\">FROM</span> order_items <span class=\"hljs-keyword\">WHERE</span> order_id <span class=\"hljs-operator\">=</span> o.order_id) <span class=\"hljs-keyword\">as</span> max_price\n<span class=\"hljs-keyword\">FROM</span> order_items o\n<span class=\"hljs-keyword\">WHERE</span> order_id <span class=\"hljs-keyword\">IN</span> (<span class=\"hljs-number\">1001</span>, <span class=\"hljs-number\">1002</span>, <span class=\"hljs-number\">1003</span>);\n\n<span class=\"hljs-comment\">-- 优化方案：转换为自JOIN</span>\n<span class=\"hljs-keyword\">SELECT</span> o1.order_id, o1.product_id, o1.price, o2.max_price\n<span class=\"hljs-keyword\">FROM</span> order_items o1\n<span class=\"hljs-keyword\">JOIN</span> (\n  <span class=\"hljs-keyword\">SELECT</span> order_id, <span class=\"hljs-built_in\">MAX</span>(price) <span class=\"hljs-keyword\">as</span> max_price\n  <span class=\"hljs-keyword\">FROM</span> order_items\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> order_id\n) o2 <span class=\"hljs-keyword\">ON</span> o1.order_id <span class=\"hljs-operator\">=</span> o2.order_id\n<span class=\"hljs-keyword\">WHERE</span> o1.order_id <span class=\"hljs-keyword\">IN</span> (<span class=\"hljs-number\">1001</span>, <span class=\"hljs-number\">1002</span>, <span class=\"hljs-number\">1003</span>);\n</code></div></pre>\n<p><strong>执行计划分析</strong> ：<br />\n子查询版本：外层查询3行，每行触发一次子查询（扫描100行/次），总扫描300行<br />\nJOIN版本：子查询先聚合生成临时表（3行），再与主表JOIN，总扫描103行</p>\n<h4><a id=\"2_EXISTSIN_151\"></a>2. EXISTS子查询与IN子查询的选择与优化</h4>\n<p>在&quot;查询有未支付订单的用户&quot;场景中，EXISTS与IN的选择直接影响性能：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 场景：users表10万行，orders表100万行</span>\n<span class=\"hljs-keyword\">CREATE</span> <span class=\"hljs-keyword\">TABLE</span> users (user_id <span class=\"hljs-type\">INT</span> <span class=\"hljs-keyword\">PRIMARY</span> KEY, username <span class=\"hljs-type\">VARCHAR</span>(<span class=\"hljs-number\">50</span>));\n<span class=\"hljs-keyword\">CREATE</span> <span class=\"hljs-keyword\">TABLE</span> orders (order_id <span class=\"hljs-type\">INT</span>, user_id <span class=\"hljs-type\">INT</span>, status <span class=\"hljs-type\">VARCHAR</span>(<span class=\"hljs-number\">20</span>), KEY idx_user_status (user_id, status));\n\n<span class=\"hljs-comment\">-- 错误用法：IN子查询导致全表扫描</span>\n<span class=\"hljs-keyword\">SELECT</span> u.user_id, u.username\n<span class=\"hljs-keyword\">FROM</span> users u\n<span class=\"hljs-keyword\">WHERE</span> u.user_id <span class=\"hljs-keyword\">IN</span> (\n  <span class=\"hljs-keyword\">SELECT</span> o.user_id <span class=\"hljs-keyword\">FROM</span> orders o <span class=\"hljs-keyword\">WHERE</span> o.status <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;未支付&#x27;</span>\n);\n\n<span class=\"hljs-comment\">-- 优化方案：EXISTS结合索引</span>\n<span class=\"hljs-keyword\">SELECT</span> u.user_id, u.username\n<span class=\"hljs-keyword\">FROM</span> users u\n<span class=\"hljs-keyword\">WHERE</span> <span class=\"hljs-keyword\">EXISTS</span> (\n  <span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-number\">1</span> <span class=\"hljs-keyword\">FROM</span> orders o \n  <span class=\"hljs-keyword\">WHERE</span> o.user_id <span class=\"hljs-operator\">=</span> u.user_id <span class=\"hljs-keyword\">AND</span> o.status <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;未支付&#x27;</span>\n);\n\n<span class=\"hljs-comment\">-- 更优方案：JOIN + 聚合</span>\n<span class=\"hljs-keyword\">SELECT</span> u.user_id, u.username\n<span class=\"hljs-keyword\">FROM</span> users u\n<span class=\"hljs-keyword\">JOIN</span> orders o <span class=\"hljs-keyword\">ON</span> u.user_id <span class=\"hljs-operator\">=</span> o.user_id <span class=\"hljs-keyword\">AND</span> o.status <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;未支付&#x27;</span>\n<span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> u.user_id, u.username;\n</code></div></pre>\n<p><strong>性能测试数据</strong> ：<br />\nIN子查询：耗时18秒，扫描orders表100万行<br />\nEXISTS子查询：耗时3.2秒，利用<code>idx_user_status</code>索引扫描20万行<br />\nJOIN方案：耗时1.8秒，通过索引过滤后JOIN结果集10万行</p>\n<h4><a id=\"3_WITH_RECURSIVE_187\"></a>3. WITH RECURSIVE优化递归子查询</h4>\n<p>在处理层级数据（如部门架构）时，递归子查询可能导致性能骤降，可通过CTE（Common Table Expression）优化：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始递归子查询：查询部门及其所有子部门</span>\n<span class=\"hljs-keyword\">SELECT</span> dept_id, parent_id, dept_name\n<span class=\"hljs-keyword\">FROM</span> departments\n<span class=\"hljs-keyword\">WHERE</span> dept_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">1001</span>\n<span class=\"hljs-keyword\">UNION</span> <span class=\"hljs-keyword\">ALL</span>\n<span class=\"hljs-keyword\">SELECT</span> d.dept_id, d.parent_id, d.dept_name\n<span class=\"hljs-keyword\">FROM</span> departments d\n<span class=\"hljs-keyword\">JOIN</span> (\n  <span class=\"hljs-keyword\">SELECT</span> dept_id, parent_id, dept_name\n  <span class=\"hljs-keyword\">FROM</span> departments\n  <span class=\"hljs-keyword\">WHERE</span> dept_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">1001</span>\n) sub <span class=\"hljs-keyword\">ON</span> d.parent_id <span class=\"hljs-operator\">=</span> sub.dept_id;\n\n<span class=\"hljs-comment\">-- 优化方案：WITH RECURSIVE CTE</span>\n<span class=\"hljs-keyword\">WITH</span> <span class=\"hljs-keyword\">RECURSIVE</span> dept_hierarchy <span class=\"hljs-keyword\">AS</span> (\n  <span class=\"hljs-comment\">-- 初始查询：根部门</span>\n  <span class=\"hljs-keyword\">SELECT</span> dept_id, parent_id, dept_name, <span class=\"hljs-number\">1</span> <span class=\"hljs-keyword\">as</span> level\n  <span class=\"hljs-keyword\">FROM</span> departments\n  <span class=\"hljs-keyword\">WHERE</span> dept_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">1001</span>\n  \n  <span class=\"hljs-keyword\">UNION</span> <span class=\"hljs-keyword\">ALL</span>\n  \n  <span class=\"hljs-comment\">-- 递归查询：子部门</span>\n  <span class=\"hljs-keyword\">SELECT</span> d.dept_id, d.parent_id, d.dept_name, dh.level <span class=\"hljs-operator\">+</span> <span class=\"hljs-number\">1</span>\n  <span class=\"hljs-keyword\">FROM</span> departments d\n  <span class=\"hljs-keyword\">JOIN</span> dept_hierarchy dh <span class=\"hljs-keyword\">ON</span> d.parent_id <span class=\"hljs-operator\">=</span> dh.dept_id\n)\n<span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-operator\">*</span> <span class=\"hljs-keyword\">FROM</span> dept_hierarchy;\n</code></div></pre>\n<p><strong>执行效率对比</strong> ：<br />\n原始递归：耗时7.5秒，重复扫描父部门数据<br />\nCTE优化：耗时1.2秒，利用CTE缓存中间结果，避免重复查询</p>\n<h3><a id=\"_226\"></a>四、索引与统计信息的深度优化</h3>\n<h4><a id=\"1__228\"></a>1. 覆盖索引与前缀索引的应用</h4>\n<p>当查询字段可完全通过索引获取时，覆盖索引可避免回表查询。以订单查询为例：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始查询：需要回表查询</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> order_id, create_time, total_amount\n<span class=\"hljs-keyword\">FROM</span> orders\n<span class=\"hljs-keyword\">WHERE</span> user_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">1234</span> <span class=\"hljs-keyword\">AND</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-01&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 优化方案：创建覆盖索引</span>\n<span class=\"hljs-keyword\">ALTER</span> <span class=\"hljs-keyword\">TABLE</span> orders <span class=\"hljs-keyword\">ADD</span> KEY idx_user_time_amount (user_id, create_time, total_amount);\n\n<span class=\"hljs-comment\">-- 优化后执行计划：Using index（覆盖索引）</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> order_id, create_time, total_amount\n<span class=\"hljs-keyword\">FROM</span> orders\n<span class=\"hljs-keyword\">WHERE</span> user_id <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">1234</span> <span class=\"hljs-keyword\">AND</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-01&#x27;</span>;\n</code></div></pre>\n<p>对于长文本字段（如商品描述），前缀索引可在空间与性能间取得平衡：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 创建前缀索引（取前100个字符）</span>\n<span class=\"hljs-keyword\">ALTER</span> <span class=\"hljs-keyword\">TABLE</span> products <span class=\"hljs-keyword\">ADD</span> KEY idx_desc_prefix (description(<span class=\"hljs-number\">100</span>));\n\n<span class=\"hljs-comment\">-- 查询包含&quot;人工智能&quot;的商品</span>\n<span class=\"hljs-keyword\">SELECT</span> product_id, name\n<span class=\"hljs-keyword\">FROM</span> products\n<span class=\"hljs-keyword\">WHERE</span> description <span class=\"hljs-keyword\">LIKE</span> <span class=\"hljs-string\">&#x27;%人工智能%&#x27;</span>;\n</code></div></pre>\n<h4><a id=\"2__259\"></a>2. 统计信息更新与直方图优化</h4>\n<p>MySQL的查询优化器依赖表统计信息生成执行计划，过时统计信息会导致错误决策：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 场景：订单表新增90%的&quot;电子产品&quot;订单，但统计信息未更新</span>\n<span class=\"hljs-comment\">-- 错误执行计划：选择全表扫描而非索引</span>\nEXPLAIN <span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-operator\">*</span> <span class=\"hljs-keyword\">FROM</span> orders <span class=\"hljs-keyword\">WHERE</span> category <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;电子产品&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 优化方案：更新表统计信息</span>\nANALYZE <span class=\"hljs-keyword\">TABLE</span> orders;\n\n<span class=\"hljs-comment\">-- 高级优化：为category字段创建直方图</span>\n<span class=\"hljs-keyword\">ALTER</span> <span class=\"hljs-keyword\">TABLE</span> orders <span class=\"hljs-keyword\">SET</span> STATISTICS_PERSISTENT<span class=\"hljs-operator\">=</span><span class=\"hljs-keyword\">ON</span>;\nANALYZE <span class=\"hljs-keyword\">TABLE</span> orders <span class=\"hljs-keyword\">UPDATE</span> HISTOGRAM <span class=\"hljs-keyword\">ON</span> category;\n</code></div></pre>\n<h3><a id=\"_276\"></a>五、复杂查询的分拆与缓存策略</h3>\n<h4><a id=\"1__278\"></a>1. 大查询分拆为多个小查询</h4>\n<p>当单个查询涉及超过5张表关联时，可拆分为多个子查询分步执行：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 原始复杂查询：五表关联</span>\n<span class=\"hljs-keyword\">SELECT</span> o.order_id, u.username, p.product_name, c.category_name, s.status_name\n<span class=\"hljs-keyword\">FROM</span> orders o\n<span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> o.user_id <span class=\"hljs-operator\">=</span> u.user_id\n<span class=\"hljs-keyword\">JOIN</span> order_items oi <span class=\"hljs-keyword\">ON</span> o.order_id <span class=\"hljs-operator\">=</span> oi.order_id\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> oi.product_id <span class=\"hljs-operator\">=</span> p.product_id\n<span class=\"hljs-keyword\">JOIN</span> categories c <span class=\"hljs-keyword\">ON</span> p.category_id <span class=\"hljs-operator\">=</span> c.category_id\n<span class=\"hljs-keyword\">JOIN</span> order_status s <span class=\"hljs-keyword\">ON</span> o.status_id <span class=\"hljs-operator\">=</span> s.status_id\n<span class=\"hljs-keyword\">WHERE</span> o.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-06-01&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 优化方案：分三步查询</span>\n<span class=\"hljs-comment\">-- 1. 查询订单基本信息</span>\n<span class=\"hljs-keyword\">CREATE</span> TEMPORARY <span class=\"hljs-keyword\">TABLE</span> temp_orders <span class=\"hljs-keyword\">AS</span>\n<span class=\"hljs-keyword\">SELECT</span> order_id, user_id, status_id, create_time\n<span class=\"hljs-keyword\">FROM</span> orders\n<span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-06-01&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 2. 关联用户和状态表</span>\n<span class=\"hljs-keyword\">CREATE</span> TEMPORARY <span class=\"hljs-keyword\">TABLE</span> temp_orders_users <span class=\"hljs-keyword\">AS</span>\n<span class=\"hljs-keyword\">SELECT</span> o.order_id, u.username, s.status_name\n<span class=\"hljs-keyword\">FROM</span> temp_orders o\n<span class=\"hljs-keyword\">JOIN</span> users u <span class=\"hljs-keyword\">ON</span> o.user_id <span class=\"hljs-operator\">=</span> u.user_id\n<span class=\"hljs-keyword\">JOIN</span> order_status s <span class=\"hljs-keyword\">ON</span> o.status_id <span class=\"hljs-operator\">=</span> s.status_id;\n\n<span class=\"hljs-comment\">-- 3. 关联商品和分类表</span>\n<span class=\"hljs-keyword\">SELECT</span> o.order_id, u.username, p.product_name, c.category_name, o.status_name\n<span class=\"hljs-keyword\">FROM</span> temp_orders_users o\n<span class=\"hljs-keyword\">JOIN</span> order_items oi <span class=\"hljs-keyword\">ON</span> o.order_id <span class=\"hljs-operator\">=</span> oi.order_id\n<span class=\"hljs-keyword\">JOIN</span> products p <span class=\"hljs-keyword\">ON</span> oi.product_id <span class=\"hljs-operator\">=</span> p.product_id\n<span class=\"hljs-keyword\">JOIN</span> categories c <span class=\"hljs-keyword\">ON</span> p.category_id <span class=\"hljs-operator\">=</span> c.category_id;\n</code></div></pre>\n<h4><a id=\"2__315\"></a>2. 结果缓存与查询缓存策略</h4>\n<p>对于高频低变的查询，可利用MySQL查询缓存或应用层缓存：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- MySQL查询缓存（需配置query_cache_type=1）</span>\n<span class=\"hljs-keyword\">SELECT</span> SQL_CACHE order_id, total_amount\n<span class=\"hljs-keyword\">FROM</span> orders\n<span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-keyword\">BETWEEN</span> <span class=\"hljs-string\">&#x27;2025-06-10&#x27;</span> <span class=\"hljs-keyword\">AND</span> <span class=\"hljs-string\">&#x27;2025-06-20&#x27;</span>;\n\n<span class=\"hljs-comment\">-- 应用层缓存示例（PHP代码）</span>\n$cacheKey <span class=\"hljs-operator\">=</span> <span class=\"hljs-string\">&#x27;orders_20250610_20250620&#x27;</span>;\n$orders <span class=\"hljs-operator\">=</span> redis_get($cacheKey);\nif (<span class=\"hljs-operator\">!</span>$orders) {\n  $orders <span class=\"hljs-operator\">=</span> db_query(&quot;SELECT order_id, total_amount FROM orders WHERE create_time BETWEEN &#x27;2025-06-10&#x27; AND &#x27;2025-06-20&#x27;&quot;);\n  redis_set($cacheKey, $orders, <span class=\"hljs-number\">3600</span>); <span class=\"hljs-operator\">/</span><span class=\"hljs-operator\">/</span> 缓存<span class=\"hljs-number\">1</span>小时\n}\n</code></div></pre>\n<h3><a id=\"_334\"></a>六、实战案例：电商系统复杂查询优化全流程</h3>\n<h4><a id=\"30TOP10_336\"></a>场景：查询&quot;近30天内购买过TOP10热销商品的用户及其复购率&quot;</h4>\n<p><strong>原始查询（耗时12秒）</strong>：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-keyword\">SELECT</span> u.user_id, u.username, <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-keyword\">DISTINCT</span> o.order_id) <span class=\"hljs-keyword\">as</span> order_count,\n  (<span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-operator\">*</span>) <span class=\"hljs-keyword\">FROM</span> orders o2 <span class=\"hljs-keyword\">WHERE</span> o2.user_id <span class=\"hljs-operator\">=</span> u.user_id <span class=\"hljs-keyword\">AND</span> o2.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>) <span class=\"hljs-keyword\">as</span> total_orders,\n  (<span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-keyword\">DISTINCT</span> o.order_id) <span class=\"hljs-operator\">/</span> (<span class=\"hljs-keyword\">SELECT</span> <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-operator\">*</span>) <span class=\"hljs-keyword\">FROM</span> orders o3 <span class=\"hljs-keyword\">WHERE</span> o3.user_id <span class=\"hljs-operator\">=</span> u.user_id <span class=\"hljs-keyword\">AND</span> o3.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>)) <span class=\"hljs-keyword\">as</span> repurchase_rate\n<span class=\"hljs-keyword\">FROM</span> users u\n<span class=\"hljs-keyword\">JOIN</span> orders o <span class=\"hljs-keyword\">ON</span> u.user_id <span class=\"hljs-operator\">=</span> o.user_id\n<span class=\"hljs-keyword\">JOIN</span> order_items oi <span class=\"hljs-keyword\">ON</span> o.order_id <span class=\"hljs-operator\">=</span> oi.order_id\n<span class=\"hljs-keyword\">WHERE</span> o.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n<span class=\"hljs-keyword\">AND</span> oi.product_id <span class=\"hljs-keyword\">IN</span> (\n  <span class=\"hljs-comment\">-- TOP10热销商品</span>\n  <span class=\"hljs-keyword\">SELECT</span> product_id <span class=\"hljs-keyword\">FROM</span> order_items\n  <span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> product_id <span class=\"hljs-keyword\">ORDER</span> <span class=\"hljs-keyword\">BY</span> <span class=\"hljs-built_in\">SUM</span>(quantity) <span class=\"hljs-keyword\">DESC</span> LIMIT <span class=\"hljs-number\">10</span>\n)\n<span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> u.user_id, u.username;\n</code></div></pre>\n<p><strong>优化步骤</strong>：</p>\n<ol>\n<li><strong>子查询转JOIN</strong>：将TOP10商品查询转为CTE</li>\n</ol>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-keyword\">WITH</span> top_products <span class=\"hljs-keyword\">AS</span> (\n  <span class=\"hljs-keyword\">SELECT</span> product_id <span class=\"hljs-keyword\">FROM</span> order_items\n  <span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> product_id <span class=\"hljs-keyword\">ORDER</span> <span class=\"hljs-keyword\">BY</span> <span class=\"hljs-built_in\">SUM</span>(quantity) <span class=\"hljs-keyword\">DESC</span> LIMIT <span class=\"hljs-number\">10</span>\n)\n</code></div></pre>\n<ol start=\"2\">\n<li><strong>预计算复购率数据</strong>：避免重复查询订单表</li>\n</ol>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-keyword\">CREATE</span> TEMPORARY <span class=\"hljs-keyword\">TABLE</span> temp_user_orders <span class=\"hljs-keyword\">AS</span>\n<span class=\"hljs-keyword\">SELECT</span> user_id, <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-operator\">*</span>) <span class=\"hljs-keyword\">as</span> total_orders\n<span class=\"hljs-keyword\">FROM</span> orders\n<span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n<span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> user_id;\n</code></div></pre>\n<ol start=\"3\">\n<li><strong>重构查询结构</strong>：</li>\n</ol>\n<pre><div class=\"hljs\"><code class=\"lang-sql\"><span class=\"hljs-comment\">-- 优化后查询（耗时1.4秒）</span>\n<span class=\"hljs-keyword\">WITH</span> top_products <span class=\"hljs-keyword\">AS</span> (\n  <span class=\"hljs-keyword\">SELECT</span> product_id <span class=\"hljs-keyword\">FROM</span> order_items\n  <span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> product_id <span class=\"hljs-keyword\">ORDER</span> <span class=\"hljs-keyword\">BY</span> <span class=\"hljs-built_in\">SUM</span>(quantity) <span class=\"hljs-keyword\">DESC</span> LIMIT <span class=\"hljs-number\">10</span>\n),\nuser_order_stats <span class=\"hljs-keyword\">AS</span> (\n  <span class=\"hljs-keyword\">SELECT</span> user_id, <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-operator\">*</span>) <span class=\"hljs-keyword\">as</span> total_orders\n  <span class=\"hljs-keyword\">FROM</span> orders\n  <span class=\"hljs-keyword\">WHERE</span> create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n  <span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> user_id\n)\n<span class=\"hljs-keyword\">SELECT</span> u.user_id, u.username, \n  <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-keyword\">DISTINCT</span> o.order_id) <span class=\"hljs-keyword\">as</span> order_count,\n  s.total_orders,\n  IF(s.total_orders <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-number\">0</span>, <span class=\"hljs-built_in\">COUNT</span>(<span class=\"hljs-keyword\">DISTINCT</span> o.order_id) <span class=\"hljs-operator\">/</span> s.total_orders, <span class=\"hljs-number\">0</span>) <span class=\"hljs-keyword\">as</span> repurchase_rate\n<span class=\"hljs-keyword\">FROM</span> users u\n<span class=\"hljs-keyword\">JOIN</span> orders o <span class=\"hljs-keyword\">ON</span> u.user_id <span class=\"hljs-operator\">=</span> o.user_id\n<span class=\"hljs-keyword\">JOIN</span> order_items oi <span class=\"hljs-keyword\">ON</span> o.order_id <span class=\"hljs-operator\">=</span> oi.order_id\n<span class=\"hljs-keyword\">JOIN</span> top_products tp <span class=\"hljs-keyword\">ON</span> oi.product_id <span class=\"hljs-operator\">=</span> tp.product_id\n<span class=\"hljs-keyword\">LEFT</span> <span class=\"hljs-keyword\">JOIN</span> user_order_stats s <span class=\"hljs-keyword\">ON</span> u.user_id <span class=\"hljs-operator\">=</span> s.user_id\n<span class=\"hljs-keyword\">WHERE</span> o.create_time <span class=\"hljs-operator\">&gt;</span> <span class=\"hljs-string\">&#x27;2025-05-20&#x27;</span>\n<span class=\"hljs-keyword\">GROUP</span> <span class=\"hljs-keyword\">BY</span> u.user_id, u.username;\n</code></div></pre>\n<p><strong>优化效果分析</strong>：</p>\n<ul>\n<li>执行计划扫描行数从890万降至78万</li>\n<li>临时表使用从<code>Using temporary</code>变为<code>Using index</code></li>\n<li>复购率计算从3次子查询变为1次JOIN</li>\n</ul>\n<h3><a id=\"_413\"></a>七、总结：复杂查询优化的核心原则</h3>\n<ol>\n<li><strong>减少数据扫描量</strong>：通过索引、过滤条件先缩小结果集</li>\n<li><strong>避免重复计算</strong>：利用CTE、临时表缓存中间结果</li>\n<li><strong>优先JOIN替代子查询</strong>：嵌套子查询的嵌套层级应控制在2层以内</li>\n<li><strong>关注执行计划</strong> ：重点优化<code>Using filesort</code>、<code>Using temporary</code>、<code>Full table scan</code>等低效操作</li>\n</ol>\n<p>实际优化中需结合业务场景灵活调整策略，必要时可通过<code>STRAIGHT_JOIN</code>强制指定JOIN顺序，或利用<code>SQL_BIG_RESULT</code>提示优化分组排序性能。记住：<strong>最优的查询方案往往是数据库引擎成本估算与业务逻辑的平衡点</strong>。</p>\n', '### 一、复杂查询性能瓶颈分析与优化框架\n\n在实际业务场景中，MySQL查询性能问题往往源于多表关联（JOIN）和子查询的不当使用。以电商订单系统为例，当需要查询\"近30天内购买过电子产品的用户及其订单详情\"时，若直接使用嵌套子查询或无序JOIN，可能导致查询耗时从毫秒级飙升至秒级。这类问题的核心矛盾在于：**数据库引擎对复杂查询的执行计划生成存在天然局限性，需要通过人为干预优化执行路径**。\n\n优化的核心框架可拆解为三步：\n\n1. **定位性能痛点** ：通过`EXPLAIN`分析执行计划，识别`Using filesort`、`Using temporary`等低效操作\n2. **重构查询结构**：将子查询转换为JOIN、调整表关联顺序、拆分复杂查询\n3. **索引与统计信息优化**：建立复合索引、更新表统计信息\n\n### 二、多表关联查询的优化策略与实战\n\n#### 1. JOIN顺序优化：基于成本估算的表关联策略\n\nMySQL的JOIN执行遵循\"嵌套循环连接\"（Nested Loop Join）机制，驱动表的选择直接影响IO次数。以订单表、用户表、商品表的三表关联为例：\n\n```sql\n-- 原始查询：错误的JOIN顺序导致全表扫描\nEXPLAIN SELECT o.order_id, u.username, p.product_name\nFROM orders o\nJOIN users u ON o.user_id = u.user_id\nJOIN products p ON o.product_id = p.product_id\nWHERE o.create_time > \'2025-05-20\' AND p.category = \'电子产品\';\n\n-- 优化后：先过滤再关联，以orders表为驱动表\nEXPLAIN SELECT o.order_id, u.username, p.product_name\nFROM orders o\n-- 先对orders表建立时间索引\nWHERE o.create_time > \'2025-05-20\'\nJOIN users u ON o.user_id = u.user_id\nJOIN products p ON o.product_id = p.product_id AND p.category = \'电子产品\';\n```\n\n**执行计划对比** ：  \n优化前：orders表扫描10万行，users和products表均全表扫描，总IO约20万次  \n优化后：orders表通过索引过滤至1万行，users和products表通过主键关联，总IO降至1.2万次\n\n#### 2. 复合索引与JOIN条件优化\n\n当JOIN条件涉及多个字段时，复合索引的顺序至关重要。以订单明细表与商品表的关联为例：\n\n```sql\n-- 表结构\nCREATE TABLE order_items (\n  order_id INT,\n  product_id INT,\n  quantity INT,\n  -- 错误的索引顺序：未按JOIN条件顺序创建\n  KEY idx_order_product (order_id, product_id)\n);\n\nCREATE TABLE products (\n  product_id INT PRIMARY KEY,\n  category VARCHAR(50),\n  price DECIMAL(10,2)\n);\n\n-- 低效查询：JOIN条件与索引顺序不一致\nEXPLAIN SELECT oi.order_id, p.category\nFROM order_items oi\nJOIN products p ON oi.product_id = p.product_id AND oi.order_id = 12345;\n\n-- 优化方案：重建复合索引并调整JOIN条件顺序\nALTER TABLE order_items DROP KEY idx_order_product;\nALTER TABLE order_items ADD KEY idx_product_order (product_id, order_id);\n\n-- 优化后查询：条件顺序与索引一致\nEXPLAIN SELECT oi.order_id, p.category\nFROM order_items oi\nJOIN products p ON oi.product_id = p.product_id AND oi.order_id = 12345;\n```\n\n**索引原理解析** ：  \n复合索引`idx_product_order`按`product_id`和`order_id`排序，当查询条件为`product_id = ? AND order_id = ?`时，可直接通过B+树定位，避免回表查询。而原索引`idx_order_product`在查询时只能利用`order_id`过滤，`product_id`条件需二次扫描。\n\n#### 3. 大表JOIN的分片处理\n\n当关联表数据量超过千万级时，直接JOIN可能导致内存溢出。可采用\"分批次JOIN\"策略，以日志表与用户表的关联为例：\n\n```sql\n-- 原始查询：千万级日志表与百万级用户表直接JOIN\nEXPLAIN SELECT l.user_id, u.username, COUNT(l.id) as log_count\nFROM user_logs l\nJOIN users u ON l.user_id = u.user_id\nWHERE l.log_time > \'2025-01-01\'\nGROUP BY l.user_id;\n\n-- 优化方案：分批次查询用户ID再关联\n-- 1. 先查询符合条件的用户ID范围\nSELECT user_id INTO @min_id FROM users ORDER BY user_id LIMIT 1;\nSELECT user_id INTO @max_id FROM users ORDER BY user_id DESC LIMIT 1;\n\n-- 2. 定义批次大小\nSET @batch_size = 10000;\nSET @current_id = @min_id;\n\n-- 3. 循环分批次查询\nCREATE TEMPORARY TABLE temp_results (\n  user_id INT,\n  username VARCHAR(50),\n  log_count INT\n);\n\nWHILE @current_id < @max_id DO\n  INSERT INTO temp_results\n  SELECT l.user_id, u.username, COUNT(l.id)\n  FROM user_logs l\n  JOIN users u ON l.user_id = u.user_id\n  WHERE l.log_time > \'2025-01-01\'\n  AND u.user_id BETWEEN @current_id AND @current_id + @batch_size - 1\n  GROUP BY l.user_id;\n  \n  SET @current_id = @current_id + @batch_size;\nEND WHILE;\n\n-- 4. 输出最终结果\nSELECT * FROM temp_results;\n```\n\n**性能对比** ：  \n直接JOIN：耗时120秒，内存占用峰值2.8GB  \n分批次JOIN：总耗时28秒，单次批次内存占用\\<500MB\n\n### 三、子查询优化：从嵌套到JOIN的转换艺术\n\n#### 1. 标量子查询转换为JOIN\n\n标量子查询（返回单个值）常见于\"查询订单中金额最高的商品\"场景，但其嵌套查询结构会导致多次执行：\n\n```sql\n-- 原始标量子查询：每次查询都触发子查询\nSELECT order_id, product_id, price,\n  (SELECT MAX(price) FROM order_items WHERE order_id = o.order_id) as max_price\nFROM order_items o\nWHERE order_id IN (1001, 1002, 1003);\n\n-- 优化方案：转换为自JOIN\nSELECT o1.order_id, o1.product_id, o1.price, o2.max_price\nFROM order_items o1\nJOIN (\n  SELECT order_id, MAX(price) as max_price\n  FROM order_items\n  GROUP BY order_id\n) o2 ON o1.order_id = o2.order_id\nWHERE o1.order_id IN (1001, 1002, 1003);\n```\n\n**执行计划分析** ：  \n子查询版本：外层查询3行，每行触发一次子查询（扫描100行/次），总扫描300行  \nJOIN版本：子查询先聚合生成临时表（3行），再与主表JOIN，总扫描103行\n\n#### 2. EXISTS子查询与IN子查询的选择与优化\n\n在\"查询有未支付订单的用户\"场景中，EXISTS与IN的选择直接影响性能：\n\n```sql\n-- 场景：users表10万行，orders表100万行\nCREATE TABLE users (user_id INT PRIMARY KEY, username VARCHAR(50));\nCREATE TABLE orders (order_id INT, user_id INT, status VARCHAR(20), KEY idx_user_status (user_id, status));\n\n-- 错误用法：IN子查询导致全表扫描\nSELECT u.user_id, u.username\nFROM users u\nWHERE u.user_id IN (\n  SELECT o.user_id FROM orders o WHERE o.status = \'未支付\'\n);\n\n-- 优化方案：EXISTS结合索引\nSELECT u.user_id, u.username\nFROM users u\nWHERE EXISTS (\n  SELECT 1 FROM orders o \n  WHERE o.user_id = u.user_id AND o.status = \'未支付\'\n);\n\n-- 更优方案：JOIN + 聚合\nSELECT u.user_id, u.username\nFROM users u\nJOIN orders o ON u.user_id = o.user_id AND o.status = \'未支付\'\nGROUP BY u.user_id, u.username;\n```\n\n**性能测试数据** ：  \nIN子查询：耗时18秒，扫描orders表100万行  \nEXISTS子查询：耗时3.2秒，利用`idx_user_status`索引扫描20万行  \nJOIN方案：耗时1.8秒，通过索引过滤后JOIN结果集10万行\n\n#### 3. WITH RECURSIVE优化递归子查询\n\n在处理层级数据（如部门架构）时，递归子查询可能导致性能骤降，可通过CTE（Common Table Expression）优化：\n\n```sql\n-- 原始递归子查询：查询部门及其所有子部门\nSELECT dept_id, parent_id, dept_name\nFROM departments\nWHERE dept_id = 1001\nUNION ALL\nSELECT d.dept_id, d.parent_id, d.dept_name\nFROM departments d\nJOIN (\n  SELECT dept_id, parent_id, dept_name\n  FROM departments\n  WHERE dept_id = 1001\n) sub ON d.parent_id = sub.dept_id;\n\n-- 优化方案：WITH RECURSIVE CTE\nWITH RECURSIVE dept_hierarchy AS (\n  -- 初始查询：根部门\n  SELECT dept_id, parent_id, dept_name, 1 as level\n  FROM departments\n  WHERE dept_id = 1001\n  \n  UNION ALL\n  \n  -- 递归查询：子部门\n  SELECT d.dept_id, d.parent_id, d.dept_name, dh.level + 1\n  FROM departments d\n  JOIN dept_hierarchy dh ON d.parent_id = dh.dept_id\n)\nSELECT * FROM dept_hierarchy;\n```\n\n**执行效率对比** ：  \n原始递归：耗时7.5秒，重复扫描父部门数据  \nCTE优化：耗时1.2秒，利用CTE缓存中间结果，避免重复查询\n\n### 四、索引与统计信息的深度优化\n\n#### 1. 覆盖索引与前缀索引的应用\n\n当查询字段可完全通过索引获取时，覆盖索引可避免回表查询。以订单查询为例：\n\n```sql\n-- 原始查询：需要回表查询\nEXPLAIN SELECT order_id, create_time, total_amount\nFROM orders\nWHERE user_id = 1234 AND create_time > \'2025-05-01\';\n\n-- 优化方案：创建覆盖索引\nALTER TABLE orders ADD KEY idx_user_time_amount (user_id, create_time, total_amount);\n\n-- 优化后执行计划：Using index（覆盖索引）\nEXPLAIN SELECT order_id, create_time, total_amount\nFROM orders\nWHERE user_id = 1234 AND create_time > \'2025-05-01\';\n```\n\n对于长文本字段（如商品描述），前缀索引可在空间与性能间取得平衡：\n\n```sql\n-- 创建前缀索引（取前100个字符）\nALTER TABLE products ADD KEY idx_desc_prefix (description(100));\n\n-- 查询包含\"人工智能\"的商品\nSELECT product_id, name\nFROM products\nWHERE description LIKE \'%人工智能%\';\n```\n\n#### 2. 统计信息更新与直方图优化\n\nMySQL的查询优化器依赖表统计信息生成执行计划，过时统计信息会导致错误决策：\n\n```sql\n-- 场景：订单表新增90%的\"电子产品\"订单，但统计信息未更新\n-- 错误执行计划：选择全表扫描而非索引\nEXPLAIN SELECT * FROM orders WHERE category = \'电子产品\';\n\n-- 优化方案：更新表统计信息\nANALYZE TABLE orders;\n\n-- 高级优化：为category字段创建直方图\nALTER TABLE orders SET STATISTICS_PERSISTENT=ON;\nANALYZE TABLE orders UPDATE HISTOGRAM ON category;\n```\n\n### 五、复杂查询的分拆与缓存策略\n\n#### 1. 大查询分拆为多个小查询\n\n当单个查询涉及超过5张表关联时，可拆分为多个子查询分步执行：\n\n```sql\n-- 原始复杂查询：五表关联\nSELECT o.order_id, u.username, p.product_name, c.category_name, s.status_name\nFROM orders o\nJOIN users u ON o.user_id = u.user_id\nJOIN order_items oi ON o.order_id = oi.order_id\nJOIN products p ON oi.product_id = p.product_id\nJOIN categories c ON p.category_id = c.category_id\nJOIN order_status s ON o.status_id = s.status_id\nWHERE o.create_time > \'2025-06-01\';\n\n-- 优化方案：分三步查询\n-- 1. 查询订单基本信息\nCREATE TEMPORARY TABLE temp_orders AS\nSELECT order_id, user_id, status_id, create_time\nFROM orders\nWHERE create_time > \'2025-06-01\';\n\n-- 2. 关联用户和状态表\nCREATE TEMPORARY TABLE temp_orders_users AS\nSELECT o.order_id, u.username, s.status_name\nFROM temp_orders o\nJOIN users u ON o.user_id = u.user_id\nJOIN order_status s ON o.status_id = s.status_id;\n\n-- 3. 关联商品和分类表\nSELECT o.order_id, u.username, p.product_name, c.category_name, o.status_name\nFROM temp_orders_users o\nJOIN order_items oi ON o.order_id = oi.order_id\nJOIN products p ON oi.product_id = p.product_id\nJOIN categories c ON p.category_id = c.category_id;\n```\n\n#### 2. 结果缓存与查询缓存策略\n\n对于高频低变的查询，可利用MySQL查询缓存或应用层缓存：\n\n```sql\n-- MySQL查询缓存（需配置query_cache_type=1）\nSELECT SQL_CACHE order_id, total_amount\nFROM orders\nWHERE create_time BETWEEN \'2025-06-10\' AND \'2025-06-20\';\n\n-- 应用层缓存示例（PHP代码）\n$cacheKey = \'orders_20250610_20250620\';\n$orders = redis_get($cacheKey);\nif (!$orders) {\n  $orders = db_query(\"SELECT order_id, total_amount FROM orders WHERE create_time BETWEEN \'2025-06-10\' AND \'2025-06-20\'\");\n  redis_set($cacheKey, $orders, 3600); // 缓存1小时\n}\n```\n\n### 六、实战案例：电商系统复杂查询优化全流程\n\n#### 场景：查询\"近30天内购买过TOP10热销商品的用户及其复购率\"\n\n**原始查询（耗时12秒）**：\n\n```sql\nSELECT u.user_id, u.username, COUNT(DISTINCT o.order_id) as order_count,\n  (SELECT COUNT(*) FROM orders o2 WHERE o2.user_id = u.user_id AND o2.create_time > \'2025-05-20\') as total_orders,\n  (COUNT(DISTINCT o.order_id) / (SELECT COUNT(*) FROM orders o3 WHERE o3.user_id = u.user_id AND o3.create_time > \'2025-05-20\')) as repurchase_rate\nFROM users u\nJOIN orders o ON u.user_id = o.user_id\nJOIN order_items oi ON o.order_id = oi.order_id\nWHERE o.create_time > \'2025-05-20\'\nAND oi.product_id IN (\n  -- TOP10热销商品\n  SELECT product_id FROM order_items\n  WHERE create_time > \'2025-05-20\'\n  GROUP BY product_id ORDER BY SUM(quantity) DESC LIMIT 10\n)\nGROUP BY u.user_id, u.username;\n```\n\n**优化步骤**：\n\n1. **子查询转JOIN**：将TOP10商品查询转为CTE\n\n```sql\nWITH top_products AS (\n  SELECT product_id FROM order_items\n  WHERE create_time > \'2025-05-20\'\n  GROUP BY product_id ORDER BY SUM(quantity) DESC LIMIT 10\n)\n```\n\n2. **预计算复购率数据**：避免重复查询订单表\n\n```sql\nCREATE TEMPORARY TABLE temp_user_orders AS\nSELECT user_id, COUNT(*) as total_orders\nFROM orders\nWHERE create_time > \'2025-05-20\'\nGROUP BY user_id;\n```\n\n3. **重构查询结构**：\n\n```sql\n-- 优化后查询（耗时1.4秒）\nWITH top_products AS (\n  SELECT product_id FROM order_items\n  WHERE create_time > \'2025-05-20\'\n  GROUP BY product_id ORDER BY SUM(quantity) DESC LIMIT 10\n),\nuser_order_stats AS (\n  SELECT user_id, COUNT(*) as total_orders\n  FROM orders\n  WHERE create_time > \'2025-05-20\'\n  GROUP BY user_id\n)\nSELECT u.user_id, u.username, \n  COUNT(DISTINCT o.order_id) as order_count,\n  s.total_orders,\n  IF(s.total_orders > 0, COUNT(DISTINCT o.order_id) / s.total_orders, 0) as repurchase_rate\nFROM users u\nJOIN orders o ON u.user_id = o.user_id\nJOIN order_items oi ON o.order_id = oi.order_id\nJOIN top_products tp ON oi.product_id = tp.product_id\nLEFT JOIN user_order_stats s ON u.user_id = s.user_id\nWHERE o.create_time > \'2025-05-20\'\nGROUP BY u.user_id, u.username;\n```\n\n**优化效果分析**：\n\n* 执行计划扫描行数从890万降至78万\n* 临时表使用从`Using temporary`变为`Using index`\n* 复购率计算从3次子查询变为1次JOIN\n\n### 七、总结：复杂查询优化的核心原则\n\n1. **减少数据扫描量**：通过索引、过滤条件先缩小结果集\n2. **避免重复计算**：利用CTE、临时表缓存中间结果\n3. **优先JOIN替代子查询**：嵌套子查询的嵌套层级应控制在2层以内\n4. **关注执行计划** ：重点优化`Using filesort`、`Using temporary`、`Full table scan`等低效操作\n\n实际优化中需结合业务场景灵活调整策略，必要时可通过`STRAIGHT_JOIN`强制指定JOIN顺序，或利用`SQL_BIG_RESULT`提示优化分组排序性能。记住：**最优的查询方案往往是数据库引擎成本估算与业务逻辑的平衡点**。\n', 1, 1, 1, 0, 0, 1, 'https://blog.csdn.net/qq_35766758/article/details/148799612', 0, NULL, '测试ai', '2025-06-21 15:22:29', '2025-06-26 11:20:49');
INSERT INTO `sys_article` (`id`, `user_id`, `title`, `cover`, `summary`, `content`, `content_md`, `read_type`, `is_stick`, `status`, `is_original`, `is_carousel`, `is_recommend`, `original_url`, `quantity`, `keywords`, `ai_describe`, `create_time`, `update_time`) VALUES (334, 1, '【JAVA】Java线上问题排查“活地图”：CPU与内存问题定位与调优指南', NULL, '【JAVA】Java线上问题排查“活地图”：CPU与内存问题定位与调优指南', '<h3><a id=\"_CPU___0\"></a>前言：线上血雨腥风，记一次惊心动魄的 CPU 爆表 💥</h3>\n<p>对于我们这些 Java 后端攻城狮来说，线上的世界从来都不是风平浪静。各种妖魔鬼怪层出不穷，CPU 突然像脱缰的野马一样狂飙，内存一不小心就给你 OutOfMemoryError 的&quot;惊喜&quot;，还有那频繁得让人怀疑人生的 GC… 相信各位或多或少都经历过线上事故的&quot;洗礼&quot;。</p>\n<p>今天，我想跟大家聊聊线上问题排查的那些&quot;基本操作&quot;。你可能会觉得&quot;基本&quot;嘛，谁还不会 <code>top</code> 和 <code>jstack</code>？但就像武侠小说里的基本功一样，往往最基础的东西才是解决复杂问题的基石。别问我为什么这么说，因为我前几天就刚经历了一场因为&quot;基本功&quot;扎实而化险为夷的战斗！</p>\n<p>话说上周五，我刚泡好一杯枸杞菊花茶，准备摸鱼…哦不，是认真 review 代码的时候，突然监控群里 красные报警像雨点一样砸过来：<strong>&quot;XX服务 CPU 使用率持续超过 90%！&quot;</strong></p>\n<p>我的心头一紧，菊花茶瞬间不香了。线上 CPU 爆高，这可不是闹着玩的。赶紧放下手里的&quot;摸鱼神器&quot;，我开始了我的&quot;线上救援&quot;行动。</p>\n<p><strong>（接下来就可以直接切入正文的第一点，并结合故事来讲解）</strong></p>\n<hr />\n<h3><a id=\"1_CPU___14\"></a>1. CPU 飚高：抽丝剥茧，揪出那个&quot;疯狂&quot;的线程 🧵</h3>\n<h4><a id=\"11__CPU__16\"></a>1.1 定位&quot;罪魁祸首&quot;：找到高 CPU 进程</h4>\n<p>如同警察办案一样，我们首先要找到&quot;案发现场&quot;。我的第一反应就是登录服务器，祭出我的&quot;老伙计&quot;：<code>top</code> 命令。</p>\n<p>在 <code>top</code> 的输出结果中，我迅速锁定了那个 CPU 使用率高居不下的 Java 进程，记下了它的 <strong>PID (Process ID)</strong>。</p>\n<h4><a id=\"12__CPU__22\"></a>1.2 揪出&quot;真凶&quot;：定位高 CPU 线程</h4>\n<p>找到了&quot;嫌疑人&quot;进程，接下来就要找到这个进程里哪个线程在&quot;搞事情&quot;。 这时候就需要 <code>top</code> 的另一个利器：<code>top -Hp [进程 ID]</code>。</p>\n<p>这个命令会列出指定 PID 下所有线程的 CPU 使用情况。很快，我就发现了一个 CPU 占用率极高的线程，再次记下它的 <strong>线程 ID (LWP)</strong>。</p>\n<h4><a id=\"13__28\"></a>1.3 &quot;审问&quot;嫌疑人：查看线程堆栈</h4>\n<p>现在我们已经锁定了&quot;嫌疑线程&quot;，是时候看看它到底在干什么了。JDK 提供的 <code>jstack</code> 工具就是我们的&quot;审讯利器&quot;。</p>\n<p>我执行了命令：<code>jstack -l [进程 ID] &gt; jstack.log</code>，将该进程的所有线程堆栈信息都导到了 <code>jstack.log</code> 文件中。</p>\n<p><strong>（故事继续）</strong></p>\n<p>由于 <code>top -Hp</code> 看到的线程 ID是十进制的，而 <code>jstack</code> 日志中的线程 ID 是十六进制的，所以我们需要进行一个简单的转换。使用 <code>printf &quot;%x\\n&quot; [十进制线程 ID]</code> 命令，将十进制的线程 ID 转换为十六进制。</p>\n<p>拿到十六进制的线程 ID，我打开 <code>jstack.log</code> 文件，通过搜索（<code>/</code> 命令在 <code>vim</code> 中）找到了对应的线程堆栈信息。</p>\n<p><strong>（在这里可以贴一段你实际遇到的线程堆栈的简化版，并进行分析）</strong></p>\n<p>例如，我看到这个线程一直在执行一个看似没有出口的循环：</p>\n<pre><div class=\"hljs\"><code class=\"lang-sh\"><span class=\"hljs-string\">&quot;Thread-X&quot;</span> <span class=\"hljs-comment\">#23 prio=5 os_prio=0 tid=0x00007f8c12345678 nid=0xabcd runnable [0x00007f8c98765432]</span>\njava.lang.Thread.State: RUNNABLE at\ncom.example.demo.service.impl.SomeServiceImpl.process(SomeServiceImpl.java:88) at\ncom.example.demo.task.MyTask.run(MyTask.java:35) at\njava.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1149) at\njava.util.concurrent.ThreadPoolExecutor<span class=\"hljs-variable\">$Worker</span>.run(ThreadPoolExecutor.java:624) at\njava.lang.Thread.run(Thread.java:748)\n</code></div></pre>\n<p><strong>（故事高潮）</strong></p>\n<p>看到 <code>SomeServiceImpl.java:88</code> 这行代码，我瞬间明白了！这不就是我昨天刚上线的一个功能吗？由于在处理某种特殊数据时，我遗漏了一个判断条件，导致程序进入了死循环，一直在疯狂地消耗 CPU 资源！</p>\n<p><strong>（解决方案）</strong></p>\n<p>定位到问题代码，解决起来就简单多了。我立即修改了代码，增加了缺失的判断逻辑，然后紧急发布上线。几分钟后，监控告警消失，服务器的 CPU 使用率也恢复了正常。</p>\n<p><strong>（总结经验）</strong></p>\n<p>这次 CPU 爆高事件虽然惊险，但也给我提了个醒：<strong>再简单的代码也需要仔细 review，任何疏忽都可能导致线上事故。</strong></p>\n<h4><a id=\"14__CPU__66\"></a>1.4 其他 CPU 飚高原因</h4>\n<p>除了业务逻辑死循环，CPU 飚高还可能是以下原因导致的：</p>\n<ul>\n<li><strong>C2 编译器优化：</strong> JVM 的 C2 编译器在将热点代码编译成本地机器码时会消耗 CPU。<strong>解决方案：</strong> 提前进行充分的压测预热，让 C2 编译器在上线前完成编译。</li>\n<li><strong>频繁 Full GC：</strong> Full GC 会 Stop-The-World，如果过于频繁也会导致 CPU 升高。<strong>解决方案：</strong> 需要进行 GC 优化。</li>\n</ul>\n<hr />\n<h3><a id=\"2__GC___75\"></a>2. 内存问题排查：与 GC “斗智斗勇” 🧠</h3>\n<h4><a id=\"21_OOM_77\"></a>2.1 内存溢出（OOM）：最后的&quot;遗言&quot;</h4>\n<p>内存溢出是 Java 应用最致命的错误之一。当 JVM 堆内存不足以创建新对象时，就会抛出 <code>OutOfMemoryError</code>。</p>\n<p><strong>排查方法：</strong></p>\n<ul>\n<li><strong>添加 JVM 参数：</strong> 在启动参数中加上 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，这样在发生 OOM 时，JVM 会生成一个 Heap Dump 文件（<code>.hprof</code> 文件），记录了当时堆内存的详细信息。</li>\n<li><strong>使用内存分析工具：</strong> 常用的工具有 <strong>MAT (Memory Analyzer Tool)</strong> ，<strong>JProfiler</strong> ，<strong>JVisualVM</strong> 等。这些工具可以分析 Heap Dump 文件，找出内存泄漏的原因，例如哪些对象占用了大量内存，对象的引用链是什么等等。</li>\n</ul>\n<h4><a id=\"22_GC___86\"></a>2.2 GC 不健康：小心&quot;温水煮青蛙&quot; 🐸</h4>\n<p>有时候，内存并没有溢出，但是 GC 的行为并不理想，例如 Young GC（YGC）过于频繁或耗时过长，Full GC（FGC）过于频繁等等。这也会影响应用的性能。</p>\n<p><strong>如何判断 GC 是否健康？</strong></p>\n<p>根据我的经验，一个相对健康的 GC 状态是：</p>\n<ul>\n<li><strong>YGC：</strong> 大约 5 秒一次左右，每次耗时不超过 50 毫秒。</li>\n<li><strong>FGC：</strong> 最好没有，如果使用 CMS GC，一天一次左右是可以接受的。</li>\n</ul>\n<p><strong>GC 优化的两个维度：</strong></p>\n<ul>\n<li>\n<p>频率：</p>\n<ul>\n<li><strong>YGC 频率过低（间隔过长）：</strong> 可能说明堆内存过大，可以适当缩小堆内存。</li>\n<li><strong>YGC 频率过高：</strong> 可能说明 Eden 区过小，可以适当增大 Eden 区，但要保证新生代占整个堆的 30%-40%。Eden、From Survivor、To Survivor 的比例建议在 8:1:1 左右，可以根据实际情况调整。</li>\n</ul>\n</li>\n<li>\n<p>时长（主要针对 YGC）：</p>\n<ul>\n<li>\n<p>YGC 耗时过长：</p>\n<p>可能原因包括：</p>\n<ul>\n<li><strong>大量对象需要复制：</strong> 检查是否有大量短生命周期的大对象。</li>\n<li><strong>StringTable 过大：</strong> 如果大量使用 <code>String.intern()</code> 且没有 Full GC 清理，可能导致 StringTable 很大，YGC 扫描耗时增加。</li>\n<li><strong>操作系统 Swap：</strong> GC 时如果操作系统正在进行内存交换，也会增加 STW 时间。</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p><strong>FGC 优化（主要优化频率）：</strong></p>\n<p>FGC 的常见原因和优化思路：</p>\n<ol>\n<li><strong>Old 区内存不够：</strong> 扩大 Old 区容量。如果 FGC 后 Old 区仍然有很多存活对象，说明 Old 区确实需要增大；如果 FGC 后效果很好，可能是大量短命对象进入了 Old 区，需要调整新生代大小或晋升年龄。</li>\n<li><strong>元数据区内存不够：</strong> 调整元数据区大小（<code>-XX:MaxMetaspaceSize</code>）。</li>\n<li><strong>System.gc() 调用：</strong> 避免在生产环境显式调用 <code>System.gc()</code>。</li>\n<li><strong>jmap 或 jcmd 执行 Full GC 操作：</strong> 在执行 dump 等操作时会触发 FGC，需要在合适的时间进行。</li>\n<li><strong>CMS Promotion failed 或 concurrent mode failure：</strong> 这是 CMS GC 特有的问题，通常需要调整 CMS 相关参数，例如 <code>-XX:CMSInitiatingOccupancyFraction</code>。</li>\n<li><strong>JVM 悲观策略：</strong> JVM 认为 YGC 后 Old 区无法容纳晋升对象而提前触发 FGC。可以尝试调整新生代和 Old 区的大小比例。</li>\n</ol>\n<h4><a id=\"23_GC__123\"></a>2.3 GC 监控利器</h4>\n<ul>\n<li><strong>jstat：</strong> 查看 JVM 各种内存区域的使用情况和 GC 的详细统计信息，例如 YGC 次数、YGC 总耗时、FGC 次数、FGC 总耗时等。</li>\n<li><strong>jmap 和 jcmd：</strong> 可以查看堆内存的对象分布情况，也可以生成 Heap Dump 文件。Oracle 推荐使用 <code>jcmd</code> 代替 <code>jmap</code>。<strong>注意：dump 文件时会触发 FGC，谨慎使用。</strong></li>\n<li><strong>jinfo：</strong> 查看 JVM 启动参数，也可以在运行时修改部分参数。</li>\n<li><strong>可视化 GC 日志分析工具：</strong> 例如 <strong>GCeasy</strong> ，<strong>HeapHero</strong> 等，可以将 GC 日志可视化，更直观地分析 GC 行为。</li>\n</ul>\n<p><strong>最重要的：线上环境务必开启 GC 日志！</strong> 这对于分析 GC 问题至关重要。</p>\n<hr />\n<h3><a id=\"__134\"></a>总结：基本功是线上排查的&quot;倚天剑&quot; 🗡️</h3>\n<p>正如本文的标题，我们今天聊的都是线上问题排查的&quot;基本操作&quot;。线上故障千变万化，解决之道也远不止这些。但掌握这些基本工具和思路，能帮助我们快速定位问题的方向，为后续更深入的分析打下坚实的基础。</p>\n<p>后续的文章中，我还会继续分享关于 IO、网络、TCP 连接等方面的基本排查方法，希望能和大家一起在&quot;线上战场&quot;上不断成长！敬请期待！ 😉</p>\n', '### 前言：线上血雨腥风，记一次惊心动魄的 CPU 爆表 💥\n\n对于我们这些 Java 后端攻城狮来说，线上的世界从来都不是风平浪静。各种妖魔鬼怪层出不穷，CPU 突然像脱缰的野马一样狂飙，内存一不小心就给你 OutOfMemoryError 的\"惊喜\"，还有那频繁得让人怀疑人生的 GC... 相信各位或多或少都经历过线上事故的\"洗礼\"。\n\n今天，我想跟大家聊聊线上问题排查的那些\"基本操作\"。你可能会觉得\"基本\"嘛，谁还不会 `top` 和 `jstack`？但就像武侠小说里的基本功一样，往往最基础的东西才是解决复杂问题的基石。别问我为什么这么说，因为我前几天就刚经历了一场因为\"基本功\"扎实而化险为夷的战斗！\n\n话说上周五，我刚泡好一杯枸杞菊花茶，准备摸鱼...哦不，是认真 review 代码的时候，突然监控群里 красные报警像雨点一样砸过来：**\"XX服务 CPU 使用率持续超过 90%！\"**\n\n我的心头一紧，菊花茶瞬间不香了。线上 CPU 爆高，这可不是闹着玩的。赶紧放下手里的\"摸鱼神器\"，我开始了我的\"线上救援\"行动。\n\n**（接下来就可以直接切入正文的第一点，并结合故事来讲解）**\n\n*** ** * ** ***\n\n### 1. CPU 飚高：抽丝剥茧，揪出那个\"疯狂\"的线程 🧵\n\n#### 1.1 定位\"罪魁祸首\"：找到高 CPU 进程\n\n如同警察办案一样，我们首先要找到\"案发现场\"。我的第一反应就是登录服务器，祭出我的\"老伙计\"：`top` 命令。\n\n在 `top` 的输出结果中，我迅速锁定了那个 CPU 使用率高居不下的 Java 进程，记下了它的 **PID (Process ID)**。\n\n#### 1.2 揪出\"真凶\"：定位高 CPU 线程\n\n找到了\"嫌疑人\"进程，接下来就要找到这个进程里哪个线程在\"搞事情\"。 这时候就需要 `top` 的另一个利器：`top -Hp [进程 ID]`。\n\n这个命令会列出指定 PID 下所有线程的 CPU 使用情况。很快，我就发现了一个 CPU 占用率极高的线程，再次记下它的 **线程 ID (LWP)**。\n\n#### 1.3 \"审问\"嫌疑人：查看线程堆栈\n\n现在我们已经锁定了\"嫌疑线程\"，是时候看看它到底在干什么了。JDK 提供的 `jstack` 工具就是我们的\"审讯利器\"。\n\n我执行了命令：`jstack -l [进程 ID] > jstack.log`，将该进程的所有线程堆栈信息都导到了 `jstack.log` 文件中。\n\n**（故事继续）**\n\n由于 `top -Hp` 看到的线程 ID是十进制的，而 `jstack` 日志中的线程 ID 是十六进制的，所以我们需要进行一个简单的转换。使用 `printf \"%x\\n\" [十进制线程 ID]` 命令，将十进制的线程 ID 转换为十六进制。\n\n拿到十六进制的线程 ID，我打开 `jstack.log` 文件，通过搜索（`/` 命令在 `vim` 中）找到了对应的线程堆栈信息。\n\n**（在这里可以贴一段你实际遇到的线程堆栈的简化版，并进行分析）**\n\n例如，我看到这个线程一直在执行一个看似没有出口的循环：\n\n```sh\n\"Thread-X\" #23 prio=5 os_prio=0 tid=0x00007f8c12345678 nid=0xabcd runnable [0x00007f8c98765432]\njava.lang.Thread.State: RUNNABLE at\ncom.example.demo.service.impl.SomeServiceImpl.process(SomeServiceImpl.java:88) at\ncom.example.demo.task.MyTask.run(MyTask.java:35) at\njava.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1149) at\njava.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:624) at\njava.lang.Thread.run(Thread.java:748)\n```\n\n**（故事高潮）**\n\n看到 `SomeServiceImpl.java:88` 这行代码，我瞬间明白了！这不就是我昨天刚上线的一个功能吗？由于在处理某种特殊数据时，我遗漏了一个判断条件，导致程序进入了死循环，一直在疯狂地消耗 CPU 资源！\n\n**（解决方案）**\n\n定位到问题代码，解决起来就简单多了。我立即修改了代码，增加了缺失的判断逻辑，然后紧急发布上线。几分钟后，监控告警消失，服务器的 CPU 使用率也恢复了正常。\n\n**（总结经验）**\n\n这次 CPU 爆高事件虽然惊险，但也给我提了个醒：**再简单的代码也需要仔细 review，任何疏忽都可能导致线上事故。**\n\n#### 1.4 其他 CPU 飚高原因\n\n除了业务逻辑死循环，CPU 飚高还可能是以下原因导致的：\n\n* **C2 编译器优化：** JVM 的 C2 编译器在将热点代码编译成本地机器码时会消耗 CPU。**解决方案：** 提前进行充分的压测预热，让 C2 编译器在上线前完成编译。\n* **频繁 Full GC：** Full GC 会 Stop-The-World，如果过于频繁也会导致 CPU 升高。**解决方案：** 需要进行 GC 优化。\n\n*** ** * ** ***\n\n### 2. 内存问题排查：与 GC \"斗智斗勇\" 🧠\n\n#### 2.1 内存溢出（OOM）：最后的\"遗言\"\n\n内存溢出是 Java 应用最致命的错误之一。当 JVM 堆内存不足以创建新对象时，就会抛出 `OutOfMemoryError`。\n\n**排查方法：**\n\n* **添加 JVM 参数：** 在启动参数中加上 `-XX:+HeapDumpOnOutOfMemoryError`，这样在发生 OOM 时，JVM 会生成一个 Heap Dump 文件（`.hprof` 文件），记录了当时堆内存的详细信息。\n* **使用内存分析工具：** 常用的工具有 **MAT (Memory Analyzer Tool)** ，**JProfiler** ，**JVisualVM** 等。这些工具可以分析 Heap Dump 文件，找出内存泄漏的原因，例如哪些对象占用了大量内存，对象的引用链是什么等等。\n\n#### 2.2 GC 不健康：小心\"温水煮青蛙\" 🐸\n\n有时候，内存并没有溢出，但是 GC 的行为并不理想，例如 Young GC（YGC）过于频繁或耗时过长，Full GC（FGC）过于频繁等等。这也会影响应用的性能。\n\n**如何判断 GC 是否健康？**\n\n根据我的经验，一个相对健康的 GC 状态是：\n\n* **YGC：** 大约 5 秒一次左右，每次耗时不超过 50 毫秒。\n* **FGC：** 最好没有，如果使用 CMS GC，一天一次左右是可以接受的。\n\n**GC 优化的两个维度：**\n\n* 频率：\n\n  * **YGC 频率过低（间隔过长）：** 可能说明堆内存过大，可以适当缩小堆内存。\n  * **YGC 频率过高：** 可能说明 Eden 区过小，可以适当增大 Eden 区，但要保证新生代占整个堆的 30%-40%。Eden、From Survivor、To Survivor 的比例建议在 8:1:1 左右，可以根据实际情况调整。\n* 时长（主要针对 YGC）：\n\n  * YGC 耗时过长：\n\n    可能原因包括：\n    * **大量对象需要复制：** 检查是否有大量短生命周期的大对象。\n    * **StringTable 过大：** 如果大量使用 `String.intern()` 且没有 Full GC 清理，可能导致 StringTable 很大，YGC 扫描耗时增加。\n    * **操作系统 Swap：** GC 时如果操作系统正在进行内存交换，也会增加 STW 时间。\n\n**FGC 优化（主要优化频率）：**\n\nFGC 的常见原因和优化思路：\n\n1. **Old 区内存不够：** 扩大 Old 区容量。如果 FGC 后 Old 区仍然有很多存活对象，说明 Old 区确实需要增大；如果 FGC 后效果很好，可能是大量短命对象进入了 Old 区，需要调整新生代大小或晋升年龄。\n2. **元数据区内存不够：** 调整元数据区大小（`-XX:MaxMetaspaceSize`）。\n3. **System.gc() 调用：** 避免在生产环境显式调用 `System.gc()`。\n4. **jmap 或 jcmd 执行 Full GC 操作：** 在执行 dump 等操作时会触发 FGC，需要在合适的时间进行。\n5. **CMS Promotion failed 或 concurrent mode failure：** 这是 CMS GC 特有的问题，通常需要调整 CMS 相关参数，例如 `-XX:CMSInitiatingOccupancyFraction`。\n6. **JVM 悲观策略：** JVM 认为 YGC 后 Old 区无法容纳晋升对象而提前触发 FGC。可以尝试调整新生代和 Old 区的大小比例。\n\n#### 2.3 GC 监控利器\n\n* **jstat：** 查看 JVM 各种内存区域的使用情况和 GC 的详细统计信息，例如 YGC 次数、YGC 总耗时、FGC 次数、FGC 总耗时等。\n* **jmap 和 jcmd：** 可以查看堆内存的对象分布情况，也可以生成 Heap Dump 文件。Oracle 推荐使用 `jcmd` 代替 `jmap`。**注意：dump 文件时会触发 FGC，谨慎使用。**\n* **jinfo：** 查看 JVM 启动参数，也可以在运行时修改部分参数。\n* **可视化 GC 日志分析工具：** 例如 **GCeasy** ，**HeapHero** 等，可以将 GC 日志可视化，更直观地分析 GC 行为。\n\n**最重要的：线上环境务必开启 GC 日志！** 这对于分析 GC 问题至关重要。\n\n*** ** * ** ***\n\n### 总结：基本功是线上排查的\"倚天剑\" 🗡️\n\n正如本文的标题，我们今天聊的都是线上问题排查的\"基本操作\"。线上故障千变万化，解决之道也远不止这些。但掌握这些基本工具和思路，能帮助我们快速定位问题的方向，为后续更深入的分析打下坚实的基础。\n\n后续的文章中，我还会继续分享关于 IO、网络、TCP 连接等方面的基本排查方法，希望能和大家一起在\"线上战场\"上不断成长！敬请期待！ 😉\n', 1, 0, 1, 0, 0, 0, 'https://blog.csdn.net/Billy_hxp/article/details/148716492', 0, NULL, NULL, '2025-06-21 16:14:23', '2025-06-21 16:15:07');
INSERT INTO `sys_article` (`id`, `user_id`, `title`, `cover`, `summary`, `content`, `content_md`, `read_type`, `is_stick`, `status`, `is_original`, `is_carousel`, `is_recommend`, `original_url`, `quantity`, `keywords`, `ai_describe`, `create_time`, `update_time`) VALUES (335, 1, 'HashMap 面试常见的6连问，你能扛得住吗？', NULL, 'HashMap 面试常见的6连问，你能扛得住吗？', '<div  class=\"article_content clearfix\"> \n <link rel=\"stylesheet\" href=\"https://csdnimg.cn/release/blogv2/dist/mdeditor/css/editerView/kdoc_html_views-1a98987dfd.css\"> \n <link rel=\"stylesheet\" href=\"https://csdnimg.cn/release/blogv2/dist/mdeditor/css/editerView/ck_htmledit_views-01addd087f.css\"> \n <div  class=\"markdown_views prism-atom-one-dark\"> \n  <svg xmlns=\"http://www.w3.org/2000/svg\" style=\"display: none;\"> <path stroke-linecap=\"round\" d=\"M5,0 0,2.5 5,5z\"  style=\"-webkit-tap-highlight-color: rgba(0, 0, 0, 0);\"></path> \n  </svg> \n  <p>}</p> \n  <p>/**</p> \n  <p>*&nbsp;红黑树结构</p> \n  <p>*/</p> \n  <p>static&nbsp;final&nbsp;class&nbsp;TreeNode&lt;K,V&gt;&nbsp;extends&nbsp;LinkedHashMap.Entry&lt;K,V&gt;&nbsp;{<!-- --></p> \n  <p>TreeNode&lt;K,V&gt;&nbsp;parent;&nbsp;&nbsp;//&nbsp;red-black&nbsp;tree&nbsp;links</p> \n  <p>TreeNode&lt;K,V&gt;&nbsp;left;</p> \n  <p>TreeNode&lt;K,V&gt;&nbsp;right;</p> \n  <p>TreeNode&lt;K,V&gt;&nbsp;prev;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;needed&nbsp;to&nbsp;unlink&nbsp;next&nbsp;upon&nbsp;deletion</p> \n  <p>boolean&nbsp;red;</p> \n  <p>…</p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/37c21a05a6107a9f9cd540b74b4e2cce.png\" alt=\"f0f8c04fadb3232519aaa2d65c6c95d9.png\"></p> \n  <p>图片</p> \n  <p>但面试往往会问的比较细，例如下面的容量问题，我们能答上来几个？</p> \n  <p>1、table 的初始化时机是什么时候，初始化的 table.length 是多少、阀值（threshold）是多少，实际能容下多少元素</p> \n  <p>2、什么时候触发扩容，扩容之后的 table.length、阀值各是多少？</p> \n  <p>3、table 的 length 为什么是 2 的 n 次幂</p> \n  <p>4、求索引的时候为什么是：h&amp;(length-1)，而不是 h&amp;length，更不是 h%length</p> \n  <p>5、 Map map = new HashMap(1000); 当我们存入多少个元素时会触发map的扩容；Map map1 = new HashMap(10000); 我们存入第 10001个元素时会触发 map1 扩容吗</p> \n  <p>6、为什么加载因子的默认值是 0.75，并且不推荐我们修改</p> \n  <p>由于我们平时关注的少，一旦碰上这样的 连击 + 暴击，我们往往不知所措、无从应对；接下来我们看看上面的 6 个问题，是不是真的难到无法理解 ，还是我们不够细心、在自信的自我认为</p> \n  <p>斗智斗勇，见招拆招</p> \n  <hr> \n  <p>上述的问题，我们如何去找答案 ? 方式有很多种，用的最多的，我想应该是上网查资料、看别人的博客，但我认为最有效、准确的方式是读源码</p> \n  <h4>问题 1：table 的初始化</h4> \n  <p>HashMap 的构造方法有如下 4 种</p> \n  <p>/**</p> \n  <p>*&nbsp;构造方法&nbsp;1</p> \n  <p>*</p> \n  <p>*&nbsp;通过&nbsp;指定的&nbsp;initialCapacity&nbsp;和&nbsp;loadFactor&nbsp;实例化一个空的&nbsp;HashMap&nbsp;对象</p> \n  <p>*/</p> \n  <p>public&nbsp;HashMap(int&nbsp;initialCapacity,&nbsp;float&nbsp;loadFactor)&nbsp;{<!-- --></p> \n  <p>if&nbsp;(initialCapacity&nbsp;&lt;&nbsp;0)</p> \n  <p>throw&nbsp;new&nbsp;IllegalArgumentException(\"Illegal&nbsp;initial&nbsp;capacity:&nbsp;\"&nbsp;+</p> \n  <p>initialCapacity);</p> \n  <p>if&nbsp;(initialCapacity&nbsp;&gt;&nbsp;MAXIMUM_CAPACITY)</p> \n  <p>initialCapacity&nbsp;=&nbsp;MAXIMUM_CAPACITY;</p> \n  <p>if&nbsp;(loadFactor&nbsp;&lt;=&nbsp;0&nbsp;||&nbsp;Float.isNaN(loadFactor))</p> \n  <p>throw&nbsp;new&nbsp;IllegalArgumentException(\"Illegal&nbsp;load&nbsp;factor:&nbsp;\"&nbsp;+</p> \n  <p>loadFactor);</p> \n  <p>this.loadFactor&nbsp;=&nbsp;loadFactor;</p> \n  <p>this.threshold&nbsp;=&nbsp;tableSizeFor(initialCapacity);</p> \n  <p>}</p> \n  <p>/**</p> \n  <p>*&nbsp;构造方法&nbsp;2</p> \n  <p>*</p> \n  <p>*&nbsp;通过指定的&nbsp;initialCapacity&nbsp;和&nbsp;默认的&nbsp;loadFactor(0.75)&nbsp;实例化一个空的&nbsp;HashMap&nbsp;对象</p> \n  <p>*/</p> \n  <p>public&nbsp;HashMap(int&nbsp;initialCapacity)&nbsp;{<!-- --></p> \n  <p>this(initialCapacity,&nbsp;DEFAULT_LOAD_FACTOR);</p> \n  <p>}</p> \n  <p>/**</p> \n  <p>*&nbsp;构造方法&nbsp;3</p> \n  <p>*</p> \n  <p>*&nbsp;通过默认的&nbsp;initialCapacity&nbsp;和&nbsp;默认的&nbsp;loadFactor(0.75)&nbsp;实例化一个空的&nbsp;HashMap&nbsp;对象</p> \n  <p>*/</p> \n  <p>public&nbsp;HashMap()&nbsp;{<!-- --></p> \n  <p>this.loadFactor&nbsp;=&nbsp;DEFAULT_LOAD_FACTOR;&nbsp;//&nbsp;all&nbsp;other&nbsp;fields&nbsp;defaulted</p> \n  <p>}</p> \n  <p>/**</p> \n  <p>*</p> \n  <p>*&nbsp;构造方法&nbsp;4</p> \n  <p>*&nbsp;通过指定的&nbsp;Map&nbsp;对象实例化一个&nbsp;HashMap&nbsp;对象</p> \n  <p>*/</p> \n  <p>public&nbsp;HashMap(Map&lt;?&nbsp;extends&nbsp;K,&nbsp;?&nbsp;extends&nbsp;V&gt;&nbsp;m)&nbsp;{<!-- --></p> \n  <p>this.loadFactor&nbsp;=&nbsp;DEFAULT_LOAD_FACTOR;</p> \n  <p>putMapEntries(m,&nbsp;false);</p> \n  <p>}</p> \n  <p>构造方式 4 和 构造方式 1 实际应用的不多，构造方式 2 直接调用的 1（底层实现完全一致），构造方式 2 和 构造方式 3 比较常用，而最常用的是构造方式 3；此时我们以构造方式 3 为前提来分析，而构造方式 2 我们则在问题 5 中来分析</p> \n  <p>使用方式 1 实例化 HashMap 的时候，table 并未进行初始化，那 table 是何时进行初始化的了 ？平时我们是如何使用 HashMap 的，先实例化、然后 put、然后进行其他操作，如下</p> \n  <p>Map&lt;String,Object&gt;&nbsp;map&nbsp;=&nbsp;new&nbsp;HashMap();</p> \n  <p>map.put(“name”,&nbsp;“张三”);</p> \n  <p>map.put(“age”,&nbsp;21);</p> \n  <p>//&nbsp;后续操作</p> \n  <p>…</p> \n  <p>既然实例化的时候未进行 table 的初始化，那是不是在 put 的时候初始化的了，我们来确认下</p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/0ec5b58f1f3c2219eb641d84fa40dfa2.gif\" alt=\"ef5de77244acb35b203582aed2a7486a.gif\"></p> \n  <p>图片</p> \n  <p>resize() 初始化 table 或 对 table 进行双倍扩容，源码如下（注意看注释）</p> \n  <p>/**</p> \n  <p>*&nbsp;Initializes&nbsp;or&nbsp;doubles&nbsp;table&nbsp;size.&nbsp;&nbsp;If&nbsp;null,&nbsp;allocates&nbsp;in</p> \n  <p>*&nbsp;accord&nbsp;with&nbsp;initial&nbsp;capacity&nbsp;target&nbsp;held&nbsp;in&nbsp;field&nbsp;threshold.</p> \n  <p>*&nbsp;Otherwise,&nbsp;because&nbsp;we&nbsp;are&nbsp;using&nbsp;power-of-two&nbsp;expansion,&nbsp;the</p> \n  <p>*&nbsp;elements&nbsp;from&nbsp;each&nbsp;bin&nbsp;must&nbsp;either&nbsp;stay&nbsp;at&nbsp;same&nbsp;index,&nbsp;or&nbsp;move</p> \n  <p>*&nbsp;with&nbsp;a&nbsp;power&nbsp;of&nbsp;two&nbsp;offset&nbsp;in&nbsp;the&nbsp;new&nbsp;table.</p> \n  <p>*</p> \n  <p>*&nbsp;@return&nbsp;the&nbsp;table</p> \n  <p>*/</p> \n  <p>final&nbsp;Node&lt;K,V&gt;[]&nbsp;resize()&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;[]&nbsp;oldTab&nbsp;=&nbsp;table;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;第一次&nbsp;put&nbsp;的时候，table&nbsp;=&nbsp;null</p> \n  <p>int&nbsp;oldCap&nbsp;=&nbsp;(oldTab&nbsp;==&nbsp;null)&nbsp;?&nbsp;0&nbsp;:&nbsp;oldTab.length;&nbsp;//&nbsp;oldCap&nbsp;=&nbsp;0</p> \n  <p>int&nbsp;oldThr&nbsp;=&nbsp;threshold;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;threshold=0,&nbsp;oldThr&nbsp;=&nbsp;0</p> \n  <p>int&nbsp;newCap,&nbsp;newThr&nbsp;=&nbsp;0;</p> \n  <p>if&nbsp;(oldCap&nbsp;&gt;&nbsp;0)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;条件不满足，往下走</p> \n  <p>if&nbsp;(oldCap&nbsp;&gt;=&nbsp;MAXIMUM_CAPACITY)&nbsp;{<!-- --></p> \n  <p>threshold&nbsp;=&nbsp;Integer.MAX_VALUE;</p> \n  <p>return&nbsp;oldTab;</p> \n  <p>}</p> \n  <p>else&nbsp;if&nbsp;((newCap&nbsp;=&nbsp;oldCap&nbsp;&lt;&lt;&nbsp;1)&nbsp;&lt;&nbsp;MAXIMUM_CAPACITY&nbsp;&amp;&amp;</p> \n  <p>oldCap&nbsp;&gt;=&nbsp;DEFAULT_INITIAL_CAPACITY)</p> \n  <p>newThr&nbsp;=&nbsp;oldThr&nbsp;&lt;&lt;&nbsp;1;&nbsp;//&nbsp;double&nbsp;threshold</p> \n  <p>}</p> \n  <p>else&nbsp;if&nbsp;(oldThr&nbsp;&gt;&nbsp;0)&nbsp;//&nbsp;initial&nbsp;capacity&nbsp;was&nbsp;placed&nbsp;in&nbsp;threshold</p> \n  <p>newCap&nbsp;=&nbsp;oldThr;</p> \n  <p>else&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;zero&nbsp;initial&nbsp;threshold&nbsp;signifies&nbsp;using&nbsp;defaults&nbsp;走到这里，进行默认初始化</p> \n  <p>newCap&nbsp;=&nbsp;DEFAULT_INITIAL_CAPACITY;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;DEFAULT_INITIAL_CAPACITY&nbsp;=&nbsp;1&nbsp;&lt;&lt;&nbsp;4&nbsp;=&nbsp;16,&nbsp;newCap&nbsp;=&nbsp;16;</p> \n  <p>newThr&nbsp;=&nbsp;(int)(DEFAULT_LOAD_FACTOR&nbsp;*&nbsp;DEFAULT_INITIAL_CAPACITY);&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;newThr&nbsp;=&nbsp;0.75&nbsp;*&nbsp;16&nbsp;=&nbsp;12;</p> \n  <p>}</p> \n  <p>if&nbsp;(newThr&nbsp;==&nbsp;0)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;条件不满足</p> \n  <p>float&nbsp;ft&nbsp;=&nbsp;(float)newCap&nbsp;*&nbsp;loadFactor;</p> \n  <p>newThr&nbsp;=&nbsp;(newCap&nbsp;&lt;&nbsp;MAXIMUM_CAPACITY&nbsp;&amp;&amp;&nbsp;ft&nbsp;&lt;&nbsp;(float)MAXIMUM_CAPACITY&nbsp;?</p> \n  <p>(int)ft&nbsp;:&nbsp;Integer.MAX_VALUE);</p> \n  <p>}</p> \n  <p>threshold&nbsp;=&nbsp;newThr;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;threshold&nbsp;=&nbsp;12;&nbsp;重置阀值为12</p> \n  <p>@SuppressWarnings({“rawtypes”,“unchecked”})</p> \n  <p>Node&lt;K,V&gt;[]&nbsp;newTab&nbsp;=&nbsp;(Node&lt;K,V&gt;[])new&nbsp;Node[newCap];&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;初始化&nbsp;newTab,&nbsp;length&nbsp;=&nbsp;16;</p> \n  <p>table&nbsp;=&nbsp;newTab;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;table&nbsp;初始化完成,&nbsp;length&nbsp;=&nbsp;16;</p> \n  <p>if&nbsp;(oldTab&nbsp;!=&nbsp;null)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;此时条件不满足，后续扩容的时候，走此if分支&nbsp;将数组元素复制到新数组</p> \n  <p>for&nbsp;(int&nbsp;j&nbsp;=&nbsp;0;&nbsp;j&nbsp;&lt;&nbsp;oldCap;&nbsp;++j)&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;&nbsp;e;</p> \n  <p>if&nbsp;((e&nbsp;=&nbsp;oldTab[j])&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>oldTab[j]&nbsp;=&nbsp;null;</p> \n  <p>if&nbsp;(e.next&nbsp;==&nbsp;null)</p> \n  <p>newTab[e.hash&nbsp;&amp;&nbsp;(newCap&nbsp;-&nbsp;1)]&nbsp;=&nbsp;e;</p> \n  <p>else&nbsp;if&nbsp;(e&nbsp;instanceof&nbsp;TreeNode)</p> \n  <p>((TreeNode&lt;K,V&gt;)e).split(this,&nbsp;newTab,&nbsp;j,&nbsp;oldCap);</p> \n  <p>else&nbsp;{&nbsp;//&nbsp;preserve&nbsp;order</p> \n  <p>Node&lt;K,V&gt;&nbsp;loHead&nbsp;=&nbsp;null,&nbsp;loTail&nbsp;=&nbsp;null;</p> \n  <p>Node&lt;K,V&gt;&nbsp;hiHead&nbsp;=&nbsp;null,&nbsp;hiTail&nbsp;=&nbsp;null;</p> \n  <p>Node&lt;K,V&gt;&nbsp;next;</p> \n  <p>do&nbsp;{<!-- --></p> \n  <p>next&nbsp;=&nbsp;e.next;</p> \n  <p>if&nbsp;((e.hash&nbsp;&amp;&nbsp;oldCap)&nbsp;==&nbsp;0)&nbsp;{<!-- --></p> \n  <p>if&nbsp;(loTail&nbsp;==&nbsp;null)</p> \n  <p>loHead&nbsp;=&nbsp;e;</p> \n  <p>else</p> \n  <p>loTail.next&nbsp;=&nbsp;e;</p> \n  <p>loTail&nbsp;=&nbsp;e;</p> \n  <p>}</p> \n  <p>else&nbsp;{<!-- --></p> \n  <p>if&nbsp;(hiTail&nbsp;==&nbsp;null)</p> \n  <p>hiHead&nbsp;=&nbsp;e;</p> \n  <p>else</p> \n  <p>hiTail.next&nbsp;=&nbsp;e;</p> \n  <p>hiTail&nbsp;=&nbsp;e;</p> \n  <p>}</p> \n  <p>}&nbsp;while&nbsp;((e&nbsp;=&nbsp;next)&nbsp;!=&nbsp;null);</p> \n  <p>if&nbsp;(loTail&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>loTail.next&nbsp;=&nbsp;null;</p> \n  <p>newTab[j]&nbsp;=&nbsp;loHead;</p> \n  <p>}</p> \n  <p>if&nbsp;(hiTail&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>hiTail.next&nbsp;=&nbsp;null;</p> \n  <p>newTab[j&nbsp;+&nbsp;oldCap]&nbsp;=&nbsp;hiHead;</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>return&nbsp;newTab;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;新数组</p> \n  <p>}</p> \n  <p>自此，问题 1 的答案就明了了</p> \n  <p><strong>table 的初始化时机是什么时候</strong></p> \n  <p>一般情况下，在第一次 put 的时候，调用 resize 方法进行 table 的初始化（懒初始化，懒加载思想在很多框架中都有应用！）</p> \n  <p>初始化的 table.length 是多少、阀值（threshold）是多少，实际能容下多少元素</p> \n  <ul>\n   <li> <p>默认情况下，table.length = 16; 指定了 initialCapacity 的情况放到问题 5 中分析</p> </li>\n   <li> <p>默认情况下，threshold = 12; 指定了 initialCapacity 的情况放到问题 5 中分析</p> </li>\n   <li> <p>默认情况下，能存放 12 个元素，当存放第 13 个元素后进行扩容</p> </li>\n  </ul> \n  <h4>问题 2 ：table 的扩容</h4> \n  <p>putVal 源码如下</p> \n  <p>/**</p> \n  <p>*&nbsp;Implements&nbsp;Map.put&nbsp;and&nbsp;related&nbsp;methods</p> \n  <p>*</p> \n  <p>*&nbsp;@param&nbsp;hash&nbsp;hash&nbsp;for&nbsp;key</p> \n  <p>*&nbsp;@param&nbsp;key&nbsp;the&nbsp;key</p> \n  <p>*&nbsp;@param&nbsp;value&nbsp;the&nbsp;value&nbsp;to&nbsp;put</p> \n  <p>*&nbsp;@param&nbsp;onlyIfAbsent&nbsp;if&nbsp;true,&nbsp;don’t&nbsp;change&nbsp;existing&nbsp;value</p> \n  <p>*&nbsp;@param&nbsp;evict&nbsp;if&nbsp;false,&nbsp;the&nbsp;table&nbsp;is&nbsp;in&nbsp;creation&nbsp;mode.</p> \n  <p>*&nbsp;@return&nbsp;previous&nbsp;value,&nbsp;or&nbsp;null&nbsp;if&nbsp;none</p> \n  <p>*/</p> \n  <p>final&nbsp;V&nbsp;putVal(int&nbsp;hash,&nbsp;K&nbsp;key,&nbsp;V&nbsp;value,&nbsp;boolean&nbsp;onlyIfAbsent,</p> \n  <p>boolean&nbsp;evict)&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;[]&nbsp;tab;&nbsp;Node&lt;K,V&gt;&nbsp;p;&nbsp;int&nbsp;n,&nbsp;i;</p> \n  <p>if&nbsp;((tab&nbsp;=&nbsp;table)&nbsp;==&nbsp;null&nbsp;||&nbsp;(n&nbsp;=&nbsp;tab.length)&nbsp;==&nbsp;0)</p> \n  <p>n&nbsp;=&nbsp;(tab&nbsp;=&nbsp;resize()).length;</p> \n  <p>if&nbsp;((p&nbsp;=&nbsp;tab[i&nbsp;=&nbsp;(n&nbsp;-&nbsp;1)&nbsp;&amp;&nbsp;hash])&nbsp;==&nbsp;null)</p> \n  <p>tab[i]&nbsp;=&nbsp;newNode(hash,&nbsp;key,&nbsp;value,&nbsp;null);</p> \n  <p>else&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;&nbsp;e;&nbsp;K&nbsp;k;</p> \n  <p>if&nbsp;(p.hash&nbsp;==&nbsp;hash&nbsp;&amp;&amp;</p> \n  <p>((k&nbsp;=&nbsp;p.key)&nbsp;==&nbsp;key&nbsp;||&nbsp;(key&nbsp;!=&nbsp;null&nbsp;&amp;&amp;&nbsp;key.equals(k))))</p> \n  <p>e&nbsp;=&nbsp;p;</p> \n  <p>else&nbsp;if&nbsp;(p&nbsp;instanceof&nbsp;TreeNode)</p> \n  <p>e&nbsp;=&nbsp;((TreeNode&lt;K,V&gt;)p).putTreeVal(this,&nbsp;tab,&nbsp;hash,&nbsp;key,&nbsp;value);</p> \n  <p>else&nbsp;{<!-- --></p> \n  <p>for&nbsp;(int&nbsp;binCount&nbsp;=&nbsp;0;&nbsp;;&nbsp;++binCount)&nbsp;{<!-- --></p> \n  <p>if&nbsp;((e&nbsp;=&nbsp;p.next)&nbsp;==&nbsp;null)&nbsp;{<!-- --></p> \n  <p>p.next&nbsp;=&nbsp;newNode(hash,&nbsp;key,&nbsp;value,&nbsp;null);</p> \n  <p>if&nbsp;(binCount&nbsp;&gt;=&nbsp;TREEIFY_THRESHOLD&nbsp;-&nbsp;1)&nbsp;//&nbsp;-1&nbsp;for&nbsp;1st</p> \n  <p>treeifyBin(tab,&nbsp;hash);</p> \n  <p>break;</p> \n  <p>}</p> \n  <p>if&nbsp;(e.hash&nbsp;==&nbsp;hash&nbsp;&amp;&amp;</p> \n  <p>((k&nbsp;=&nbsp;e.key)&nbsp;==&nbsp;key&nbsp;||&nbsp;(key&nbsp;!=&nbsp;null&nbsp;&amp;&amp;&nbsp;key.equals(k))))</p> \n  <p>break;</p> \n  <p>p&nbsp;=&nbsp;e;</p> \n  <p>}</p> \n  <p>}</p> \n  <p>if&nbsp;(e&nbsp;!=&nbsp;null)&nbsp;{&nbsp;//&nbsp;existing&nbsp;mapping&nbsp;for&nbsp;key</p> \n  <p>V&nbsp;oldValue&nbsp;=&nbsp;e.value;</p> \n  <p>if&nbsp;(!onlyIfAbsent&nbsp;||&nbsp;oldValue&nbsp;==&nbsp;null)</p> \n  <p>e.value&nbsp;=&nbsp;value;</p> \n  <p>afterNodeAccess(e);</p> \n  <p>return&nbsp;oldValue;</p> \n  <p>}</p> \n  <p>}</p> \n  <p>++modCount;</p> \n  <p>if&nbsp;(++size&nbsp;&gt;&nbsp;threshold)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;当size（已存放元素个数）&nbsp;&gt;&nbsp;thrshold（阀值），进行扩容</p> \n  <p>resize();</p> \n  <p>afterNodeInsertion(evict);</p> \n  <p>return&nbsp;null;</p> \n  <p>}</p> \n  <p>还是调用 resize() 进行扩容，但与初始化时不同（注意看注释）</p> \n  <p>/**</p> \n  <p>*&nbsp;Initializes&nbsp;or&nbsp;doubles&nbsp;table&nbsp;size.&nbsp;&nbsp;If&nbsp;null,&nbsp;allocates&nbsp;in</p> \n  <p>*&nbsp;accord&nbsp;with&nbsp;initial&nbsp;capacity&nbsp;target&nbsp;held&nbsp;in&nbsp;field&nbsp;threshold.</p> \n  <p>*&nbsp;Otherwise,&nbsp;because&nbsp;we&nbsp;are&nbsp;using&nbsp;power-of-two&nbsp;expansion,&nbsp;the</p> \n  <p>*&nbsp;elements&nbsp;from&nbsp;each&nbsp;bin&nbsp;must&nbsp;either&nbsp;stay&nbsp;at&nbsp;same&nbsp;index,&nbsp;or&nbsp;move</p> \n  <p>*&nbsp;with&nbsp;a&nbsp;power&nbsp;of&nbsp;two&nbsp;offset&nbsp;in&nbsp;the&nbsp;new&nbsp;table.</p> \n  <p>*</p> \n  <p>*&nbsp;@return&nbsp;the&nbsp;table</p> \n  <p>*/</p> \n  <p>final&nbsp;Node&lt;K,V&gt;[]&nbsp;resize()&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;[]&nbsp;oldTab&nbsp;=&nbsp;table;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;此时的&nbsp;table&nbsp;!=&nbsp;null，oldTab&nbsp;指向旧的&nbsp;table</p> \n  <p>int&nbsp;oldCap&nbsp;=&nbsp;(oldTab&nbsp;==&nbsp;null)&nbsp;?&nbsp;0&nbsp;:&nbsp;oldTab.length;&nbsp;//&nbsp;oldCap&nbsp;=&nbsp;table.length;&nbsp;第一次扩容时是&nbsp;16</p> \n  <p>int&nbsp;oldThr&nbsp;=&nbsp;threshold;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;threshold=12,&nbsp;oldThr&nbsp;=&nbsp;12;</p> \n  <p>int&nbsp;newCap,&nbsp;newThr&nbsp;=&nbsp;0;</p> \n  <p>if&nbsp;(oldCap&nbsp;&gt;&nbsp;0)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;条件满足，走此分支</p> \n  <p>if&nbsp;(oldCap&nbsp;&gt;=&nbsp;MAXIMUM_CAPACITY)&nbsp;{<!-- --></p> \n  <p>threshold&nbsp;=&nbsp;Integer.MAX_VALUE;</p> \n  <p>return&nbsp;oldTab;</p> \n  <p>}</p> \n  <p>else&nbsp;if&nbsp;((newCap&nbsp;=&nbsp;oldCap&nbsp;&lt;&lt;&nbsp;1)&nbsp;&lt;&nbsp;MAXIMUM_CAPACITY&nbsp;&amp;&amp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;oldCap左移一位;&nbsp;newCap&nbsp;=&nbsp;16&nbsp;&lt;&lt;&nbsp;1&nbsp;=&nbsp;32;</p> \n  <p>oldCap&nbsp;&gt;=&nbsp;DEFAULT_INITIAL_CAPACITY)</p> \n  <p>newThr&nbsp;=&nbsp;oldThr&nbsp;&lt;&lt;&nbsp;1;&nbsp;//&nbsp;double&nbsp;threshold&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;newThr&nbsp;=&nbsp;12&nbsp;&lt;&lt;&nbsp;1&nbsp;=&nbsp;24;</p> \n  <p>}</p> \n  <p>else&nbsp;if&nbsp;(oldThr&nbsp;&gt;&nbsp;0)&nbsp;//&nbsp;initial&nbsp;capacity&nbsp;was&nbsp;placed&nbsp;in&nbsp;threshold</p> \n  <p>newCap&nbsp;=&nbsp;oldThr;</p> \n  <p>else&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;zero&nbsp;initial&nbsp;threshold&nbsp;signifies&nbsp;using&nbsp;defaults</p> \n  <p>newCap&nbsp;=&nbsp;DEFAULT_INITIAL_CAPACITY;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;DEFAULT_INITIAL_CAPACITY&nbsp;=&nbsp;1&nbsp;&lt;&lt;&nbsp;4&nbsp;=&nbsp;16,&nbsp;newCap&nbsp;=&nbsp;16;</p> \n  <p>newThr&nbsp;=&nbsp;(int)(DEFAULT_LOAD_FACTOR&nbsp;*&nbsp;DEFAULT_INITIAL_CAPACITY);</p> \n  <p>}</p> \n  <p>if&nbsp;(newThr&nbsp;==&nbsp;0)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;条件不满足</p> \n  <p>float&nbsp;ft&nbsp;=&nbsp;(float)newCap&nbsp;*&nbsp;loadFactor;</p> \n  <p>newThr&nbsp;=&nbsp;(newCap&nbsp;&lt;&nbsp;MAXIMUM_CAPACITY&nbsp;&amp;&amp;&nbsp;ft&nbsp;&lt;&nbsp;(float)MAXIMUM_CAPACITY&nbsp;?</p> \n  <p>(int)ft&nbsp;:&nbsp;Integer.MAX_VALUE);</p> \n  <p>}</p> \n  <p>threshold&nbsp;=&nbsp;newThr;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;threshold&nbsp;=&nbsp;newThr&nbsp;=&nbsp;24;&nbsp;重置阀值为&nbsp;24</p> \n  <p>@SuppressWarnings({“rawtypes”,“unchecked”})</p> \n  <p>Node&lt;K,V&gt;[]&nbsp;newTab&nbsp;=&nbsp;(Node&lt;K,V&gt;[])new&nbsp;Node[newCap];&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;初始化&nbsp;newTab,&nbsp;length&nbsp;=&nbsp;32;</p> \n  <p>table&nbsp;=&nbsp;newTab;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;table&nbsp;指向&nbsp;newTab,&nbsp;length&nbsp;=&nbsp;32;</p> \n  <p>if&nbsp;(oldTab&nbsp;!=&nbsp;null)&nbsp;{&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;扩容后，将&nbsp;oldTab(旧table)&nbsp;中的元素移到&nbsp;newTab（新table）中</p> \n  <p>for&nbsp;(int&nbsp;j&nbsp;=&nbsp;0;&nbsp;j&nbsp;&lt;&nbsp;oldCap;&nbsp;++j)&nbsp;{<!-- --></p> \n  <p>Node&lt;K,V&gt;&nbsp;e;</p> \n  <p>if&nbsp;((e&nbsp;=&nbsp;oldTab[j])&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>oldTab[j]&nbsp;=&nbsp;null;</p> \n  <p>if&nbsp;(e.next&nbsp;==&nbsp;null)</p> \n  <p>newTab[e.hash&nbsp;&amp;&nbsp;(newCap&nbsp;-&nbsp;1)]&nbsp;=&nbsp;e;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//</p> \n  <p>else&nbsp;if&nbsp;(e&nbsp;instanceof&nbsp;TreeNode)</p> \n  <p>((TreeNode&lt;K,V&gt;)e).split(this,&nbsp;newTab,&nbsp;j,&nbsp;oldCap);</p> \n  <p>else&nbsp;{&nbsp;//&nbsp;preserve&nbsp;order</p> \n  <p>Node&lt;K,V&gt;&nbsp;loHead&nbsp;=&nbsp;null,&nbsp;loTail&nbsp;=&nbsp;null;</p> \n  <p>Node&lt;K,V&gt;&nbsp;hiHead&nbsp;=&nbsp;null,&nbsp;hiTail&nbsp;=&nbsp;null;</p> \n  <p>Node&lt;K,V&gt;&nbsp;next;</p> \n  <p>do&nbsp;{<!-- --></p> \n  <p>next&nbsp;=&nbsp;e.next;</p> \n  <p>if&nbsp;((e.hash&nbsp;&amp;&nbsp;oldCap)&nbsp;==&nbsp;0)&nbsp;{<!-- --></p> \n  <p>if&nbsp;(loTail&nbsp;==&nbsp;null)</p> \n  <p>loHead&nbsp;=&nbsp;e;</p> \n  <p>else</p> \n  <p>loTail.next&nbsp;=&nbsp;e;</p> \n  <p>loTail&nbsp;=&nbsp;e;</p> \n  <p>}</p> \n  <p>else&nbsp;{<!-- --></p> \n  <p>if&nbsp;(hiTail&nbsp;==&nbsp;null)</p> \n  <p>hiHead&nbsp;=&nbsp;e;</p> \n  <p>else</p> \n  <p>hiTail.next&nbsp;=&nbsp;e;</p> \n  <p>hiTail&nbsp;=&nbsp;e;</p> \n  <p>}</p> \n  <p>}&nbsp;while&nbsp;((e&nbsp;=&nbsp;next)&nbsp;!=&nbsp;null);</p> \n  <p>if&nbsp;(loTail&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>loTail.next&nbsp;=&nbsp;null;</p> \n  <p>newTab[j]&nbsp;=&nbsp;loHead;</p> \n  <p>}</p> \n  <p>if&nbsp;(hiTail&nbsp;!=&nbsp;null)&nbsp;{<!-- --></p> \n  <p>hiTail.next&nbsp;=&nbsp;null;</p> \n  <p>newTab[j&nbsp;+&nbsp;oldCap]&nbsp;=&nbsp;hiHead;</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>}</p> \n  <p>return&nbsp;newTab;</p> \n  <p>}</p> \n  <p>自此，问题 2 的答案也就清晰了</p> \n  <p>什么时候触发扩容，扩容之后的 table.length、阀值各是多少</p> \n  <ul>\n   <li> <p>当 size &gt; threshold 的时候进行扩容</p> </li>\n   <li> <p>扩容之后的 table.length = 旧 table.length * 2,</p> </li>\n   <li> <p>扩容之后的 threshold = 旧 threshold * 2</p> </li>\n  </ul> \n  <h4>问题 3、4 ：2 的 n 次幂</h4> \n  <p>table 是一个数组，那么如何最快的将元素 e 放入数组 ？当然是找到元素 e 在 table 中对应的位置 index ，然后 table[index] = e; 就好了；如何找到 e 在 table 中的位置了 ？</p> \n  <p>我们知道只能通过数组下标（索引）操作数组，而数组的下标类型又是 int ，如果 e 是 int 类型，那好说，就直接用 e 来做数组下标（若 e &gt; table.length，则可以 e % table.length 来获取下标），可 key - value 中的 key 类型不一定，所以我们需要一种统一的方式将 key 转换成 int ，最好是一个 key 对应一个唯一的 int (目前还不可能, int有范围限制，对转换方法要求也极高)，所以引入了 hash 方法</p> \n  <p>static&nbsp;final&nbsp;int&nbsp;hash(Object&nbsp;key)&nbsp;{<!-- --></p> \n  <p>int&nbsp;h;</p> \n  <p>return&nbsp;(key&nbsp;==&nbsp;null)&nbsp;?&nbsp;0&nbsp;:&nbsp;(h&nbsp;=&nbsp;key.hashCode())&nbsp;^&nbsp;(h&nbsp;&gt;&gt;&gt;&nbsp;16);&nbsp;&nbsp;//&nbsp;这里的处理，有兴趣的可以琢磨下；能够减少碰撞</p> \n  <p>}</p> \n  <p>实现 key 到 int 的转换（关于 hash，本文不展开讨论）。拿到了 key 对应的 int h 之后，我们最容易想到的对 value 的 put 和 get 操作也许如下</p> \n  <p>//&nbsp;put</p> \n  <p>table[h&nbsp;%&nbsp;table.length]&nbsp;=&nbsp;value;</p> \n  <p>//&nbsp;get</p> \n  <p>e&nbsp;=&nbsp;table[h&nbsp;%&nbsp;table.length];<br> <strong>自我介绍一下，小编13年上海交大毕业，曾经在小公司待过，也去过华为、OPPO等大厂，18年进入阿里一直到现在。</strong></p> \n  <p><strong>深知大多数Java工程师，想要提升技能，往往是自己摸索成长或者是报班学习，但对于培训机构动则几千的学费，着实压力不小。自己不成体系的自学效果低效又漫长，而且极易碰到天花板技术停滞不前！</strong></p> \n  <p><strong>因此收集整理了一份《2024年Java开发全套学习资料》，初衷也很简单，就是希望能够帮助到想自学提升又不知道该从何学起的朋友，同时减轻大家的负担。</strong><img src=\"https://i-blog.csdnimg.cn/blog_migrate/c80c92e9a042eae8346996133e15acdb.jpeg\" alt=\"img\"></p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/04175337479972ae9c0682b1cfceb1b0.png\" alt=\"\"></p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/93901eaec622e666063310a976033676.png\" alt=\"\"></p> \n  <p><strong>既有适合小白学习的零基础资料，也有适合3年以上经验的小伙伴深入学习提升的进阶课程，基本涵盖了95%以上Java开发知识点，真正体系化！</strong></p> \n  <p><strong>由于文件比较大，这里只是将部分目录截图出来，每个节点里面都包含大厂面经、学习笔记、源码讲义、实战项目、讲解视频，并且会持续更新！</strong></p> \n  <p><strong>如果你觉得这些内容对你有帮助，可以扫码获取！！（备注Java获取）</strong></p> \n  <img src=\"https://i-blog.csdnimg.cn/blog_migrate/c5ec0bf6a209711c06722a69d446fc10.jpeg\" alt=\"img\"> \n  <h2>最后</h2> \n  <p>各位读者，由于本篇幅度过长，为了避免影响阅读体验，下面我就大概概括了整理了</p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/6287297b3d1f33ebbd0bc0b657b888ba.png\" alt=\"\"></p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/b5d93d44cb49217f54a9cd65c7e8c7c5.png\" alt=\"\"></p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/f7606d3f94a9c73b285bebf04f43c505.png\" alt=\"\"></p> \n  <p><img src=\"https://i-blog.csdnimg.cn/blog_migrate/fab6837acf17d31bd528474a9fb4c6fe.png\" alt=\"\"></p> \n  <p><strong>《互联网大厂面试真题解析、进阶开发核心学习笔记、全套讲解视频、实战项目源码讲义》<a href=\"https://bbs.csdn.net/forums/f76c2498e3b04ae99081eaf6e6cf692c\">点击传送门即可获取！</a></strong><br> 该从何学起的朋友，同时减轻大家的负担。**[外链图片转存中…(img-UYdPzRtk-1713382023452)]</p> \n  <p>[外链图片转存中…(img-f7BgCOIS-1713382023453)]</p> \n  <p>[外链图片转存中…(img-9pgj8gWN-1713382023453)]</p> \n  <p><strong>既有适合小白学习的零基础资料，也有适合3年以上经验的小伙伴深入学习提升的进阶课程，基本涵盖了95%以上Java开发知识点，真正体系化！</strong></p> \n  <p><strong>由于文件比较大，这里只是将部分目录截图出来，每个节点里面都包含大厂面经、学习笔记、源码讲义、实战项目、讲解视频，并且会持续更新！</strong></p> \n  <p><strong>如果你觉得这些内容对你有帮助，可以扫码获取！！（备注Java获取）</strong></p> \n  <img src=\"https://i-blog.csdnimg.cn/blog_migrate/c5ec0bf6a209711c06722a69d446fc10.jpeg\" alt=\"img\"> \n  <h2>最后</h2> \n  <p>各位读者，由于本篇幅度过长，为了避免影响阅读体验，下面我就大概概括了整理了</p> \n  <p>[外链图片转存中…(img-CElYEPzY-1713382023453)]</p> \n  <p>[外链图片转存中…(img-SqlYWP0V-1713382023454)]</p> \n  <p>[外链图片转存中…(img-AyM9IX1g-1713382023454)]</p> \n  <p>[外链图片转存中…(img-cpooMBS2-1713382023454)]</p> \n  <p><strong>《互联网大厂面试真题解析、进阶开发核心学习笔记、全套讲解视频、实战项目源码讲义》<a href=\"https://bbs.csdn.net/forums/f76c2498e3b04ae99081eaf6e6cf692c\">点击传送门即可获取！</a></strong></p> \n </div> \n <link href=\"https://csdnimg.cn/release/blogv2/dist/mdeditor/css/editerView/markdown_views-ecfda744a4.css\" rel=\"stylesheet\"> \n <link href=\"https://csdnimg.cn/release/blogv2/dist/mdeditor/css/style-e504d6a974.css\" rel=\"stylesheet\"> \n</div>', '}\n\n/\\*\\*\n\n\\* 红黑树结构\n\n\\*/\n\nstatic final class TreeNode\\<K,V\\> extends LinkedHashMap.Entry\\<K,V\\> {\n\nTreeNode\\<K,V\\> parent; // red-black tree links\n\nTreeNode\\<K,V\\> left;\n\nTreeNode\\<K,V\\> right;\n\nTreeNode\\<K,V\\> prev; // needed to unlink next upon deletion\n\nboolean red;\n\n...\n\n![f0f8c04fadb3232519aaa2d65c6c95d9.png](https://i-blog.csdnimg.cn/blog_migrate/37c21a05a6107a9f9cd540b74b4e2cce.png)\n\n图片\n\n但面试往往会问的比较细，例如下面的容量问题，我们能答上来几个？\n\n1、table 的初始化时机是什么时候，初始化的 table.length 是多少、阀值（threshold）是多少，实际能容下多少元素\n\n2、什么时候触发扩容，扩容之后的 table.length、阀值各是多少？\n\n3、table 的 length 为什么是 2 的 n 次幂\n\n4、求索引的时候为什么是：h\\&(length-1)，而不是 h\\&length，更不是 h%length\n\n5、 Map map = new HashMap(1000); 当我们存入多少个元素时会触发map的扩容；Map map1 = new HashMap(10000); 我们存入第 10001个元素时会触发 map1 扩容吗\n\n6、为什么加载因子的默认值是 0.75，并且不推荐我们修改\n\n由于我们平时关注的少，一旦碰上这样的 连击 + 暴击，我们往往不知所措、无从应对；接下来我们看看上面的 6 个问题，是不是真的难到无法理解 ，还是我们不够细心、在自信的自我认为\n\n斗智斗勇，见招拆招\n\n*** ** * ** ***\n\n上述的问题，我们如何去找答案 ? 方式有很多种，用的最多的，我想应该是上网查资料、看别人的博客，但我认为最有效、准确的方式是读源码\n\n#### 问题 1：table 的初始化\n\nHashMap 的构造方法有如下 4 种\n\n/\\*\\*\n\n\\* 构造方法 1\n\n\\*\n\n\\* 通过 指定的 initialCapacity 和 loadFactor 实例化一个空的 HashMap 对象\n\n\\*/\n\npublic HashMap(int initialCapacity, float loadFactor) {\n\nif (initialCapacity \\< 0)\n\nthrow new IllegalArgumentException(\"Illegal initial capacity: \" +\n\ninitialCapacity);\n\nif (initialCapacity \\> MAXIMUM_CAPACITY)\n\ninitialCapacity = MAXIMUM_CAPACITY;\n\nif (loadFactor \\<= 0 \\|\\| Float.isNaN(loadFactor))\n\nthrow new IllegalArgumentException(\"Illegal load factor: \" +\n\nloadFactor);\n\nthis.loadFactor = loadFactor;\n\nthis.threshold = tableSizeFor(initialCapacity);\n\n}\n\n/\\*\\*\n\n\\* 构造方法 2\n\n\\*\n\n\\* 通过指定的 initialCapacity 和 默认的 loadFactor(0.75) 实例化一个空的 HashMap 对象\n\n\\*/\n\npublic HashMap(int initialCapacity) {\n\nthis(initialCapacity, DEFAULT_LOAD_FACTOR);\n\n}\n\n/\\*\\*\n\n\\* 构造方法 3\n\n\\*\n\n\\* 通过默认的 initialCapacity 和 默认的 loadFactor(0.75) 实例化一个空的 HashMap 对象\n\n\\*/\n\npublic HashMap() {\n\nthis.loadFactor = DEFAULT_LOAD_FACTOR; // all other fields defaulted\n\n}\n\n/\\*\\*\n\n\\*\n\n\\* 构造方法 4\n\n\\* 通过指定的 Map 对象实例化一个 HashMap 对象\n\n\\*/\n\npublic HashMap(Map\\<? extends K, ? extends V\\> m) {\n\nthis.loadFactor = DEFAULT_LOAD_FACTOR;\n\nputMapEntries(m, false);\n\n}\n\n构造方式 4 和 构造方式 1 实际应用的不多，构造方式 2 直接调用的 1（底层实现完全一致），构造方式 2 和 构造方式 3 比较常用，而最常用的是构造方式 3；此时我们以构造方式 3 为前提来分析，而构造方式 2 我们则在问题 5 中来分析\n\n使用方式 1 实例化 HashMap 的时候，table 并未进行初始化，那 table 是何时进行初始化的了 ？平时我们是如何使用 HashMap 的，先实例化、然后 put、然后进行其他操作，如下\n\nMap\\<String,Object\\> map = new HashMap();\n\nmap.put(\"name\", \"张三\");\n\nmap.put(\"age\", 21);\n\n// 后续操作\n\n...\n\n既然实例化的时候未进行 table 的初始化，那是不是在 put 的时候初始化的了，我们来确认下\n\n![ef5de77244acb35b203582aed2a7486a.gif](https://i-blog.csdnimg.cn/blog_migrate/0ec5b58f1f3c2219eb641d84fa40dfa2.gif)\n\n图片\n\nresize() 初始化 table 或 对 table 进行双倍扩容，源码如下（注意看注释）\n\n/\\*\\*\n\n\\* Initializes or doubles table size. If null, allocates in\n\n\\* accord with initial capacity target held in field threshold.\n\n\\* Otherwise, because we are using power-of-two expansion, the\n\n\\* elements from each bin must either stay at same index, or move\n\n\\* with a power of two offset in the new table.\n\n\\*\n\n\\* @return the table\n\n\\*/\n\nfinal Node\\<K,V\\>\\[\\] resize() {\n\nNode\\<K,V\\>\\[\\] oldTab = table; // 第一次 put 的时候，table = null\n\nint oldCap = (oldTab == null) ? 0 : oldTab.length; // oldCap = 0\n\nint oldThr = threshold; // threshold=0, oldThr = 0\n\nint newCap, newThr = 0;\n\nif (oldCap \\> 0) { // 条件不满足，往下走\n\nif (oldCap \\>= MAXIMUM_CAPACITY) {\n\nthreshold = Integer.MAX_VALUE;\n\nreturn oldTab;\n\n}\n\nelse if ((newCap = oldCap \\<\\< 1) \\< MAXIMUM_CAPACITY \\&\\&\n\noldCap \\>= DEFAULT_INITIAL_CAPACITY)\n\nnewThr = oldThr \\<\\< 1; // double threshold\n\n}\n\nelse if (oldThr \\> 0) // initial capacity was placed in threshold\n\nnewCap = oldThr;\n\nelse { // zero initial threshold signifies using defaults 走到这里，进行默认初始化\n\nnewCap = DEFAULT_INITIAL_CAPACITY; // DEFAULT_INITIAL_CAPACITY = 1 \\<\\< 4 = 16, newCap = 16;\n\nnewThr = (int)(DEFAULT_LOAD_FACTOR \\* DEFAULT_INITIAL_CAPACITY); // newThr = 0.75 \\* 16 = 12;\n\n}\n\nif (newThr == 0) { // 条件不满足\n\nfloat ft = (float)newCap \\* loadFactor;\n\nnewThr = (newCap \\< MAXIMUM_CAPACITY \\&\\& ft \\< (float)MAXIMUM_CAPACITY ?\n\n(int)ft : Integer.MAX_VALUE);\n\n}\n\nthreshold = newThr; // threshold = 12; 重置阀值为12\n\n@SuppressWarnings({\"rawtypes\",\"unchecked\"})\n\nNode\\<K,V\\>\\[\\] newTab = (Node\\<K,V\\>\\[\\])new Node\\[newCap\\]; // 初始化 newTab, length = 16;\n\ntable = newTab; // table 初始化完成, length = 16;\n\nif (oldTab != null) { // 此时条件不满足，后续扩容的时候，走此if分支 将数组元素复制到新数组\n\nfor (int j = 0; j \\< oldCap; ++j) {\n\nNode\\<K,V\\> e;\n\nif ((e = oldTab\\[j\\]) != null) {\n\noldTab\\[j\\] = null;\n\nif (e.next == null)\n\nnewTab\\[e.hash \\& (newCap - 1)\\] = e;\n\nelse if (e instanceof TreeNode)\n\n((TreeNode\\<K,V\\>)e).split(this, newTab, j, oldCap);\n\nelse { // preserve order\n\nNode\\<K,V\\> loHead = null, loTail = null;\n\nNode\\<K,V\\> hiHead = null, hiTail = null;\n\nNode\\<K,V\\> next;\n\ndo {\n\nnext = e.next;\n\nif ((e.hash \\& oldCap) == 0) {\n\nif (loTail == null)\n\nloHead = e;\n\nelse\n\nloTail.next = e;\n\nloTail = e;\n\n}\n\nelse {\n\nif (hiTail == null)\n\nhiHead = e;\n\nelse\n\nhiTail.next = e;\n\nhiTail = e;\n\n}\n\n} while ((e = next) != null);\n\nif (loTail != null) {\n\nloTail.next = null;\n\nnewTab\\[j\\] = loHead;\n\n}\n\nif (hiTail != null) {\n\nhiTail.next = null;\n\nnewTab\\[j + oldCap\\] = hiHead;\n\n}\n\n}\n\n}\n\n}\n\n}\n\nreturn newTab; // 新数组\n\n}\n\n自此，问题 1 的答案就明了了\n\n**table 的初始化时机是什么时候**\n\n一般情况下，在第一次 put 的时候，调用 resize 方法进行 table 的初始化（懒初始化，懒加载思想在很多框架中都有应用！）\n\n初始化的 table.length 是多少、阀值（threshold）是多少，实际能容下多少元素\n\n* 默认情况下，table.length = 16; 指定了 initialCapacity 的情况放到问题 5 中分析\n\n* 默认情况下，threshold = 12; 指定了 initialCapacity 的情况放到问题 5 中分析\n\n* 默认情况下，能存放 12 个元素，当存放第 13 个元素后进行扩容\n\n#### 问题 2 ：table 的扩容\n\nputVal 源码如下\n\n/\\*\\*\n\n\\* Implements Map.put and related methods\n\n\\*\n\n\\* @param hash hash for key\n\n\\* @param key the key\n\n\\* @param value the value to put\n\n\\* @param onlyIfAbsent if true, don\'t change existing value\n\n\\* @param evict if false, the table is in creation mode.\n\n\\* @return previous value, or null if none\n\n\\*/\n\nfinal V putVal(int hash, K key, V value, boolean onlyIfAbsent,\n\nboolean evict) {\n\nNode\\<K,V\\>\\[\\] tab; Node\\<K,V\\> p; int n, i;\n\nif ((tab = table) == null \\|\\| (n = tab.length) == 0)\n\nn = (tab = resize()).length;\n\nif ((p = tab\\[i = (n - 1) \\& hash\\]) == null)\n\ntab\\[i\\] = newNode(hash, key, value, null);\n\nelse {\n\nNode\\<K,V\\> e; K k;\n\nif (p.hash == hash \\&\\&\n\n((k = p.key) == key \\|\\| (key != null \\&\\& key.equals(k))))\n\ne = p;\n\nelse if (p instanceof TreeNode)\n\ne = ((TreeNode\\<K,V\\>)p).putTreeVal(this, tab, hash, key, value);\n\nelse {\n\nfor (int binCount = 0; ; ++binCount) {\n\nif ((e = p.next) == null) {\n\np.next = newNode(hash, key, value, null);\n\nif (binCount \\>= TREEIFY_THRESHOLD - 1) // -1 for 1st\n\ntreeifyBin(tab, hash);\n\nbreak;\n\n}\n\nif (e.hash == hash \\&\\&\n\n((k = e.key) == key \\|\\| (key != null \\&\\& key.equals(k))))\n\nbreak;\n\np = e;\n\n}\n\n}\n\nif (e != null) { // existing mapping for key\n\nV oldValue = e.value;\n\nif (!onlyIfAbsent \\|\\| oldValue == null)\n\ne.value = value;\n\nafterNodeAccess(e);\n\nreturn oldValue;\n\n}\n\n}\n\n++modCount;\n\nif (++size \\> threshold) // 当size（已存放元素个数） \\> thrshold（阀值），进行扩容\n\nresize();\n\nafterNodeInsertion(evict);\n\nreturn null;\n\n}\n\n还是调用 resize() 进行扩容，但与初始化时不同（注意看注释）\n\n/\\*\\*\n\n\\* Initializes or doubles table size. If null, allocates in\n\n\\* accord with initial capacity target held in field threshold.\n\n\\* Otherwise, because we are using power-of-two expansion, the\n\n\\* elements from each bin must either stay at same index, or move\n\n\\* with a power of two offset in the new table.\n\n\\*\n\n\\* @return the table\n\n\\*/\n\nfinal Node\\<K,V\\>\\[\\] resize() {\n\nNode\\<K,V\\>\\[\\] oldTab = table; // 此时的 table != null，oldTab 指向旧的 table\n\nint oldCap = (oldTab == null) ? 0 : oldTab.length; // oldCap = table.length; 第一次扩容时是 16\n\nint oldThr = threshold; // threshold=12, oldThr = 12;\n\nint newCap, newThr = 0;\n\nif (oldCap \\> 0) { // 条件满足，走此分支\n\nif (oldCap \\>= MAXIMUM_CAPACITY) {\n\nthreshold = Integer.MAX_VALUE;\n\nreturn oldTab;\n\n}\n\nelse if ((newCap = oldCap \\<\\< 1) \\< MAXIMUM_CAPACITY \\&\\& // oldCap左移一位; newCap = 16 \\<\\< 1 = 32;\n\noldCap \\>= DEFAULT_INITIAL_CAPACITY)\n\nnewThr = oldThr \\<\\< 1; // double threshold // newThr = 12 \\<\\< 1 = 24;\n\n}\n\nelse if (oldThr \\> 0) // initial capacity was placed in threshold\n\nnewCap = oldThr;\n\nelse { // zero initial threshold signifies using defaults\n\nnewCap = DEFAULT_INITIAL_CAPACITY; // DEFAULT_INITIAL_CAPACITY = 1 \\<\\< 4 = 16, newCap = 16;\n\nnewThr = (int)(DEFAULT_LOAD_FACTOR \\* DEFAULT_INITIAL_CAPACITY);\n\n}\n\nif (newThr == 0) { // 条件不满足\n\nfloat ft = (float)newCap \\* loadFactor;\n\nnewThr = (newCap \\< MAXIMUM_CAPACITY \\&\\& ft \\< (float)MAXIMUM_CAPACITY ?\n\n(int)ft : Integer.MAX_VALUE);\n\n}\n\nthreshold = newThr; // threshold = newThr = 24; 重置阀值为 24\n\n@SuppressWarnings({\"rawtypes\",\"unchecked\"})\n\nNode\\<K,V\\>\\[\\] newTab = (Node\\<K,V\\>\\[\\])new Node\\[newCap\\]; // 初始化 newTab, length = 32;\n\ntable = newTab; // table 指向 newTab, length = 32;\n\nif (oldTab != null) { // 扩容后，将 oldTab(旧table) 中的元素移到 newTab（新table）中\n\nfor (int j = 0; j \\< oldCap; ++j) {\n\nNode\\<K,V\\> e;\n\nif ((e = oldTab\\[j\\]) != null) {\n\noldTab\\[j\\] = null;\n\nif (e.next == null)\n\nnewTab\\[e.hash \\& (newCap - 1)\\] = e; //\n\nelse if (e instanceof TreeNode)\n\n((TreeNode\\<K,V\\>)e).split(this, newTab, j, oldCap);\n\nelse { // preserve order\n\nNode\\<K,V\\> loHead = null, loTail = null;\n\nNode\\<K,V\\> hiHead = null, hiTail = null;\n\nNode\\<K,V\\> next;\n\ndo {\n\nnext = e.next;\n\nif ((e.hash \\& oldCap) == 0) {\n\nif (loTail == null)\n\nloHead = e;\n\nelse\n\nloTail.next = e;\n\nloTail = e;\n\n}\n\nelse {\n\nif (hiTail == null)\n\nhiHead = e;\n\nelse\n\nhiTail.next = e;\n\nhiTail = e;\n\n}\n\n} while ((e = next) != null);\n\nif (loTail != null) {\n\nloTail.next = null;\n\nnewTab\\[j\\] = loHead;\n\n}\n\nif (hiTail != null) {\n\nhiTail.next = null;\n\nnewTab\\[j + oldCap\\] = hiHead;\n\n}\n\n}\n\n}\n\n}\n\n}\n\nreturn newTab;\n\n}\n\n自此，问题 2 的答案也就清晰了\n\n什么时候触发扩容，扩容之后的 table.length、阀值各是多少\n\n* 当 size \\> threshold 的时候进行扩容\n\n* 扩容之后的 table.length = 旧 table.length \\* 2,\n\n* 扩容之后的 threshold = 旧 threshold \\* 2\n\n#### 问题 3、4 ：2 的 n 次幂\n\ntable 是一个数组，那么如何最快的将元素 e 放入数组 ？当然是找到元素 e 在 table 中对应的位置 index ，然后 table\\[index\\] = e; 就好了；如何找到 e 在 table 中的位置了 ？\n\n我们知道只能通过数组下标（索引）操作数组，而数组的下标类型又是 int ，如果 e 是 int 类型，那好说，就直接用 e 来做数组下标（若 e \\> table.length，则可以 e % table.length 来获取下标），可 key - value 中的 key 类型不一定，所以我们需要一种统一的方式将 key 转换成 int ，最好是一个 key 对应一个唯一的 int (目前还不可能, int有范围限制，对转换方法要求也极高)，所以引入了 hash 方法\n\nstatic final int hash(Object key) {\n\nint h;\n\nreturn (key == null) ? 0 : (h = key.hashCode()) \\^ (h \\>\\>\\> 16); // 这里的处理，有兴趣的可以琢磨下；能够减少碰撞\n\n}\n\n实现 key 到 int 的转换（关于 hash，本文不展开讨论）。拿到了 key 对应的 int h 之后，我们最容易想到的对 value 的 put 和 get 操作也许如下\n\n// put\n\ntable\\[h % table.length\\] = value;\n\n// get\n\ne = table\\[h % table.length\\];  \n**自我介绍一下，小编13年上海交大毕业，曾经在小公司待过，也去过华为、OPPO等大厂，18年进入阿里一直到现在。**\n\n**深知大多数Java工程师，想要提升技能，往往是自己摸索成长或者是报班学习，但对于培训机构动则几千的学费，着实压力不小。自己不成体系的自学效果低效又漫长，而且极易碰到天花板技术停滞不前！**\n\n**因此收集整理了一份《2024年Java开发全套学习资料》，初衷也很简单，就是希望能够帮助到想自学提升又不知道该从何学起的朋友，同时减轻大家的负担。** ![img](https://i-blog.csdnimg.cn/blog_migrate/c80c92e9a042eae8346996133e15acdb.jpeg)\n\n![](https://i-blog.csdnimg.cn/blog_migrate/04175337479972ae9c0682b1cfceb1b0.png)\n\n![](https://i-blog.csdnimg.cn/blog_migrate/93901eaec622e666063310a976033676.png)\n\n**既有适合小白学习的零基础资料，也有适合3年以上经验的小伙伴深入学习提升的进阶课程，基本涵盖了95%以上Java开发知识点，真正体系化！**\n\n**由于文件比较大，这里只是将部分目录截图出来，每个节点里面都包含大厂面经、学习笔记、源码讲义、实战项目、讲解视频，并且会持续更新！**\n\n**如果你觉得这些内容对你有帮助，可以扫码获取！！（备注Java获取）**\n![img](https://i-blog.csdnimg.cn/blog_migrate/c5ec0bf6a209711c06722a69d446fc10.jpeg)\n\n最后\n---\n\n各位读者，由于本篇幅度过长，为了避免影响阅读体验，下面我就大概概括了整理了\n\n![](https://i-blog.csdnimg.cn/blog_migrate/6287297b3d1f33ebbd0bc0b657b888ba.png)\n\n![](https://i-blog.csdnimg.cn/blog_migrate/b5d93d44cb49217f54a9cd65c7e8c7c5.png)\n\n![](https://i-blog.csdnimg.cn/blog_migrate/f7606d3f94a9c73b285bebf04f43c505.png)\n\n![](https://i-blog.csdnimg.cn/blog_migrate/fab6837acf17d31bd528474a9fb4c6fe.png)\n\n**《互联网大厂面试真题解析、进阶开发核心学习笔记、全套讲解视频、实战项目源码讲义》[点击传送门即可获取！](https://bbs.csdn.net/forums/f76c2498e3b04ae99081eaf6e6cf692c)**   \n该从何学起的朋友，同时减轻大家的负担。\\*\\*\\[外链图片转存中...(img-UYdPzRtk-1713382023452)\\]\n\n\\[外链图片转存中...(img-f7BgCOIS-1713382023453)\\]\n\n\\[外链图片转存中...(img-9pgj8gWN-1713382023453)\\]\n\n**既有适合小白学习的零基础资料，也有适合3年以上经验的小伙伴深入学习提升的进阶课程，基本涵盖了95%以上Java开发知识点，真正体系化！**\n\n**由于文件比较大，这里只是将部分目录截图出来，每个节点里面都包含大厂面经、学习笔记、源码讲义、实战项目、讲解视频，并且会持续更新！**\n\n**如果你觉得这些内容对你有帮助，可以扫码获取！！（备注Java获取）**\n![img](https://i-blog.csdnimg.cn/blog_migrate/c5ec0bf6a209711c06722a69d446fc10.jpeg)\n\n最后\n---\n\n各位读者，由于本篇幅度过长，为了避免影响阅读体验，下面我就大概概括了整理了\n\n\\[外链图片转存中...(img-CElYEPzY-1713382023453)\\]\n\n\\[外链图片转存中...(img-SqlYWP0V-1713382023454)\\]\n\n\\[外链图片转存中...(img-AyM9IX1g-1713382023454)\\]\n\n\\[外链图片转存中...(img-cpooMBS2-1713382023454)\\]\n\n**《互联网大厂面试真题解析、进阶开发核心学习笔记、全套讲解视频、实战项目源码讲义》[点击传送门即可获取！](https://bbs.csdn.net/forums/f76c2498e3b04ae99081eaf6e6cf692c)**\n', 1, 0, 1, 0, 0, 0, 'https://blog.csdn.net/2401_84408337/article/details/137897867', 0, NULL, NULL, '2025-06-21 16:22:49', NULL);
INSERT INTO `sys_article` (`id`, `user_id`, `title`, `cover`, `summary`, `content`, `content_md`, `read_type`, `is_stick`, `status`, `is_original`, `is_carousel`, `is_recommend`, `original_url`, `quantity`, `keywords`, `ai_describe`, `create_time`, `update_time`) VALUES (336, 1, '开源fabric.js图片编辑器的插件化架构', 'http://sycexovyo.hn-bkt.clouddn.com//blog20250624/article-cover/14_学鹏代码小站Logo方案1.png', '开源fabric.js图片编辑器的插件化架构', '<p>大家好，我是开源图片编辑器的作者，在开发图片编辑器的过程中，因为一些功能无法扩展，出现过一次较大的重构，将整个编辑器改为了插件化的架构，<strong>经历过这次重构，规范了编辑器功能的扩展方式</strong>，解决了项目里很多重要的问题。</p>\n<p>如果你也在做类似的项目，或者对图片编辑器架构比较感兴趣，希望我的经验能给你一点点参考。</p>\n<h3><a id=\"_4\"></a>大纲</h3>\n<ol>\n<li>项目介绍</li>\n<li>为什么要做插件化</li>\n<li>如何实现插件化</li>\n<li>如何开发一个插件</li>\n</ol>\n<h3><a id=\"_11\"></a>项目介绍</h3>\n<ul>\n<li>项目地址：<a href=\"https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor\" title=\"https://github.com/ikuaitu/vue-fabric-editor\" target=\"_blank\">github.com/ikuaitu/vue…</a></li>\n<li>预览：<a href=\"https://link.juejin.cn?target=https%3A%2F%2Fikuaitu.github.io%2Fvue-fabric-editor%2F\" title=\"https://ikuaitu.github.io/vue-fabric-editor/\" target=\"_blank\">ikuaitu.github.io/vue-fabric-…</a></li>\n</ul>\n<p>项目中文名称是快图设计，英文名称为技术栈拼接的：vue-fabric-editor，使用 Vue3 + Fabric.js 开发的开源图片编辑器。</p>\n<blockquote>\n<p>Fabric.js 是业界知名的Canvas工具库，它已经12岁了，在业界得到了广泛的应用和认可，可用于开发图片编辑、物联网组态、平面设计工具等场景。</p>\n<p>本文以介绍插件架构开发经验为主题，不对Fabric.js 做过多介绍。</p>\n</blockquote>\n<h4><a id=\"_21\"></a>项目特点</h4>\n<ol>\n<li><strong>插件化架构</strong>：可通过插件的形式进行扩展，定义快捷键、右键菜单、复用的API/Event。</li>\n<li><strong>简洁易用</strong>：拖拽式设计，让普通人轻松上手操作。</li>\n<li><strong>功能完善</strong>：PSD解析、辅助线、历史记录、渐变、自定义字体、裁剪等功能，满足轻量图片编辑需求。</li>\n</ol>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/3fbb35f7d4cb4d0ab9e7b117d0c562bd~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=QvNHDjhyQ9JLQt49XLSVkRTbvsY%3D\" alt=\"Foxmail20240810085605.png\" /></p>\n<p>可应用于自媒体/海报设计、平面设计、PPT、价签设计等场景，以下为项目的实际应用截图。 <img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/ffb568dffeeb47e9a448522625890cc1~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=80V0v8RRmjPBvowSBU%2FVImeHzkE%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/1b482f9be582492ca8269f4dfe944e0a~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=sf38oBn%2BNsNDJ5qjRzC5xVUvq3g%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/32eec5493bb1477e8933d172202bda92~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=yC8ooloPVjpNyz90O3bmhcYkJnY%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/0c492ecfcef240fdb8c55f6d4d3e0e9d~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=0dvQsCJhCUhnV0AnhbXe%2BB8yKq0%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/902127e846934995885f703ccc9630ae~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=HOfLgouPOeFgxzp3WpH8oniLuzs%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/9cd32da02ed34d3ea68b10392782fc6d~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=HF9utjpUzAxJSPNBxAuv6%2Ba%2FYfg%3D\" alt=\"image.png\" /></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/5c589c35942a493fa3acfe4a0266a3c4~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=NZ8hIMkc0EaZjonoUZn2d4GizNU%3D\" alt=\"image.png\" /></p>\n<h3><a id=\"_43\"></a>为什么要做插件化</h3>\n<p>项目最初使用vue2 + Fabric.js 开发，通过使用Vue2的 Provide/Inject 的 API方法，将Fabric.js 的 canvas对象注入到各个子组件当中。</p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/daa418f4f3f84e4183118b294fe4c25c~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=3EB%2Fp8GlVw%2BbLhXQjm1RrpH1nQE%3D\" alt=\"image.png\" /></p>\n<p>看起来好像组件各司其职，也符合满足单一职责原则，实际上隐藏着很大的问题。</p>\n<h4><a id=\"_51\"></a>问题说明</h4>\n<p>如果要实现以下 2 个功能：</p>\n<ol>\n<li>画布功能需要在导入源文件时储存画布尺寸变量，需要尺寸修改的 API 方法，其他组件可订阅尺寸修改事件。</li>\n<li>自定义字体功能需要初始化时生成字体引用的 CSS 代码，需要在导入源文件前获取到所有使用的字体名称，并进行加载，加载完成后再进行源文件的的渲染。</li>\n</ol>\n<p>在没有扩展规范的情况下，很有可能出现的情况是：</p>\n<ol>\n<li>导入逻辑出现过多业务处理代码。</li>\n<li>多个组件的订阅事件出现相互依赖。</li>\n</ol>\n<p>一个功能的代码散落在各个组件中，扩展功能无规范，很多逻辑相互缠绕。</p>\n<p><strong>如果按照硬编码的方式实现，那么组件将会错综复杂，相互紧密耦合，修改一个微小功能都要梳理众多组件的影响范围。</strong></p>\n<h4><a id=\"_67\"></a>根本原因</h4>\n<p>图片编辑器不同于Canvas库，需要有自己的生命周期Hook方法、API复用方法、事件订阅、快捷键/右键菜单绑定等功能，<strong>编辑器需要有明确的扩展规范</strong>。</p>\n<p>Fabric.js是一个典型的 Canvas库，不满足也不应该处理这些需求，<strong>需要有一个原则来明确定义Canvas库与图片编辑器的关系</strong>。</p>\n<h3><a id=\"_73\"></a>如何实现插件化</h3>\n<p>要实现插件化，需要先明确关系与扩展规范，最后再按照设计去实现功能即可。</p>\n<h4><a id=\"_77\"></a>抽象分层</h4>\n<p>要解决扩展规范的问题，首先要明确编辑器与 Canvas 库的关系，用汽车来类比。</p>\n<ul>\n<li><strong>Canvas库为引擎</strong>：有很强的驱动能力，是汽车的核心，就像Fabric.js有很完善的绘制图像能力，是编辑器的核心。</li>\n<li><strong>Editor编辑器为底盘</strong>：围绕引擎在为汽车行驶提供更多功能和接口，比如方向盘驱动、轮子、减震、钥匙启动等，就像图片编辑器必要的辅助线、历史记录、右键菜单、快捷键等。</li>\n<li><strong>UI 框架为车壳</strong>：React/Vue + UI 组件就像车壳，只需要调用底盘提供的功能接口即可完成驱动。</li>\n</ul>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/7360be5de7d640228cc6a5f9e34c5eea~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=4wKQmvrC4%2BoFQfPAxRlpw8e9vnE%3D\" alt=\"image.png\" /></p>\n<p>这样的分层关系，<strong>能够让我们在开发时，更清晰的拆分功能应该放在哪里更合适</strong>，绘制能力给 Fabric.js，集成复用能力给底盘，而不是将所有逻辑一股脑的塞在组件里。</p>\n<h4><a id=\"_89\"></a>扩展规范</h4>\n<p>通过对历史逻辑的梳理，对编辑器做扩展需要生命周期Hook、API挂载、事件订阅、右键菜单扩展、快捷键绑定，一个编辑器的扩展功能应该内聚在一个文件中，而插件化架构更为合适，扩展规范也就明晰了。</p>\n<ol>\n<li>生命周期\n<ul>\n<li>导入前</li>\n<li>导入后</li>\n<li>保存前</li>\n<li>保存后</li>\n</ul>\n</li>\n<li>挂载 API</li>\n<li>事件订阅</li>\n<li>右键菜单扩展</li>\n<li>快捷键绑定</li>\n</ol>\n<p>引用插件：</p>\n<pre><code class=\"lang-hljs\">  const canvas = new fabric.Canvas(\'canvas\');\n  // 编辑器初始化\n  canvasEditor.init(canvas);\n  // 引用插件\n  canvasEditor.use(DringPlugin, { repoSrc: \'https://api.kuaitu.cc\' });\n</code></pre>\n<h4><a id=\"_113\"></a>插件化实现</h4>\n<p>接下来终于进入编码的环节，已经有很多成熟的库可以满足我们的功能需求，以下是我们用到的依赖库。</p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/54f23f82fd7e4211991b540d50f641c7~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=ljGNt4OrYboME91JNuxON5OSEaU%3D\" alt=\"image.png\" /></p>\n<h5><a id=\"1_Editor_119\"></a>1. Editor对象</h5>\n<p>负责编辑器、插件、Hook的初始化，监听右键菜单并渲染所有插件内的menu方法，监听快捷键方法并所有插件内的绑定事件，主要逻辑见截图，详细实现逻辑见代码： <a href=\"https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Fblob%2Fmain%2Fpackages%2Fcore%2FEditor.ts\" title=\"https://github.com/ikuaitu/vue-fabric-editor/blob/main/packages/core/Editor.ts\" target=\"_blank\">github.com/ikuaitu/vue…</a></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/c4e7f9e37b4e4ab699b0c29f72241f20~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=LXOVf3PVbnyA6BUiUQqtL2GsD78%3D\" alt=\"image.png\" /> <img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/fd6e35ed8fc549b0954bf1cdb3f8cca0~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=ZHAmspoF%2F94nLzLSsLaY34GkZ1o%3D\" alt=\"image.png\" /></p>\n<h5><a id=\"2__125\"></a>2. 主流程插件</h5>\n<p>ServersPlugin与其他插件不同，是作为主流程插件存在，与Editor对象同等重要，提供了Hook的顺序控制和基础API。</p>\n<p>Hook控制： <a href=\"https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Fblob%2Fmain%2Fpackages%2Fcore%2FServersPlugin.ts\" title=\"https://github.com/ikuaitu/vue-fabric-editor/blob/main/packages/core/ServersPlugin.ts\" target=\"_blank\">github.com/ikuaitu/vue…</a></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/802bb6f10eee439591ef20984d4b755e~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=N4FEi%2Fad4T6q2%2B8CEHwt2cYN2DQ%3D\" alt=\"image.png\" /></p>\n<h5><a id=\"3__133\"></a>3. 其他插件</h5>\n<p>编辑器其他插件可按需单独引入，统一放置在 plugin目录下： <a href=\"https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Ftree%2Fmain%2Fpackages%2Fcore%2Fplugin\" title=\"https://github.com/ikuaitu/vue-fabric-editor/tree/main/packages/core/plugin\" target=\"_blank\">github.com/ikuaitu/vue…</a></p>\n<p><img src=\"https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/e9f4b6c06e8b49d7870f02b8ef42abb7~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&amp;x-expires=1750635801&amp;x-signature=n8h84uRUg79WzsGrVYUV%2Fj993lw%3D\" alt=\"image.png\" /></p>\n<p>以上就是插件化的主要实现思路，具体细节逻辑可参见源码。</p>\n<h3><a id=\"_141\"></a>如何开发一个插件</h3>\n<p>插件以类的形式初始化，采用声明式编程的方式对外部暴露 API、事件、快捷键，所有需要使用的 API、事件、快捷键都需要在apis、events、hotkeys里声明。</p>\n<p>Hook方法直接在插件内部按规范命名即可：</p>\n<ul>\n<li>hookImportBefore</li>\n<li>hookImportAfter</li>\n<li>hookSaveBefore</li>\n<li>hookSaveAfter</li>\n</ul>\n<p>右键菜单可根据选中的元素类型进行判断，可增加分割线、二级菜单嵌套。</p>\n<p>快捷键的扩展可根据点击事件的 keyCode、up/down 绑定对应的方法即可。</p>\n<p>插件代码实例：</p>\n<pre><code class=\"lang-hljs\">import Editor from \'./Editor\';\ntype IEditor = Editor;\n\nclass FontPlugin {\n  public canvas: fabric.Canvas;\n  public editor: IEditor;\n  // 插件名称\n  static pluginName = \'FontPlugin\';\n  // 挂载API名称\n  static apis = [\'downFontByJSON\'];\n  // 发布事件\n  static events = [\'textEvent1\', \'textEvent2\'];\n  // 快捷键 keyCode hotkeys-js\n  public hotkeys: string[] = [\'backspace\', \'space\'];\n  // 私有属性\n  repoSrc: string;\n\n  constructor(canvas: fabric.Canvas, editor: IEditor, config: { repoSrc: string }) {\n    // 初始化\n    this.canvas = canvas;\n    this.editor = editor;\n    // 可插入外部配置\n    this.repoSrc = config.repoSrc;\n  }\n\n  // 钩子函数 hookImportAfter/hookSaveBefore/hookSaveAfter Promise\n  hookImportBefore(json: string) {\n    return this.downFontByJSON(json);\n  }\n\n  // 挂载API方法\n  downFontByJSON() {\n    //\n  }\n\n  // 私有方法 + 发布事件\n  _createFontCSS() {\n    const params = [];\n    this.editor.emit(\'textEvent1\', params);\n  }\n\n  // 右键菜单\n  contextMenu() {\n    const selectedMode = this.editor.getSelectMode();\n    if (selectedMode === SelectMode.ONE) {\n      return [\n        null, // 分割线\n        {\n          text: \'翻转\',\n          hotkey: \'❯\',\n          subitems: [\n            {\n              text: t(\'flip.x\'),\n              hotkey: \'|\',\n              onclick: () =&gt; this.flip(\'X\'),\n            },\n            {\n              text: t(\'flip.y\'),\n              hotkey: \'-\',\n              onclick: () =&gt; this.flip(\'Y\'),\n            },\n          ],\n        },\n      ];\n    }\n  }\n\n  // 快捷键\n  hotkeyEvent(eventName: string, { type }: KeyboardEvent) {\n    // eventName：hotkeys中的属性 backspace、space\n    // type：keyUp keyDown\n    // code：hotkeys-js Code\n    if (eventName === \'backspace\' &amp;&amp; type === \'keydown\') {\n      this.del();\n    }\n  }\n\n  // 注销\n  destroy() {\n    console.log(\'pluginDestroy\');\n  }\n}\n\nexport default FontPlugin;\n\n</code></pre>\n<h3><a id=\"_246\"></a>总结</h3>\n<p>开头简单介绍了项目及应用场景，重点说明图片编辑器不同于Canvas库，需要有自己的生命周期Hook方法、API复用方法、事件订阅、快捷键/右键菜单绑定等功能，硬编码会导致代码复杂度增高，<strong>编辑器需要有明确的扩展规范</strong>。</p>\n<p>之后用<strong>汽车的引擎、底盘、车壳来类比图片编辑的 Canvas库、Editor、UI 框架之间的关系</strong>，并梳理出一个插件需要的Hook/API/Event/右键菜单/快捷键扩展能力，并将插件化实现思路代码做了展示，最后展示了插件 API 的用法，并提供了示例。</p>\n<p>以上就是开源图片编辑器vue-fabric-editor项目的插件化架构实现，笔记多有疏漏，还望见谅，分享出来希望能够给大家一些参考，如果有收获希望，大家帮忙点赞收藏，评论区一起交流。</p>\n<p>如果你对这个开源项目感兴趣，欢迎你能加入我们一起维护。</p>\n', '大家好，我是开源图片编辑器的作者，在开发图片编辑器的过程中，因为一些功能无法扩展，出现过一次较大的重构，将整个编辑器改为了插件化的架构，**经历过这次重构，规范了编辑器功能的扩展方式**，解决了项目里很多重要的问题。\n\n如果你也在做类似的项目，或者对图片编辑器架构比较感兴趣，希望我的经验能给你一点点参考。\n\n### 大纲\n\n1. 项目介绍\n2. 为什么要做插件化\n3. 如何实现插件化\n4. 如何开发一个插件\n\n### 项目介绍\n\n* 项目地址：[github.com/ikuaitu/vue...](https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor \"https://github.com/ikuaitu/vue-fabric-editor\")\n* 预览：[ikuaitu.github.io/vue-fabric-...](https://link.juejin.cn?target=https%3A%2F%2Fikuaitu.github.io%2Fvue-fabric-editor%2F \"https://ikuaitu.github.io/vue-fabric-editor/\")\n\n项目中文名称是快图设计，英文名称为技术栈拼接的：vue-fabric-editor，使用 Vue3 + Fabric.js 开发的开源图片编辑器。\n> Fabric.js 是业界知名的Canvas工具库，它已经12岁了，在业界得到了广泛的应用和认可，可用于开发图片编辑、物联网组态、平面设计工具等场景。\n>\n> 本文以介绍插件架构开发经验为主题，不对Fabric.js 做过多介绍。\n\n#### 项目特点\n\n1. **插件化架构**：可通过插件的形式进行扩展，定义快捷键、右键菜单、复用的API/Event。\n2. **简洁易用**：拖拽式设计，让普通人轻松上手操作。\n3. **功能完善**：PSD解析、辅助线、历史记录、渐变、自定义字体、裁剪等功能，满足轻量图片编辑需求。\n\n![Foxmail20240810085605.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/3fbb35f7d4cb4d0ab9e7b117d0c562bd~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=QvNHDjhyQ9JLQt49XLSVkRTbvsY%3D)\n\n可应用于自媒体/海报设计、平面设计、PPT、价签设计等场景，以下为项目的实际应用截图。 ![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/ffb568dffeeb47e9a448522625890cc1~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=80V0v8RRmjPBvowSBU%2FVImeHzkE%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/1b482f9be582492ca8269f4dfe944e0a~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=sf38oBn%2BNsNDJ5qjRzC5xVUvq3g%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/32eec5493bb1477e8933d172202bda92~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=yC8ooloPVjpNyz90O3bmhcYkJnY%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/0c492ecfcef240fdb8c55f6d4d3e0e9d~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=0dvQsCJhCUhnV0AnhbXe%2BB8yKq0%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/902127e846934995885f703ccc9630ae~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=HOfLgouPOeFgxzp3WpH8oniLuzs%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/9cd32da02ed34d3ea68b10392782fc6d~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=HF9utjpUzAxJSPNBxAuv6%2Ba%2FYfg%3D)\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/5c589c35942a493fa3acfe4a0266a3c4~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=NZ8hIMkc0EaZjonoUZn2d4GizNU%3D)\n\n### 为什么要做插件化\n\n项目最初使用vue2 + Fabric.js 开发，通过使用Vue2的 Provide/Inject 的 API方法，将Fabric.js 的 canvas对象注入到各个子组件当中。\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/daa418f4f3f84e4183118b294fe4c25c~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=3EB%2Fp8GlVw%2BbLhXQjm1RrpH1nQE%3D)\n\n看起来好像组件各司其职，也符合满足单一职责原则，实际上隐藏着很大的问题。\n\n#### 问题说明\n\n如果要实现以下 2 个功能：\n\n1. 画布功能需要在导入源文件时储存画布尺寸变量，需要尺寸修改的 API 方法，其他组件可订阅尺寸修改事件。\n2. 自定义字体功能需要初始化时生成字体引用的 CSS 代码，需要在导入源文件前获取到所有使用的字体名称，并进行加载，加载完成后再进行源文件的的渲染。\n\n在没有扩展规范的情况下，很有可能出现的情况是：\n\n1. 导入逻辑出现过多业务处理代码。\n2. 多个组件的订阅事件出现相互依赖。\n\n一个功能的代码散落在各个组件中，扩展功能无规范，很多逻辑相互缠绕。\n\n**如果按照硬编码的方式实现，那么组件将会错综复杂，相互紧密耦合，修改一个微小功能都要梳理众多组件的影响范围。**\n\n#### 根本原因\n\n图片编辑器不同于Canvas库，需要有自己的生命周期Hook方法、API复用方法、事件订阅、快捷键/右键菜单绑定等功能，**编辑器需要有明确的扩展规范**。\n\nFabric.js是一个典型的 Canvas库，不满足也不应该处理这些需求，**需要有一个原则来明确定义Canvas库与图片编辑器的关系**。\n\n### 如何实现插件化\n\n要实现插件化，需要先明确关系与扩展规范，最后再按照设计去实现功能即可。\n\n#### 抽象分层\n\n要解决扩展规范的问题，首先要明确编辑器与 Canvas 库的关系，用汽车来类比。\n\n* **Canvas库为引擎**：有很强的驱动能力，是汽车的核心，就像Fabric.js有很完善的绘制图像能力，是编辑器的核心。\n* **Editor编辑器为底盘**：围绕引擎在为汽车行驶提供更多功能和接口，比如方向盘驱动、轮子、减震、钥匙启动等，就像图片编辑器必要的辅助线、历史记录、右键菜单、快捷键等。\n* **UI 框架为车壳**：React/Vue + UI 组件就像车壳，只需要调用底盘提供的功能接口即可完成驱动。\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/7360be5de7d640228cc6a5f9e34c5eea~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=4wKQmvrC4%2BoFQfPAxRlpw8e9vnE%3D)\n\n这样的分层关系，**能够让我们在开发时，更清晰的拆分功能应该放在哪里更合适**，绘制能力给 Fabric.js，集成复用能力给底盘，而不是将所有逻辑一股脑的塞在组件里。\n\n#### 扩展规范\n\n通过对历史逻辑的梳理，对编辑器做扩展需要生命周期Hook、API挂载、事件订阅、右键菜单扩展、快捷键绑定，一个编辑器的扩展功能应该内聚在一个文件中，而插件化架构更为合适，扩展规范也就明晰了。\n\n1. 生命周期\n   * 导入前\n   * 导入后\n   * 保存前\n   * 保存后\n2. 挂载 API\n3. 事件订阅\n4. 右键菜单扩展\n5. 快捷键绑定\n\n引用插件：\n\n```hljs language-js\n  const canvas = new fabric.Canvas(\'canvas\');\n  // 编辑器初始化\n  canvasEditor.init(canvas);\n  // 引用插件\n  canvasEditor.use(DringPlugin, { repoSrc: \'https://api.kuaitu.cc\' });\n```\n\n#### 插件化实现\n\n接下来终于进入编码的环节，已经有很多成熟的库可以满足我们的功能需求，以下是我们用到的依赖库。\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/54f23f82fd7e4211991b540d50f641c7~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=ljGNt4OrYboME91JNuxON5OSEaU%3D)\n\n##### 1. Editor对象\n\n负责编辑器、插件、Hook的初始化，监听右键菜单并渲染所有插件内的menu方法，监听快捷键方法并所有插件内的绑定事件，主要逻辑见截图，详细实现逻辑见代码： [github.com/ikuaitu/vue...](https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Fblob%2Fmain%2Fpackages%2Fcore%2FEditor.ts \"https://github.com/ikuaitu/vue-fabric-editor/blob/main/packages/core/Editor.ts\")\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/c4e7f9e37b4e4ab699b0c29f72241f20~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=LXOVf3PVbnyA6BUiUQqtL2GsD78%3D) ![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/fd6e35ed8fc549b0954bf1cdb3f8cca0~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=ZHAmspoF%2F94nLzLSsLaY34GkZ1o%3D)\n\n##### 2. 主流程插件\n\nServersPlugin与其他插件不同，是作为主流程插件存在，与Editor对象同等重要，提供了Hook的顺序控制和基础API。\n\nHook控制： [github.com/ikuaitu/vue...](https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Fblob%2Fmain%2Fpackages%2Fcore%2FServersPlugin.ts \"https://github.com/ikuaitu/vue-fabric-editor/blob/main/packages/core/ServersPlugin.ts\")\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/802bb6f10eee439591ef20984d4b755e~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=N4FEi%2Fad4T6q2%2B8CEHwt2cYN2DQ%3D)\n\n##### 3. 其他插件\n\n编辑器其他插件可按需单独引入，统一放置在 plugin目录下： [github.com/ikuaitu/vue...](https://link.juejin.cn?target=https%3A%2F%2Fgithub.com%2Fikuaitu%2Fvue-fabric-editor%2Ftree%2Fmain%2Fpackages%2Fcore%2Fplugin \"https://github.com/ikuaitu/vue-fabric-editor/tree/main/packages/core/plugin\")\n\n![image.png](https://p9-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/e9f4b6c06e8b49d7870f02b8ef42abb7~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg5oSa5Z2k56em5bCR5Y2r:q75.awebp?rk3s=f64ab15b&x-expires=1750635801&x-signature=n8h84uRUg79WzsGrVYUV%2Fj993lw%3D)\n\n以上就是插件化的主要实现思路，具体细节逻辑可参见源码。\n\n### 如何开发一个插件\n\n插件以类的形式初始化，采用声明式编程的方式对外部暴露 API、事件、快捷键，所有需要使用的 API、事件、快捷键都需要在apis、events、hotkeys里声明。\n\nHook方法直接在插件内部按规范命名即可：\n\n* hookImportBefore\n* hookImportAfter\n* hookSaveBefore\n* hookSaveAfter\n\n右键菜单可根据选中的元素类型进行判断，可增加分割线、二级菜单嵌套。\n\n快捷键的扩展可根据点击事件的 keyCode、up/down 绑定对应的方法即可。\n\n插件代码实例：\n\n```hljs language-JS\nimport Editor from \'./Editor\';\ntype IEditor = Editor;\n\nclass FontPlugin {\n  public canvas: fabric.Canvas;\n  public editor: IEditor;\n  // 插件名称\n  static pluginName = \'FontPlugin\';\n  // 挂载API名称\n  static apis = [\'downFontByJSON\'];\n  // 发布事件\n  static events = [\'textEvent1\', \'textEvent2\'];\n  // 快捷键 keyCode hotkeys-js\n  public hotkeys: string[] = [\'backspace\', \'space\'];\n  // 私有属性\n  repoSrc: string;\n\n  constructor(canvas: fabric.Canvas, editor: IEditor, config: { repoSrc: string }) {\n    // 初始化\n    this.canvas = canvas;\n    this.editor = editor;\n    // 可插入外部配置\n    this.repoSrc = config.repoSrc;\n  }\n\n  // 钩子函数 hookImportAfter/hookSaveBefore/hookSaveAfter Promise\n  hookImportBefore(json: string) {\n    return this.downFontByJSON(json);\n  }\n\n  // 挂载API方法\n  downFontByJSON() {\n    //\n  }\n\n  // 私有方法 + 发布事件\n  _createFontCSS() {\n    const params = [];\n    this.editor.emit(\'textEvent1\', params);\n  }\n\n  // 右键菜单\n  contextMenu() {\n    const selectedMode = this.editor.getSelectMode();\n    if (selectedMode === SelectMode.ONE) {\n      return [\n        null, // 分割线\n        {\n          text: \'翻转\',\n          hotkey: \'❯\',\n          subitems: [\n            {\n              text: t(\'flip.x\'),\n              hotkey: \'|\',\n              onclick: () => this.flip(\'X\'),\n            },\n            {\n              text: t(\'flip.y\'),\n              hotkey: \'-\',\n              onclick: () => this.flip(\'Y\'),\n            },\n          ],\n        },\n      ];\n    }\n  }\n\n  // 快捷键\n  hotkeyEvent(eventName: string, { type }: KeyboardEvent) {\n    // eventName：hotkeys中的属性 backspace、space\n    // type：keyUp keyDown\n    // code：hotkeys-js Code\n    if (eventName === \'backspace\' && type === \'keydown\') {\n      this.del();\n    }\n  }\n\n  // 注销\n  destroy() {\n    console.log(\'pluginDestroy\');\n  }\n}\n\nexport default FontPlugin;\n\n```\n\n### 总结\n\n开头简单介绍了项目及应用场景，重点说明图片编辑器不同于Canvas库，需要有自己的生命周期Hook方法、API复用方法、事件订阅、快捷键/右键菜单绑定等功能，硬编码会导致代码复杂度增高，**编辑器需要有明确的扩展规范**。\n\n之后用**汽车的引擎、底盘、车壳来类比图片编辑的 Canvas库、Editor、UI 框架之间的关系**，并梳理出一个插件需要的Hook/API/Event/右键菜单/快捷键扩展能力，并将插件化实现思路代码做了展示，最后展示了插件 API 的用法，并提供了示例。\n\n以上就是开源图片编辑器vue-fabric-editor项目的插件化架构实现，笔记多有疏漏，还望见谅，分享出来希望能够给大家一些参考，如果有收获希望，大家帮忙点赞收藏，评论区一起交流。\n\n如果你对这个开源项目感兴趣，欢迎你能加入我们一起维护。\n', 1, 1, 1, 0, 0, 0, 'https://juejin.cn/post/7401071861847949339', 0, NULL, NULL, '2025-06-21 17:06:15', '2025-06-24 16:14:31');
INSERT INTO `sys_article` (`id`, `user_id`, `title`, `cover`, `summary`, `content`, `content_md`, `read_type`, `is_stick`, `status`, `is_original`, `is_carousel`, `is_recommend`, `original_url`, `quantity`, `keywords`, `ai_describe`, `create_time`, `update_time`) VALUES (338, 1, 'Let’s Encrypt（乐此加密） 免费SSL证书申请', 'http://sycexovyo.hn-bkt.clouddn.com//blog20250626/article-cover/20_d72a6be0479f4c42a171034afba11188.jpeg', 'Let’s Encrypt（乐此加密） 免费SSL证书申请', '<h2><a id=\"_0\"></a>一、前言</h2>\n<p>腾讯云、阿里云等平台都支持免费的SSL证书申请，但只支持单域名SSL证书申请，不支持泛域名证书申请，而且每年只有20张免费证书额度，自2024年4月25日之起免费申请的证书只有3个月有效期。域名比较多的情况下，更新就变得非常麻烦。</p>\n<p>Let’s Encrypt 是一家免费、开放、自动化的公益性证书颁发机构（CA），提供免费SSL证书申请，并且支持泛域名证书申请，一个证书就能支持很多个域名，多个网站共同使用。不仅如此，它还支持证书自动续期，通过一次的定时任务设定，就可以在三个月证书到期时自动续期，达到永久使用证书的效果。</p>\n<h2><a id=\"_7\"></a>二、为什么要进行域名验证</h2>\n<p>申请SSL证书时进行域名验证的主要原因是确保证书只颁发给有权控制特定域名的实体。这是为了保证互联网的安全性和信任，防止恶意方获取不属于他们的域名的SSL证书，进而保护用户免受中间人攻击、数据窃取和其他形式的网络犯罪。</p>\n<h2><a id=\"SSL_12\"></a>三、申请SSL证书</h2>\n<p>Let’s Encrypt 网站地址：<a href=\"https://www.letsencrypt.top/\" title=\"乐此加密-免费SSL证书申请（Let\'s Encrypt）\" target=\"_blank\">乐此加密-免费SSL证书申请（Let’s Encrypt）</a></p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/46b2736af56b45eeb536fd8b9a9145d9.png\" alt=\"\" /></p>\n<h3><a id=\"1_19\"></a>1、注册账号</h3>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/f46797ff7fd943369fab2baa3797d859.png\" alt=\"\" /></p>\n<h3><a id=\"2_23\"></a>2、登录</h3>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/bb7124db50914b3cbb33bda11c31df1b.png\" alt=\"\" /></p>\n<h3><a id=\"3SSL_27\"></a>3、申请SSL证书</h3>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/1d2a18527c6f4abe91e94eaf6cf3bff5.png\" alt=\"\" /></p>\n<p>点击&quot;免费证书申请&quot; 或者 “申请证书”</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/cda6cc14bcb0483a9bbdafdf8a1180eb.png\" alt=\"\" /></p>\n<p>输入域名，可勾选泛域名，包含根域</p>\n<p>点击&quot;点击获取验证码&quot; 输入验证码后点击&quot;确定&quot;</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/9cb2ec492ca6427d8e0e3607ef3c1d16.png\" alt=\"\" /></p>\n<p>这里新手可以看一下新手必看</p>\n<p><a href=\"https://blog.csdn.net/yangjing19910801/article/details/145815648\" title=\"申请SSL证书，如何完成域名验证_51ssl怎么验证域名-CSDN博客\" target=\"_blank\">申请SSL证书，如何完成域名验证_51ssl怎么验证域名-CSDN博客文章浏览阅读3.6k次，点赞11次，收藏12次。为了网络数据传输安全，我们需要使用https协议来进行网站数据传输，这时就需要申请SSL证书。常用的SSL证书可以通过很多网站进行购买，也可以通过Let’s Encrypt来申请免费的SSL证书，使用 www.letsencrypt.top （乐此加密）网站可以快速完成免费的SSL证书申请。根据网友的反馈，发现很多人在申请SSL证书时，都卡在了完成域名验证这一操作，不太理解这个验证是怎么回事，不知如何操作。这篇文章我们就来讲一讲，在申请SSL证书时，如何完成域名验证。_51ssl怎么验证域名<img src=\"https://g.csdnimg.cn/static/logo/favicon32.ico\" alt=\"\" />https://blog.csdn.net/yangjing19910801/article/details/145815648</a>复制上面1，2,3后，保存下</p>\n<p>在到域名提供商添加解析记录，我这边是<a href=\"https://www.aliyun.com/\" title=\"阿里云-计算，为了无法计算的价值\" target=\"_blank\">阿里云-计算，为了无法计算的价值</a></p>\n<p>点击链接进去阿里云，在控制台中，找到域名</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/056f4a3a07084f099cb37a7f88ef57b8.png\" alt=\"\" /></p>\n<p>点击解析，</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/834c834acc4a442cb7c2a2b5e9ca3d8d.png\" alt=\"\" /></p>\n<p>点击添加记录</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/a029491e86ed47afbd8f87a6caf4118d.png\" alt=\"\" /></p>\n<p>回到乐此加密Let’s Encrypt（乐此加密）点击&quot;立即验证&quot;</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/946cfd2aa65b41ba95fe425dceeed855.png\" alt=\"\" /></p>\n<p>然后等待证书验证和签发，签发后列表如下</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/b2abe619c9024649ae9fafa53fb061df.png\" alt=\"\" /></p>\n<p>点击下载<br />\n<img src=\"https://i-blog.csdnimg.cn/direct/78ca4a59738b4c128188a4d5ade236cb.png\" alt=\"\" /></p>\n<p>手动部署，可以点击边上的下载，下载自己需要的证书，部署到服务器上，不知道如何部署的，可以点击边上的&quot;帮助&quot;。帮助的部署方法链接我也放到下面了，供小伙伴们阅览</p>\n<p><a href=\"https://blog.csdn.net/yangjing19910801/article/details/145416270\" title=\"Nginx或Tengine服务器配置SSL证书_tengine-3.1.0 ssl证书-CSDN博客\" target=\"_blank\">Nginx或Tengine服务器配置SSL证书_tengine-3.1.0 ssl证书-CSDN博客文章浏览阅读2.1k次，点赞19次，收藏18次。本文将全面介绍如何在Nginx或Tengine服务器配置SSL证书，具体包括下载和上传证书文件，在Nginx上配置证书文件、证书链和证书密钥等参数，以及安装证书后结果的验证。成功配置SSL证书后，您将能够通过HTTPS加密通道安全访问Nginx服务器。_tengine-3.1.0 ssl证书<img src=\"https://g.csdnimg.cn/static/logo/favicon32.ico\" alt=\"\" />https://blog.csdn.net/yangjing19910801/article/details/145416270</a><a href=\"https://blog.csdn.net/yangjing19910801/article/details/145529819\" title=\"Apache服务器安装配置SSL证书_apache ssl证书配置-CSDN博客\" target=\"_blank\">Apache服务器安装配置SSL证书_apache ssl证书配置-CSDN博客文章浏览阅读1.7k次，点赞24次，收藏14次。本文介绍如何在Apache服务器配置单域名或多域名以及通配符域名的SSL证书。成功配置SSL证书后，您将能通过HTTPS加密通道安全访问Apache服务器，确保数据传输的安全性。_apache ssl证书配置<img src=\"https://g.csdnimg.cn/static/logo/favicon32.ico\" alt=\"\" />https://blog.csdn.net/yangjing19910801/article/details/145529819</a><a href=\"https://blog.csdn.net/yangjing19910801/article/details/145530746\" title=\"Tomcat服务器安装SSL证书_乐此加密-CSDN博客\" target=\"_blank\">Tomcat服务器安装SSL证书_乐此加密-CSDN博客文章浏览阅读1.4k次，点赞21次，收藏5次。本文介绍了在Tomcat服务器上配置PFX（也称为PKCS12）格式SSL证书的方法，包括证书文件的下载与上传、配置证书参数及安装后的验证步骤。完成配置后，用户可通过HTTPS协议安全访问Tomcat服务器，保障数据传输的安全。_乐此加密<img src=\"https://g.csdnimg.cn/static/logo/favicon32.ico\" alt=\"\" />https://blog.csdn.net/yangjing19910801/article/details/145530746</a><a href=\"https://letsencrypt.top/pages/iis-ssl-guide.html\" title=\"IIS服务器SSL证书安装指南 | 乐此加密\" target=\"_blank\">IIS服务器SSL证书安装指南 | 乐此加密【2025最新版】逐步指导在Windows Server的IIS 10/11上安装SSL证书，包含PFX导入、证书绑定、URL重写规则配置及自动续期解决方案<img src=\"https://csdnimg.cn/release/blog_editor_html/release2.3.8/ckeditor/plugins/CsdnLink/icons/icon-default.png?t=P1C7\" alt=\"\" />https://letsencrypt.top/pages/iis-ssl-guide.html</a>这里就部署完成了</p>\n<h2><a id=\"_74\"></a>四、一键部署&amp;自动续期</h2>\n<p>这里免费证书是3个月期限，有效期到，我们就要手动更换证书，这个比较麻烦，特别一些健忘的小伙伴可能会忘记3个月有效期，导致系统无法访问，客户体验不好。</p>\n<p>如果我们的服务器联网了，就可以试一下&quot;一键部署&amp;自动续期&quot;，没有联网，就只能手动了哈</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/4ff04584855846c882366aa379e848b1.png\" alt=\"\" /></p>\n<p>点击&quot;自动续费&quot;</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/775e3bf711fc4e6ba772467a114d2f48.png\" alt=\"\" /></p>\n<p>选择，服务器类型，操作系统，输入地址和命令</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/ab43b16ccd1c41e9bb0a678f6ba9638a.png\" alt=\"\" /></p>\n<p>nginx.bat 代码 控制nginx重新加载</p>\n<pre><div class=\"hljs\"><code class=\"lang-bash\">@<span class=\"hljs-built_in\">echo</span> off\nsetlocal enabledelayedexpansion\n\n:: 设置 Nginx 安装路径（请修改为你的实际路径）\n<span class=\"hljs-built_in\">set</span> <span class=\"hljs-string\">&quot;NGINX_PATH=D:\\nginx-1.19.7&quot;</span>\n<span class=\"hljs-built_in\">set</span> <span class=\"hljs-string\">&quot;NGINX_EXE=%NGINX_PATH%\\nginx.exe&quot;</span>\n<span class=\"hljs-built_in\">set</span> <span class=\"hljs-string\">&quot;PID_FILE=%NGINX_PATH%\\logs\\nginx.pid&quot;</span>\n\n<span class=\"hljs-built_in\">echo</span> 正在检查 Nginx 状态...\n\n:: 方法1：检查进程是否存在\ntasklist /FI <span class=\"hljs-string\">&quot;IMAGENAME eq nginx.exe&quot;</span> 2&gt;NUL | find /I /N <span class=\"hljs-string\">&quot;nginx.exe&quot;</span>&gt;NUL\n<span class=\"hljs-keyword\">if</span> <span class=\"hljs-string\">&quot;%ERRORLEVEL%&quot;</span>==<span class=\"hljs-string\">&quot;0&quot;</span> (\n    <span class=\"hljs-built_in\">echo</span> Nginx 正在运行，准备重启...\n    <span class=\"hljs-string\">&quot;%NGINX_EXE%&quot;</span> -s reload\n    <span class=\"hljs-keyword\">if</span> <span class=\"hljs-string\">&quot;%ERRORLEVEL%&quot;</span>==<span class=\"hljs-string\">&quot;0&quot;</span> (\n        <span class=\"hljs-built_in\">echo</span> Nginx 重启成功！\n    ) <span class=\"hljs-keyword\">else</span> (\n        <span class=\"hljs-built_in\">echo</span> Nginx 重启失败，请检查配置或权限。\n    )\n) <span class=\"hljs-keyword\">else</span> (\n    <span class=\"hljs-built_in\">echo</span> Nginx 未运行，准备启动...\n    start <span class=\"hljs-string\">&quot;&quot;</span> <span class=\"hljs-string\">&quot;%NGINX_EXE%&quot;</span>\n    <span class=\"hljs-keyword\">if</span> <span class=\"hljs-string\">&quot;%ERRORLEVEL%&quot;</span>==<span class=\"hljs-string\">&quot;0&quot;</span> (\n        <span class=\"hljs-built_in\">echo</span> Nginx 启动成功！\n    ) <span class=\"hljs-keyword\">else</span> (\n        <span class=\"hljs-built_in\">echo</span> Nginx 启动失败，请检查配置或权限。\n    )\n)\n\npause\n</code></div></pre>\n<p>执行部署</p>\n<p>点击复制上一步生成的证书部署脚本，到我们的服务器上粘贴执行，即可自动完成证书部署。</p>\n<p>命令</p>\n<pre><div class=\"hljs\"><code class=\"lang-bash\">New-Item -ItemType Directory -Force -Path <span class=\"hljs-string\">&quot;C:\\LetsEncrypt&quot;</span>\nInvoke-WebRequest -Uri <span class=\"hljs-string\">&quot;https://letsencrypt.top/download/letsencrypt-renew.exe&quot;</span> -OutFile <span class=\"hljs-string\">&quot;C:\\LetsEncrypt\\letsencrypt-renew.exe&quot;</span>\n<span class=\"hljs-variable\">$command</span> = @<span class=\"hljs-string\">&#x27;\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=&quot;NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a&quot;  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=&quot;D:\\nginx-1.19.7\\nginx.bat&quot; -backup=true &gt;&gt; C:\\Renew.log 2&gt;&amp;1\n&#x27;</span>@\n<span class=\"hljs-variable\">$command</span> | Set-Content -Path C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat -Encoding ASCII\nschtasks /Create /TN <span class=\"hljs-string\">&quot;SslRenewTask-nginx-hfits.com.cn&quot;</span> /TR <span class=\"hljs-string\">&quot;C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat&quot;</span>  /SC DAILY /MO 15 /ST 03:28 /SD 2025/01/01 /ED 9999/12/31 /RL HIGHEST /RU <span class=\"hljs-string\">&quot;NT AUTHORITY\\SYSTEM&quot;</span> /F\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -<span class=\"hljs-built_in\">command</span>=<span class=\"hljs-string\">&quot;D:\\nginx-1.19.7\\nginx.bat&quot;</span> -backup=<span class=\"hljs-literal\">true</span> \n</code></div></pre>\n<p>执行报错</p>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/ce3b18c65609454db42dbbcd47133197.png\" alt=\"\" /></p>\n<p>这里说的可能是 PowerShell 版本过低。升级PowerShell或者修改命令</p>\n<p>我这边版本过低了，又不想升级服务器的PowerShell 所以换了下载命令，curl 这个需要额外安装和配置环境变量</p>\n<p>curl下载地址：<a href=\"https://curl.se/windows/\" title=\"curl for Windows\" target=\"_blank\">curl for Windows</a></p>\n<ol>\n<li><strong>下载 cURL 程序</strong> ：\n<ul>\n<li>访问 cURL 官方网站的 <a href=\"https://curl.se/windows/\" title=\"Windows 下载页面\" target=\"_blank\">Windows 下载页面</a> 。</li>\n<li>根据系统位数（32 位或 64 位）选择对应的版本，一般下载 64 位的 <code>Win64 - Generic</code> 版本（如果不确定系统位数，可在 “我的电脑” 上右键 - “属性” 查看）。</li>\n<li>下载得到一个压缩包（如 <code>curl-8.8.0_2-win64-mingw.zip</code> 类似名称 ）。</li>\n</ul>\n</li>\n<li><strong>解压与配置</strong> ：\n<ul>\n<li>将下载的压缩包解压到一个目录，比如 <code>C:\\curl</code> 。</li>\n<li>配置系统环境变量：\n<ul>\n<li>右键 “我的电脑” - “属性” - “高级系统设置” - “环境变量” 。</li>\n<li>在 “系统变量” 中找到 “Path” 变量，点击 “编辑” 。</li>\n<li>点击 “新建”，输入 <code>C:\\curl\\bin</code>（即你解压后 <code>curl.exe</code> 所在的 <code>bin</code> 目录路径 ），然后点击 “确定” 保存。</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>验证安装</strong> ：\n<ul>\n<li>打开新的 PowerShell 或命令提示符窗口，输入 <code>curl --version</code> ，如果能显示 cURL 的版本信息，说明安装配置成功。</li>\n</ul>\n</li>\n</ol>\n<pre><div class=\"hljs\"><code class=\"lang-bash\">New-Item -ItemType Directory -Force -Path <span class=\"hljs-string\">&quot;C:\\LetsEncrypt&quot;</span>\ncurl -o C:\\LetsEncrypt\\letsencrypt-renew.exe https://letsencrypt.top/download/letsencrypt-renew.exe\n<span class=\"hljs-variable\">$command</span> = @<span class=\"hljs-string\">&#x27;\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=&quot;NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a&quot;  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=&quot;D:\\nginx-1.19.7\\nginx.bat&quot; -backup=true &gt;&gt; C:\\Renew.log 2&gt;&amp;1\n&#x27;</span>@\n<span class=\"hljs-variable\">$command</span> | Set-Content -Path C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat -Encoding ASCII\nschtasks /Create /TN <span class=\"hljs-string\">&quot;SslRenewTask-nginx-hfits.com.cn&quot;</span> /TR <span class=\"hljs-string\">&quot;C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat&quot;</span>  /SC DAILY /MO 15 /ST 03:28 /SD 2025/01/01 /ED 9999/12/31 /RL HIGHEST /RU <span class=\"hljs-string\">&quot;NT AUTHORITY\\SYSTEM&quot;</span> /F\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -<span class=\"hljs-built_in\">command</span>=<span class=\"hljs-string\">&quot;D:\\nginx-1.19.7\\nginx.bat&quot;</span> -backup=<span class=\"hljs-literal\">true</span> \n</code></div></pre>\n<p><img src=\"https://i-blog.csdnimg.cn/direct/c38a425a52c344bc8b6177fe1d7e0ece.png\" alt=\"\" /></p>\n<p>ok 运行成功了吧</p>\n<p>参考：<a href=\"https://blog.csdn.net/yangjing19910801/article/details/145531466\" title=\"https://blog.csdn.net/yangjing19910801/article/details/145531466\" target=\"_blank\">https://blog.csdn.net/yangjing19910801/article/details/145531466文章浏览阅读8k次，点赞38次，收藏46次。腾讯云、阿里云等平台都支持免费的SSL证书申请，但只支持单域名SSL证书申请，不支持泛域名证书申请，而且每年只有20张免费证书额度，自2024年4月25日之起免费申请的证书只有3个月有效期。域名比较多的情况下，更新就变得非常麻烦。Let’s Encrypt 是一家免费、开放、自动化的公益性证书颁发机构（CA），提供免费SSL证书申请，并且支持泛域名证书申请，一个证书就能支持很多个域名，多个网站共同使用。不仅如此，它还支持证书自动续期，通过一次的定时任务设定，就可以在三个月证书到期时自动续期。。_let’s encrypt<img src=\"https://g.csdnimg.cn/static/logo/favicon32.ico\" alt=\"\" />https://blog.csdn.net/yangjing19910801/article/details/145531466</a></p>\n<p><a href=\"https://blog.csdn.net/yangjing19910801/article/details/145815648\" title=\"（新手必看） 如何完成域名验证？\" target=\"_blank\">（新手必看） 如何完成域名验证？</a></p>\n', '一、前言\n----\n\n腾讯云、阿里云等平台都支持免费的SSL证书申请，但只支持单域名SSL证书申请，不支持泛域名证书申请，而且每年只有20张免费证书额度，自2024年4月25日之起免费申请的证书只有3个月有效期。域名比较多的情况下，更新就变得非常麻烦。\n\nLet\'s Encrypt 是一家免费、开放、自动化的公益性证书颁发机构（CA），提供免费SSL证书申请，并且支持泛域名证书申请，一个证书就能支持很多个域名，多个网站共同使用。不仅如此，它还支持证书自动续期，通过一次的定时任务设定，就可以在三个月证书到期时自动续期，达到永久使用证书的效果。\n\n二、为什么要进行域名验证\n------------\n\n申请SSL证书时进行域名验证的主要原因是确保证书只颁发给有权控制特定域名的实体。这是为了保证互联网的安全性和信任，防止恶意方获取不属于他们的域名的SSL证书，进而保护用户免受中间人攻击、数据窃取和其他形式的网络犯罪。\n\n三、申请SSL证书\n---------\n\nLet\'s Encrypt 网站地址：[乐此加密-免费SSL证书申请（Let\'s Encrypt）](https://www.letsencrypt.top/ \"乐此加密-免费SSL证书申请（Let\'s Encrypt）\")\n\n![](https://i-blog.csdnimg.cn/direct/46b2736af56b45eeb536fd8b9a9145d9.png)\n\n### 1、注册账号\n\n![](https://i-blog.csdnimg.cn/direct/f46797ff7fd943369fab2baa3797d859.png)\n\n### 2、登录\n\n![](https://i-blog.csdnimg.cn/direct/bb7124db50914b3cbb33bda11c31df1b.png)\n\n### 3、申请SSL证书\n\n![](https://i-blog.csdnimg.cn/direct/1d2a18527c6f4abe91e94eaf6cf3bff5.png)\n\n点击\"免费证书申请\" 或者 \"申请证书\"\n\n![](https://i-blog.csdnimg.cn/direct/cda6cc14bcb0483a9bbdafdf8a1180eb.png)\n\n输入域名，可勾选泛域名，包含根域\n\n点击\"点击获取验证码\" 输入验证码后点击\"确定\"\n\n![](https://i-blog.csdnimg.cn/direct/9cb2ec492ca6427d8e0e3607ef3c1d16.png)\n\n这里新手可以看一下新手必看\n\n[申请SSL证书，如何完成域名验证_51ssl怎么验证域名-CSDN博客文章浏览阅读3.6k次，点赞11次，收藏12次。为了网络数据传输安全，我们需要使用https协议来进行网站数据传输，这时就需要申请SSL证书。常用的SSL证书可以通过很多网站进行购买，也可以通过Let\'s Encrypt来申请免费的SSL证书，使用 www.letsencrypt.top （乐此加密）网站可以快速完成免费的SSL证书申请。根据网友的反馈，发现很多人在申请SSL证书时，都卡在了完成域名验证这一操作，不太理解这个验证是怎么回事，不知如何操作。这篇文章我们就来讲一讲，在申请SSL证书时，如何完成域名验证。_51ssl怎么验证域名![](https://g.csdnimg.cn/static/logo/favicon32.ico)https://blog.csdn.net/yangjing19910801/article/details/145815648](https://blog.csdn.net/yangjing19910801/article/details/145815648 \"申请SSL证书，如何完成域名验证_51ssl怎么验证域名-CSDN博客\")复制上面1，2,3后，保存下\n\n在到域名提供商添加解析记录，我这边是[阿里云-计算，为了无法计算的价值](https://www.aliyun.com/ \"阿里云-计算，为了无法计算的价值\")\n\n点击链接进去阿里云，在控制台中，找到域名\n\n![](https://i-blog.csdnimg.cn/direct/056f4a3a07084f099cb37a7f88ef57b8.png)\n\n点击解析，\n\n![](https://i-blog.csdnimg.cn/direct/834c834acc4a442cb7c2a2b5e9ca3d8d.png)\n\n点击添加记录\n\n![](https://i-blog.csdnimg.cn/direct/a029491e86ed47afbd8f87a6caf4118d.png)\n\n回到乐此加密Let\'s Encrypt（乐此加密）点击\"立即验证\"\n\n![](https://i-blog.csdnimg.cn/direct/946cfd2aa65b41ba95fe425dceeed855.png)\n\n然后等待证书验证和签发，签发后列表如下\n\n![](https://i-blog.csdnimg.cn/direct/b2abe619c9024649ae9fafa53fb061df.png)\n\n点击下载  \n![](https://i-blog.csdnimg.cn/direct/78ca4a59738b4c128188a4d5ade236cb.png)\n\n手动部署，可以点击边上的下载，下载自己需要的证书，部署到服务器上，不知道如何部署的，可以点击边上的\"帮助\"。帮助的部署方法链接我也放到下面了，供小伙伴们阅览\n\n[Nginx或Tengine服务器配置SSL证书_tengine-3.1.0 ssl证书-CSDN博客文章浏览阅读2.1k次，点赞19次，收藏18次。本文将全面介绍如何在Nginx或Tengine服务器配置SSL证书，具体包括下载和上传证书文件，在Nginx上配置证书文件、证书链和证书密钥等参数，以及安装证书后结果的验证。成功配置SSL证书后，您将能够通过HTTPS加密通道安全访问Nginx服务器。_tengine-3.1.0 ssl证书![](https://g.csdnimg.cn/static/logo/favicon32.ico)https://blog.csdn.net/yangjing19910801/article/details/145416270](https://blog.csdn.net/yangjing19910801/article/details/145416270 \"Nginx或Tengine服务器配置SSL证书_tengine-3.1.0 ssl证书-CSDN博客\")[Apache服务器安装配置SSL证书_apache ssl证书配置-CSDN博客文章浏览阅读1.7k次，点赞24次，收藏14次。本文介绍如何在Apache服务器配置单域名或多域名以及通配符域名的SSL证书。成功配置SSL证书后，您将能通过HTTPS加密通道安全访问Apache服务器，确保数据传输的安全性。_apache ssl证书配置![](https://g.csdnimg.cn/static/logo/favicon32.ico)https://blog.csdn.net/yangjing19910801/article/details/145529819](https://blog.csdn.net/yangjing19910801/article/details/145529819 \"Apache服务器安装配置SSL证书_apache ssl证书配置-CSDN博客\")[Tomcat服务器安装SSL证书_乐此加密-CSDN博客文章浏览阅读1.4k次，点赞21次，收藏5次。本文介绍了在Tomcat服务器上配置PFX（也称为PKCS12）格式SSL证书的方法，包括证书文件的下载与上传、配置证书参数及安装后的验证步骤。完成配置后，用户可通过HTTPS协议安全访问Tomcat服务器，保障数据传输的安全。_乐此加密![](https://g.csdnimg.cn/static/logo/favicon32.ico)https://blog.csdn.net/yangjing19910801/article/details/145530746](https://blog.csdn.net/yangjing19910801/article/details/145530746 \"Tomcat服务器安装SSL证书_乐此加密-CSDN博客\")[IIS服务器SSL证书安装指南 \\| 乐此加密【2025最新版】逐步指导在Windows Server的IIS 10/11上安装SSL证书，包含PFX导入、证书绑定、URL重写规则配置及自动续期解决方案![](https://csdnimg.cn/release/blog_editor_html/release2.3.8/ckeditor/plugins/CsdnLink/icons/icon-default.png?t=P1C7)https://letsencrypt.top/pages/iis-ssl-guide.html](https://letsencrypt.top/pages/iis-ssl-guide.html \"IIS服务器SSL证书安装指南 | 乐此加密\")这里就部署完成了\n\n四、一键部署\\&自动续期\n------------\n\n这里免费证书是3个月期限，有效期到，我们就要手动更换证书，这个比较麻烦，特别一些健忘的小伙伴可能会忘记3个月有效期，导致系统无法访问，客户体验不好。\n\n如果我们的服务器联网了，就可以试一下\"一键部署\\&自动续期\"，没有联网，就只能手动了哈\n\n![](https://i-blog.csdnimg.cn/direct/4ff04584855846c882366aa379e848b1.png)\n\n点击\"自动续费\"\n\n![](https://i-blog.csdnimg.cn/direct/775e3bf711fc4e6ba772467a114d2f48.png)\n\n选择，服务器类型，操作系统，输入地址和命令\n\n![](https://i-blog.csdnimg.cn/direct/ab43b16ccd1c41e9bb0a678f6ba9638a.png)\n\nnginx.bat 代码 控制nginx重新加载\n\n```bash\n@echo off\nsetlocal enabledelayedexpansion\n\n:: 设置 Nginx 安装路径（请修改为你的实际路径）\nset \"NGINX_PATH=D:\\nginx-1.19.7\"\nset \"NGINX_EXE=%NGINX_PATH%\\nginx.exe\"\nset \"PID_FILE=%NGINX_PATH%\\logs\\nginx.pid\"\n\necho 正在检查 Nginx 状态...\n\n:: 方法1：检查进程是否存在\ntasklist /FI \"IMAGENAME eq nginx.exe\" 2>NUL | find /I /N \"nginx.exe\">NUL\nif \"%ERRORLEVEL%\"==\"0\" (\n    echo Nginx 正在运行，准备重启...\n    \"%NGINX_EXE%\" -s reload\n    if \"%ERRORLEVEL%\"==\"0\" (\n        echo Nginx 重启成功！\n    ) else (\n        echo Nginx 重启失败，请检查配置或权限。\n    )\n) else (\n    echo Nginx 未运行，准备启动...\n    start \"\" \"%NGINX_EXE%\"\n    if \"%ERRORLEVEL%\"==\"0\" (\n        echo Nginx 启动成功！\n    ) else (\n        echo Nginx 启动失败，请检查配置或权限。\n    )\n)\n\npause\n```\n\n执行部署\n\n点击复制上一步生成的证书部署脚本，到我们的服务器上粘贴执行，即可自动完成证书部署。\n\n命令\n\n```bash\nNew-Item -ItemType Directory -Force -Path \"C:\\LetsEncrypt\"\nInvoke-WebRequest -Uri \"https://letsencrypt.top/download/letsencrypt-renew.exe\" -OutFile \"C:\\LetsEncrypt\\letsencrypt-renew.exe\"\n$command = @\'\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=\"NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a\"  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=\"D:\\nginx-1.19.7\\nginx.bat\" -backup=true >> C:\\Renew.log 2>&1\n\'@\n$command | Set-Content -Path C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat -Encoding ASCII\nschtasks /Create /TN \"SslRenewTask-nginx-hfits.com.cn\" /TR \"C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat\"  /SC DAILY /MO 15 /ST 03:28 /SD 2025/01/01 /ED 9999/12/31 /RL HIGHEST /RU \"NT AUTHORITY\\SYSTEM\" /F\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=\"D:\\nginx-1.19.7\\nginx.bat\" -backup=true \n```\n\n执行报错\n\n![](https://i-blog.csdnimg.cn/direct/ce3b18c65609454db42dbbcd47133197.png)\n\n这里说的可能是 PowerShell 版本过低。升级PowerShell或者修改命令\n\n我这边版本过低了，又不想升级服务器的PowerShell 所以换了下载命令，curl 这个需要额外安装和配置环境变量\n\ncurl下载地址：[curl for Windows](https://curl.se/windows/ \"curl for Windows\")\n\n1. **下载 cURL 程序** ：\n   * 访问 cURL 官方网站的 [Windows 下载页面](https://curl.se/windows/ \"Windows 下载页面\") 。\n   * 根据系统位数（32 位或 64 位）选择对应的版本，一般下载 64 位的 `Win64 - Generic` 版本（如果不确定系统位数，可在 \"我的电脑\" 上右键 - \"属性\" 查看）。\n   * 下载得到一个压缩包（如 `curl-8.8.0_2-win64-mingw.zip` 类似名称 ）。\n2. **解压与配置** ：\n   * 将下载的压缩包解压到一个目录，比如 `C:\\curl` 。\n   * 配置系统环境变量：\n     * 右键 \"我的电脑\" - \"属性\" - \"高级系统设置\" - \"环境变量\" 。\n     * 在 \"系统变量\" 中找到 \"Path\" 变量，点击 \"编辑\" 。\n     * 点击 \"新建\"，输入 `C:\\curl\\bin`（即你解压后 `curl.exe` 所在的 `bin` 目录路径 ），然后点击 \"确定\" 保存。\n3. **验证安装** ：\n   * 打开新的 PowerShell 或命令提示符窗口，输入 `curl --version` ，如果能显示 cURL 的版本信息，说明安装配置成功。\n\n```bash\nNew-Item -ItemType Directory -Force -Path \"C:\\LetsEncrypt\"\ncurl -o C:\\LetsEncrypt\\letsencrypt-renew.exe https://letsencrypt.top/download/letsencrypt-renew.exe\n$command = @\'\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=\"NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a\"  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=\"D:\\nginx-1.19.7\\nginx.bat\" -backup=true >> C:\\Renew.log 2>&1\n\'@\n$command | Set-Content -Path C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat -Encoding ASCII\nschtasks /Create /TN \"SslRenewTask-nginx-hfits.com.cn\" /TR \"C:\\LetsEncrypt\\SslRenewTask-nginx-hfits.com.cn.bat\"  /SC DAILY /MO 15 /ST 03:28 /SD 2025/01/01 /ED 9999/12/31 /RL HIGHEST /RU \"NT AUTHORITY\\SYSTEM\" /F\nC:\\LetsEncrypt\\letsencrypt-renew.exe -token=NvdRIywm9KbjKTk5Vn7Hkdw2/NSQoaqhJJAPrwGrV9pUpqhCvugGdRR/uYzq593a  -key_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_private.key  -server_type=nginx  -cert_path=D:\\nginx-1.19.7\\cert\\hfits.com.cn_certificate.pem  -command=\"D:\\nginx-1.19.7\\nginx.bat\" -backup=true \n```\n\n![](https://i-blog.csdnimg.cn/direct/c38a425a52c344bc8b6177fe1d7e0ece.png)\n\nok 运行成功了吧\n\n参考：[https://blog.csdn.net/yangjing19910801/article/details/145531466文章浏览阅读8k次，点赞38次，收藏46次。腾讯云、阿里云等平台都支持免费的SSL证书申请，但只支持单域名SSL证书申请，不支持泛域名证书申请，而且每年只有20张免费证书额度，自2024年4月25日之起免费申请的证书只有3个月有效期。域名比较多的情况下，更新就变得非常麻烦。Let\'s Encrypt 是一家免费、开放、自动化的公益性证书颁发机构（CA），提供免费SSL证书申请，并且支持泛域名证书申请，一个证书就能支持很多个域名，多个网站共同使用。不仅如此，它还支持证书自动续期，通过一次的定时任务设定，就可以在三个月证书到期时自动续期。。_let\'s encrypt![](https://g.csdnimg.cn/static/logo/favicon32.ico)https://blog.csdn.net/yangjing19910801/article/details/145531466](https://blog.csdn.net/yangjing19910801/article/details/145531466 \"https://blog.csdn.net/yangjing19910801/article/details/145531466\")\n\n[（新手必看） 如何完成域名验证？](https://blog.csdn.net/yangjing19910801/article/details/145815648 \"（新手必看） 如何完成域名验证？\")\n', 1, 1, 1, 0, 0, 1, 'https://blog.csdn.net/qq_40147106/article/details/148634965', 0, NULL, NULL, '2025-06-26 11:35:24', '2025-06-26 11:36:09');
COMMIT;

