-- ----------------------------
-- Table structure for sys_web_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_web_config`;
CREATE TABLE `sys_web_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `logo` varchar(255) NOT NULL COMMENT 'logo(文件UID)',
  `name` varchar(100) NOT NULL COMMENT '网站名称',
  `summary` varchar(255) NOT NULL COMMENT '介绍',
  `record_num` varchar(100) NOT NULL COMMENT '备案号',
  `web_url` varchar(255) DEFAULT NULL COMMENT '网站地址',
  `author` varchar(100) NOT NULL COMMENT '作者',
  `author_info` varchar(100) DEFAULT NULL COMMENT '个性签名',
  `author_avatar` varchar(255) DEFAULT NULL COMMENT '作者头像',
  `ali_pay` varchar(255) DEFAULT NULL COMMENT '支付宝收款码',
  `weixin_pay` varchar(150) DEFAULT NULL COMMENT '微信收款码',
  `github` varchar(255) DEFAULT NULL COMMENT 'github地址',
  `gitee` varchar(255) DEFAULT NULL COMMENT 'gitee地址',
  `qq_number` varchar(20) DEFAULT NULL COMMENT 'QQ号',
  `qq_group` varchar(50) DEFAULT NULL COMMENT 'QQ群',
  `email` varchar(255) DEFAULT NULL COMMENT '邮箱',
  `wechat` varchar(100) DEFAULT NULL COMMENT '微信',
  `show_list` varchar(255) DEFAULT NULL COMMENT '显示的列表（用于控制邮箱、QQ、QQ群、Github、Gitee、微信是否显示在前端）',
  `login_type_list` varchar(255) DEFAULT NULL COMMENT '登录方式列表（用于控制前端登录方式，如账号密码,码云,Github,QQ,微信）',
  `open_comment` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启评论(0:否 1:是)',
  `open_admiration` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启赞赏(0:否， 1:是)',
  `tourist_avatar` varchar(255) DEFAULT NULL COMMENT '游客头像',
  `bulletin` varchar(255) DEFAULT NULL COMMENT '公告',
  `about_me` mediumtext COMMENT '关于我',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `open_lantern` int DEFAULT NULL COMMENT '开启灯笼',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='网站配置表';

-- ----------------------------
-- Records of sys_web_config
-- ----------------------------
BEGIN;
INSERT INTO `sys_web_config` (`id`, `logo`, `name`, `summary`, `record_num`, `web_url`, `author`, `author_info`, `author_avatar`, `ali_pay`, `weixin_pay`, `github`, `gitee`, `qq_number`, `qq_group`, `email`, `wechat`, `show_list`, `login_type_list`, `open_comment`, `open_admiration`, `tourist_avatar`, `bulletin`, `about_me`, `create_time`, `update_time`, `open_lantern`) VALUES (1, 'https://img.hexp.online//blog20250627/default/67_pay-qrcode.png', '小何个人站', '一个专注于技术分享的博客平台', '皖ICP备2025089684号', 'https://www.hexp.com', '小何', '发财发财发财', 'https://img.hexp.online//blog20250627/default/44_pay-qrcode.png', NULL, NULL, 'https://github.com/0xHXP', 'https://gitee.com/xuepeng-he', '2497754747', '2497754747', '2497754747@qq.com', '18130354809', '[\"qq\",\"wechat\",\"qqGroup\",\"email\"]', '[\"qq\",\"gitee\",\"github\"]', 1, 0, 'http://sycexovyo.hn-bkt.clouddn.com//blog20250626/default/91_pay-qrcode.png', '有没有在长沙内推的小伙伴，卑微博主在线求职了，有的话<span style=\"color:red\">VX：1248954763</span> 联系博主', '<p style=\"text-align: start;\">你好呀！👋 我是小何，一个热爱分享的技术爱好者。这里是我的数字小窝，记录我的思考、学习和生活碎片。</p><h4 style=\"text-align: start;\">🛠 关于这个博客</h4><ul><li style=\"text-align: start;\">技术栈：由我亲手搭建</li><li style=\"text-align: start;\">内容方向：编程笔记/书影随感/生活杂谈</li><li style=\"text-align: start;\">更新频率：随缘但认真</li></ul><h4 style=\"text-align: start;\">🌱 我是谁</h4><ul><li style=\"text-align: start;\">职业：程序员</li><li style=\"text-align: start;\">技能树：敲代码、写文字、拍照片</li><li style=\"text-align: start;\">正在学习：如何写出更优雅的代码</li></ul><h4 style=\"text-align: start;\">📫 找到我</h4><ul><li style=\"text-align: start;\">GitHub：<a href=\"https://github.com/0xHXP\" target=\"_blank\">小何</a></li><li style=\"text-align: start;\">推特：@hexp97</li><li style=\"text-align: start;\">邮箱：2497754747@qq.com<br><strong>\"持续生长，保持好奇。\"</strong></li></ul>', '2024-12-22 11:55:25', '2024-12-22 11:55:25', 0);
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
